/* 令和5年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r05.committeeSessions.push(...[{"id":"r05-20230925-8","meetingId":"r05-cm09","date":"2023年9月25日","dateIso":"2023-09-25","committee":"建設委員会","time":"午前１０時００分～午後 ２時３２分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を80件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第６５号議案、令和５年度品川区一般会計補正予算（歳出 建設委員会所管分）","agenda":"第６５号議案、令和５年度品川区一般会計補正予算（歳出 建設委員会所管分）","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"リサイクルのほうで伺いたいのですけれども、今回、リサイクルを新たに拡大するということで、その目的の一つにＣＯ２削減の取組があるということで、資料には、プラスチック製衣装ケースで１１８ｔのＣＯ２削減、自転車では５９ｔ、羽毛布団では６ｔということで書いてありますが、これはどういった考え方から算出されているのかというところを伺いたいと思います。","respondent":"品川品川区清掃事務所長","answer":"紙おむつなど、いろいろリサイクルを拡大できるものも載せてありますので、そういった部分で、計画に合わせて事業を執行していきたいと考えています。","voiceIndex":7,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"ＣＯ２のところは、そうすると、焼却することによって出るＣＯ２が削減されるという考え方でいいのかどうかというところを確認させていただきたいと思います。そして、すみません。勉強不足で申し訳ないのですが、インフレスライド条項と、この後ありますけれども専決処分で行う契約金額の変更との違いは、どういった違いがあるのかという点を伺いたいと思います。","respondent":"品川品川区清掃事務所長、小川木密整備推進課長","answer":"委員のお考えどおりで、焼却した場合のＣＯ２ということで間違いございません。もう一点のご質問の、インフレスライドと契約変更の違いですが、インフレスライドにつきましては、特に物価高等の状況による理由によって、資機材もしくは労務費といったものの増加に伴って変更できるものですが。","voiceIndex":9,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"最後のインフレスライドと専決処分の違いは、つまり、そうすると、単純に物価高騰等で資材・賃金が上がっているというだけでなくて、何か契約内容の変更があるということでしょうか。","respondent":"小川木密整備推進課長","answer":"今回のインフレスライドにおける契約変更に関しましては、単純に物価関係に伴う変更の内容となっています。","voiceIndex":12,"id":"exchange-003"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、今回のインフレスライド条項で契約額を変更した理由というのですか、専決処分でやらなかった理由というのは何かあるのでしょうか。","respondent":"小川木密整備推進課長","answer":"今回は請負業者からの請求ということもあって、特に専決処分で行うといった対応ではございません。","voiceIndex":14,"id":"exchange-004"},{"speaker":"西本委員","kind":"確認","question":"西大井三丁目防災広場のところから確認したいのですが、今のご答弁の中で、国が変わって、それで東京都、そして、それに合わせて品川区ということなのですけれども、今、請負者からの希望があったということなのですけれども、どちらが先なのですか。それを請負者の方々に話をして、だから出してくださいと言ったのか。どういう流れでやってきたのかというのをお聞きしたいと思います。そこを教えてください。","respondent":"小川木密整備推進課長、品川品川区清掃事務所長","answer":"インフレスライドの流れですが、委員がおっしゃられるとおり、まずは国から、インフレスライドに対応してくださいというような内容で、各都道府県に通知・要請が来ます。それで、粗大ごみは、幾らプラスチック製品でも粗大ごみという扱いをしてしまって、リサイクルに回っていなかったというところが結構、問題になっていたというところで。","voiceIndex":17,"id":"exchange-005"},{"speaker":"西本委員","kind":"質問・要望","question":"西大井三丁目防災広場の件ですけれども、ということは、要は実態調査はどこまでやっているのですかということが、少し心配なのです。それから、分かりました。確かに粗大ごみだったのですよね。確かに出していました。自転車のほうです。なので、こういう形でリサイクルしておりますから協力してくださいという告知をしっかりしていただきたいと思いますが、その点の告知の方法を教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-006"},{"speaker":"田中委員","kind":"提案","question":"専決処分の規定は、まずは契約は１億８,０００万円未満の工事は専決処分できるし、その後の５％以内の価格変更であれば専決処分で対応できるというのが、まず大前提にあって、今回の変更を見ますと５％以内なので、本来であれば、これは専決処分の案件に入るのではないかと思うのですが、なぜここで議決を求められているかというと、そういうことではなくて、一般会計の補正予算を組まなくては。","respondent":"小川木密整備推進課長","answer":"こちら、障害者グループホームのほうの契約がかなりの金額になっているという形でございまして、議会案件という形になりますので、専決処分ではなくて、今回、補正を組ませていただいて、変更を行わせていただくといったことです。","voiceIndex":25,"id":"exchange-007"},{"speaker":"田中委員","kind":"質問・要望","question":"であれば、その辺も含めて、そういう理由から建設委員会での議決を求める案件に入っているということもご説明いただいたほうが、より理解は深まるのかと思います。そうすると、私の理解の中で言うと、今回、グループホームではなくて、単純に単独の防災広場の工事の変更という観点だけで言えば、これは専決処分で対応できたということですか。そこだけお願いします。","respondent":"小川木密整備推進課長","answer":"委員のおっしゃるとおり、単純に防災広場の整備の工事単体だけであれば、専決処分で可能です。","voiceIndex":27,"id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"それと、粗大ごみに関してなのですが、そもそも一般質問から若干こだわっておりますが、清掃事業が区に移管されて、区独自の様々な事業が行えるようになった中で、今回、粗大ごみに入ってしまっていた、プラスチック製の衣装ケースや自転車をリサイクルに回すというお話で、いい取組だと思うのですけれども、何ゆえここまでできなかったのかというのを少し疑問に感じておりますが、そこは。","respondent":"品川品川区清掃事務所長","answer":"本当に近年になって、コストも大分、低い形で処理できるような技術が、民間業者も物すごく今、進んできているかと感じているところです。そういった流れも含めて、今の時期というようなところの判断をしています。","voiceIndex":29,"id":"exchange-009"},{"speaker":"田中委員","kind":"質問","question":"城南島に行ってしまうような、まさにごみ扱いされてしまうということなので、相当手を入れないとリサイクルや再利用することができないような状況のものが多いという理解でいいのでしょうか。","respondent":"品川品川区清掃事務所長","answer":"そういうそれぞれの状態に応じた形で、リサイクルできる自転車があればリサイクルしていく。無理なものは、例えば部品を取って、ほかの自転車に使っていく。そのような活用をしながら、今回のリサイクルのところは進めていくという考え方です。","voiceIndex":31,"id":"exchange-010"},{"speaker":"田中委員","kind":"質問・要望","question":"選別、保管、積替え場所の賃料として、費用が計上されておりますが、具体的にこれはどういう場所なのか。すばらしい事業である一方で、やはり場所によってはご近隣対策ということも考えなくてはいけないような内容だと思うのですが、その辺の選定の考え方をお聞かせいただきたい。","respondent":"品川品川区清掃事務所長","answer":"この場所は現在、粗大ごみを持っていく中継所で行うようにしております。場所は城南島になりますので、まず地域に対して騒音等は考えられないかと考えています。","voiceIndex":33,"id":"exchange-011"},{"speaker":"若林委員","kind":"質問・要望","question":"違うとすれば、どういった残額なのか。そこを確認させていただきたいと思います。併せて、ほかのプラスチック衣装ケースと羽毛布団も、それぞれ６６ｔと３ｔとありますけれども、こちらは年間の総量そのままなのか、それとも、いろいろ不具合もあって、傷物もあって、そのうちの大体何％ですとか何分掛けですとか、そういうことも確認させていただきたいと思います。","respondent":"小川木密整備推進課長、品川品川区清掃事務所長","answer":"インフレスライドの対象品目のご質問ですが、こちらに関しましては、７月３日という基準日があるのですが、その７月３日時点における残工事の資材、また労務費に対して適用されるという形になってございまして、こちらは資料の。それから自転車の台数ですが、ざっくりですけれども、大体、自転車１台は２０ｋｇぐらいかと思われます。ざっくりそうやって計算しますと、大体７,５００台ぐらいではないかと考えています。","voiceIndex":36,"id":"exchange-012"},{"speaker":"田中委員","kind":"質問","question":"賛成なのですけれども、総務部の方への質疑をしないで、決を採ってしまっていいのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-013"}]},{"id":"topic-02","title":"令和５年陳情第２４号、森澤恭子区長との面談とＣ地区の視察を求める陳情","agenda":"令和５年陳情第２４号、森澤恭子区長との面談とＣ地区の視察を求める陳情","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"初めに、以前にもＣ地区の関係の陳情が出てまいりましたけれども、そのときの資料に、勉強会だけでなく、もう一つの会の記載もあったのですけれども、その記載が消えたのはなぜなのか伺いたいと思います。","respondent":"中道都市開発課長","answer":"特に勉強会となりますと、やはり地域の皆さんで話し合っていただく場という形で、区としては状況を把握はしているのですけれども、地域のごく一部の方が雑談のような形でしているところにつきましては、特段把握していないという状況です。","voiceIndex":58,"id":"exchange-014"},{"speaker":"のだて委員","kind":"質問","question":"もう一つの会のほうが何か雑談をしているというようなお話でしたけれども、そんなことはないのです。住民の皆さんが集まって真剣に、この後の生活をどうするか、この計画によって暮らしが壊されてしまうということで話をしているもので、今までは資料の中にも記載があったのです。それで、なくしたというのは、もう一方の会のほうは軽視しているということなのか伺います。","respondent":"中道都市開発課長","answer":"区は特に軽視しているということではないのですけれども、その情報が逐一、区には入ってくるものではないという認識です。","voiceIndex":60,"id":"exchange-015"},{"speaker":"のだて委員","kind":"質問・要望","question":"それで、陳情の内容をお聞きしていきたいと思うのですけれども、この陳情の中にも、今年の２月６日、３月６日、５月１５日ということで、区長あてに手紙を出したということですけれども、区でもちろんこれを受け取っていると思いますが、どういった要望があって、区としてはどういった回答をされたのか、伺いたいと思います。","respondent":"中道都市開発課長","answer":"区といたしましては、Ｃ地区の地域の皆様が、まちの現状や課題について十分、意見交換を行い、認識を共有した上で、将来どのようなまちにしていくのか話し合っていただく段階ということ。区では、定められた事務文書に基づいて各部署が執行しております。","voiceIndex":62,"id":"exchange-016"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、地域で話し合う段階ということで対応しないというか、区長には直接話は聞いてもらえないということでしたけれども、やはり３度も手紙を出して、直接話を聞いてほしいということで求められているわけですから、この陳情にもありますとおり、区長は開かれた区政を目標にするということでやってきたということで、やはりそうしたことでは、住民の思いを直接聞くということは重要ではないかと思うので。","respondent":"中道都市開発課長","answer":"ですけれども、陳情者としましては、あまり区から直接電話をかけてほしくないというようなお話がございまして、なかなか直接お話ができる場が設けられなかったというところで、書面の回答をしたです。","voiceIndex":64,"id":"exchange-017"},{"speaker":"のだて委員","kind":"質問・要望","question":"実際、現地を見てほしいということなので、それを見ていただいて、この間、開発の計画などがあって、やはりこうしたＣ地区の陳情が出されておりますけれども、この陳情にもありますとおり、戦後７８年、その前より、お店を営んだり、住んできて、土地を守って、家を守って暮らしてきた、まちを守ってきたのだということで、そうした方々が追い出されてしまうというので、今。","respondent":"中道都市開発課長","answer":"まちづくりのご意見ですけれども、やはり、まちの方々はいろいろな意見をお持ちだということは区も認識していますので、今後もそういった話合いの場を通じて、地域の方が主体となっているまちづくりについて支援していきたいと考えています。","voiceIndex":66,"id":"exchange-018"},{"speaker":"西本委員","kind":"確認","question":"幾つか確認したいと思います。本来は、抗議文に対して都市環境部長からのお返事というのは、ぜひ見せてほしかったと思います。それがないと、何を示しているのか分からないのです。それと、区長との関係性。そういう流れになっているのは分かります。でも、区長との調整はどう取っているのですか。答えたものは、区長の了解の下で出されているという認識でよろしいでしょうか。確認させてください。","respondent":"中道都市開発課長","answer":"区民の声での回答につきましては、区長に、広報広聴課がまとめて確認しています。","voiceIndex":69,"id":"exchange-019"},{"speaker":"西本委員","kind":"確認","question":"こちらの回答文は、「こういう対応でいいですね」という確認は取られているのですか。","respondent":"中道都市開発課長","answer":"所管で作成した回答文につきまして、それで提出してもいいかどうかということを確認しています。","voiceIndex":71,"id":"exchange-020"},{"speaker":"西本委員","kind":"質問","question":"今よく分からなかったので、要は、所管で作成したものについては、きちんと事前に、質問されている方々に返す前に、区長の了解を得て出しているという認識でよろしいですか。","respondent":"中道都市開発課長","answer":"区民の声をいただいた方に提出する前に、区長に広報広聴課が、回答の書面を確認して提出しています。","voiceIndex":73,"id":"exchange-021"},{"speaker":"西本委員","kind":"質問","question":"であるならば、この抗議文に対しての返事はどういう返事だったのですか。これは本来、資料として添付してもらいたかったのですけれども、それがないので分からないので、書類はどういう回答だったのですか。","respondent":"中道都市開発課長","answer":"ですので、内容といたしましては、区民の声に書かれていた電話番号について、それは、陳情者といたしましては、区に書いた電話番号ではなくて、自分の仲間の会に書いた電話番号だということで、個人情報の取扱いについて問題はないのかというようなお話がございましたので。","voiceIndex":75,"id":"exchange-022"},{"speaker":"西本委員","kind":"質問","question":"その回答でこの陳情が出てくるとは到底思えません。なので、個人情報があるので、どこまで私たちに資料提供していただけるか分かりませんが、でも本来、こういう形で来ているとすれば、２月６日、３月６日、それから５月１５日の抗議文と回答というものを説明資料の中に出してもらわないと、内容がそこなので、判断がつかないのです。そうではないですか。判断がつかない。それを教えてください。","respondent":"中道都市開発課長","answer":"いただいた区民の声につきましては、森澤区長に視察に来ていただきたいということと、私たちの声を聞いていただきたいという内容が含まれております。","voiceIndex":77,"id":"exchange-023"},{"speaker":"西本委員","kind":"質問","question":"ということは、区長としては面談の意思はない、視察をするつもりはないということの返事ではないのですか。そう捉えて、それで、この対応は所管でやりますということでオーケーを取ったということでよろしいのでしょうか。","respondent":"中道都市開発課長","answer":"ですけれども、お相手の方が、直接お電話はというところで、そういったご対応があったので、そこの部分がなかなか、きちんと都市開発課としては考えを伝えられなかったというところは反省かと考えています。","voiceIndex":81,"id":"exchange-024"},{"speaker":"西本委員","kind":"質問","question":"今、順番が違うのだということの段階なのかと理解はしました。だけど、区民から、住民の皆さんから話をしたい、それから視察してほしいというものに対しては応えないということです。ただ、今の課長の答弁の中では、まずは担当のところで話合いをする段階だということであれば、それは理解できないわけではありませんけれども、どういう位置づけで回答されたのでしょうか。もう一度お願いします。","respondent":"中道都市開発課長","answer":"都市開発課といたしましては、今は所管で対応すべき段階という形で考えております。","voiceIndex":83,"id":"exchange-025"},{"speaker":"西本委員","kind":"質問・要望","question":"長くなるのもあれなので、まとめたいと思うのですが、やはり住民、こういう陳情がなされている方々の声をしっかり聞いてほしいのです。なぜ議会にこういうふうに上げてくるのか。それに対して、きちんと資料を用意してください。今の状況だと、判断がつかないです。ぜひ、住民の質問には答えていただきたい。そういう形にしていただきたいと、意見を申し上げて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-026"},{"speaker":"まつざわ副委員長","kind":"質問","question":"結論を出すでお願いいたします。不採択です。皆様の質疑の中で、地域で話し合う段階ということをお聞きしました。そしてまた、広報広聴課を通じて、区長もいろいろ、この件に関しては目を通しているというお話も聞いております。そういったことを踏まえ、不採択で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-027"},{"speaker":"若林委員","kind":"質問","question":"結論を出すでお願いします。今の質疑の中で、案内が届いていないということも、区からの話合いというのですか、お手紙等の中で気づかれて、今後そういう話合いの場に積極的に参加されるとも理解・認識いたしますので、結論としては不採択ということで結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-028"},{"speaker":"のだて委員","kind":"質問・要望","question":"本日結論を出すということで、採択を主張します。自分らしく暮らせるしながわを掲げる区長ですので、自分の住まいや生活を奪われる住民の切実な思いをぜひ聞いていただきたいと思いますし、実態を把握するためにも視察をしていただきたいと思いますので、採択で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":90,"id":"exchange-029"},{"speaker":"西本委員","kind":"質問・要望","question":"継続でお願いします。なので、Ｃ地区に関しましては、これから継続して、いろいろ、引き続き見守っていきたいという思いもありますので、継続という形にさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-030"},{"speaker":"田中委員","kind":"質問・要望","question":"私の態度としては、不採択です。基本的に、まちづくりは地権者の方の意向を踏まえての取組なので、行政の立場として、特にこのＣ地区においての関わりは、不燃化ということがこの地域での課題だと思いますので、不燃化をする中で、よりよい地域づくり、地権者のご意向をしっかり踏まえた中でのまちづくりに取り組むべきだと判断いたしますので、そういった意味でも不採択でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":92,"id":"exchange-031"},{"speaker":"西本委員","kind":"質問・要望","question":"お気持ちは分かるのですが、本来は資料をもう少し見たいと思いましたし、それからＣ地区の、先ほど質問もできなかったのですが、Ｃ地区丸ごとではなくて、分割していろいろ考えられないのか、いろいろな方法もあるかと思っているので、その点も理事者の方、役所の担当の方は、いろいろな方法を見つけていただいて交渉を進めていただきたいという思いがありますので、今回は不採択という形にしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-032"},{"speaker":"のだて委員","kind":"質問","question":"伺いたいのが、この間、羽田新ルートが運用を開始されて４年目に入っているということで、今年の夏も本当にひっきりなしに飛行機が飛んできて、住民の方々には被害をもたらしているという状況です。そうすると、品川区はもうすごく直近ですので、そのためには結局、どんな急旋回をしても品川区の上を飛ぶことになると私も思いますけれども、品川区としてそうは思っていないのか、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"これは、検討会が開始された令和２年６月の第１回目から、そうした前提条件の下、進められているというところで、区でももう既に認識しています。","voiceIndex":103,"id":"exchange-033"},{"speaker":"のだて委員","kind":"質問・要望","question":"区民の願いは、この新ルート、品川区の上を飛ぶのをやめてほしいということだということで、そのことについて国に要請し、撤回を交渉してほしいということですので、ぜひ、品川区として本当にそれをやるべきだと、撤回こそ求めるべきだと思いますけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"固定化回避については、その中の取組の一つとして、３年間固定化回避してきたというお話ですが、これが、区で固定化回避検討の要望を求めなければ、そのまま３年以降も長々と進められるという受け止めですので、立ち止まって。","voiceIndex":105,"id":"exchange-034"},{"speaker":"のだて委員","kind":"質問・要望","question":"区として求めなければ継続されるというお話ですけれども、国が狙っているのは恐らく、今の午後３時から７時の南風のときだけではなく、さらに時間帯を拡大し、便数を増やしていこうという狙いだと思います。そうした認識をぜひ持っていただいて、国に撤回を求めていただきたいと思いますけれども、いかがでしょうか。区として、この品川区民憲章に、今、現状が反していると考えているのか、伺います。","respondent":"鈴木都市計画課長","answer":"１点目ですが、先ほど委員から、現在、運用が開始された夕方３時から７時の４時間を超えて、さらに増便がされるような前提で行われているというお話がありましたが、国からは一切そうしたお話はございませんし、区民の方にも、そうしたお話の周知というのは我々は行っていません。","voiceIndex":107,"id":"exchange-035"},{"speaker":"のだて委員","kind":"質問","question":"その下で、やはり固定化回避検討会が実際、検討しているのは、やはり品川区の上を飛んでしまうと思うのですけれども、区ではそういった考えがないのか、改めて伺いたいと思います。それならば、憲法あるいは区民憲章で、健康で文化的な生活、あるいは健康で豊かな区民生活という状況に今なっているのか、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"繰り返しになりますが、憲法、それから区民憲章については、特に国の法律、様々、環境基本法もしかりですが、その中で運用されているですが、やはり影響が出ていると、区にも声が寄せられているですので、区としましては、国策、国の責任において進められているものですが。","voiceIndex":109,"id":"exchange-036"},{"speaker":"のだて委員","kind":"質問","question":"後方乱気流の関係のお話なのですけれども、現在でもそうした運用をすれば、国の言う増便が可能だということですけれども、この間、地上での間隔が増便できない理由になっているということなのですが、実際に飛んできているのが、２分間隔を切って飛んできているということになれば、地上でも２分を切る時間で滑走路の運用がされているということだと思うのですけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"１点目のお話ですが、繰り返しになりますが、法律の中では環境基本法や、そうした規定値の中で運用が行われているという認識ですが、やはり影響が出ていると、区民の声が寄せられているというところとして、区としては今後も。","voiceIndex":111,"id":"exchange-037"},{"speaker":"のだて委員","kind":"質問","question":"それで、後方乱気流のお話ですけれども、何度聞いても腑に落ちないのです。実際に１分半などで空から着陸してきているという下で、つまり滑走路でも１分半の間隔で運用するところがあるということだと思うのですが、それが増便につながらない、理論上もできないというのはどういうことなのか、改めて伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"これは、先ほど私もご説明しましたが、当初の国の説明の中で、１時間当たり約３０便の着陸、発着は５便程度ということで、しかも滑走路には原則１機しか存在できないですから、それを考えると、もともと２分間隔で全ての運行がされますということではなくて、それは数字上。","voiceIndex":113,"id":"exchange-038"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうしたら、アンケートは最終的な集計はまだされていないのか、答えられたら回答数を答えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":115,"id":"exchange-039"},{"speaker":"のだて委員","kind":"質問","question":"それで、滑走路の運用のところですけれども、気温や湿度によっても変わってくるということで、つまりは条件が合えば、そうした運用も可能だということなのか、つまり増便することができるのか、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"アンケートの状況は、我々は所管ではございませんで、２０日に締め切ってありますので、一定の数もありますので、今、鋭意、取りまとめが行われているというような認識です。","voiceIndex":117,"id":"exchange-040"},{"speaker":"のだて委員","kind":"意見","question":"それで、この間、様々な議論をさせていただきましたけれども、やはりこの羽田新ルートはやめるべきだと思いますので、この陳情の中にも、そうした決議を上げてほしいということで書かれておりますので、ぜひ私としては決議を上げていくべきだと思いますので、皆さんもぜひご賛同いただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":120,"id":"exchange-041"},{"speaker":"西本委員","kind":"確認","question":"確認なのですが、固定化回避検討会というものの前提として、Ａ滑走路・Ｃ滑走路を使うという前提だということは分かっているということなのですが、再度確認したいのですが、Ａ滑走路・Ｃ滑走路を使う以上は品川区の上空は通りますよね。そういう認識はおありになりますか。","respondent":"鈴木都市計画課長","answer":"陳情の中にもありますが、具体的なこのルート下のどこを通るかというのは、今、国で聞いても、まだ検討段階でお示しできないですから、これはある意味、陳情者の方と思いは同じで、国には再三再四、具体的な取組の内容。","voiceIndex":122,"id":"exchange-042"},{"speaker":"西本委員","kind":"質問","question":"今のご答弁からすると、Ａ滑走路・Ｃ滑走路の前提という形で固定化回避検討会をやっているというところまでは分かっていると思うのです。品川区の認識はどうなのか。ただ、品川区の上空も、いろいろ広いですから、どういうふうになるかは分かりませんが、必ず通りますという、専門家の皆様の見解なのです。それは、国はどうなのでしょう。品川区はどうなのでしょう。","respondent":"鈴木都市計画課長","answer":"１点目の、国が検討状況の中で、品川区上空を飛ばないようになるのか、実際飛ぶのかというところは、これは先ほど来ご説明している、具体的な運用を示していただきたいという中で、併せてお聞きしておりますが、今まさに検討している状況ですという回答です。","voiceIndex":124,"id":"exchange-043"},{"speaker":"西本委員","kind":"質問","question":"ここからなのです。そして、行政側の行動が伴っていないというところにつながってくる。品川区は、品川区の上空を回避してほしいという形で言っていますということは分かりました。でも、品川区の上空を通るということになってしまった場合には、どうするのですかということです。では、目黒区はいいのですか、大田区はいいのですかという話になってしまう。それに対してどうお考えになりますか。","respondent":"鈴木都市計画課長","answer":"先ほどからご説明しているように、今の運用が今後も何ら検討も加えられずに、このまま永久に続くことがないように、管制技術や、様々な技術進展もあろうかと思いますので、そうしたことに継続して取り組んでいただいて。","voiceIndex":126,"id":"exchange-044"},{"speaker":"西本委員","kind":"質問・要望","question":"だって、品川区の上空を通らないでほしいと求めているわけではないではないですか。なぜかといったら、品川区民の皆様方の生活に影響があるのだ」ということを住民たちは言ってほしいわけです。集計段階なので中身については話もしませんけれども、第３４号の中で都心ルート反対というのは、撤回の選択肢は入っていないということなのです。このアンケートの内容は、どなたが考えたのですか。","respondent":"鈴木都市計画課長","answer":"アンケートの内容につきましては、所管である広報広聴課、それから関係する我々、都市計画課と検討を重ね、作成し、最終的には区長が決定してきているというようなところです。","voiceIndex":128,"id":"exchange-045"},{"speaker":"西本委員","kind":"質問","question":"は区長でしょう。区民の人たち、先ほど６３０件、来ていると言って、重大だと私は受け止めていますが、その方々の意思が、この区民アンケートには表現されていないのです。非常に強く、そう思います。なので、このアンケートの結果を待ちたいとは思いますけれども、まず２つ聞きます。このアンケートを、所管としてどういう使い方をするのでしょうか。それをどう扱いますかということをお答えください。","respondent":"鈴木都市計画課長","answer":"アンケートの羽田部分についてですが、これは、町名、お住まいのところをお聞きしているというところと、それから回答のクロス集計といったところから、当初アンケートの実施に当たっては、一般質問の答弁の中でも地域ごとの影響の違いというのをしっかり把握・分析してですので。","voiceIndex":130,"id":"exchange-046"},{"speaker":"西本委員","kind":"質問・要望","question":"区民アンケートについては、今、集計中でありますので、確認していただきたいと思うのですけれども、クロス集計は当たり前だと思うのです。クロス集計で地域ごとの影響度合いというのも出てくるかと思いますので、しっかり分析していただきたいというのが１つ。それから自由記述のところについては、言葉を取るということではなくて、やはり生のものは絶対必要です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":132,"id":"exchange-047"},{"speaker":"若林委員","kind":"質問・要望","question":"継続でお願いしたいと思います。これまでの繰り返しになりますけれども、区民の皆様の不安の払拭につながる対策をしっかりと区が行うこと、また早期に、また具体的に、ルートの再考、固定化を避ける取組を示していただきたい。これは区議会の決議でも見られますけれども、その立場から継続ということでお願いしたいと存じます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":135,"id":"exchange-048"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択を主張します。羽田新ルートについて、住民の生活が脅かされていますし、中止して、従来の海上ルートに戻すべきだと思いますので採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":137,"id":"exchange-049"},{"speaker":"田中委員","kind":"質問・要望","question":"なので、私の思いとしては、陳情者の方と同じような思いではありますが、陳情を処理するに当たりましては、それぞれ国土交通省、国に対しての改善を求める内容でありまして、では品川区長がどこまで、このルート変更に対して権限があるのかと考えたときには、いわゆる処分性がないというか、権限がありませんので、私はこの思いは、品川区役所を通じてではなくて、直接。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":139,"id":"exchange-050"},{"speaker":"まつざわ副委員長","kind":"意見","question":"継続です。繰り返しになりますが、今、アンケートの結果がどうあれと書いてありますが、アンケートの結果が私たちは大切だと思っています。結果を鑑みてまた対応していきたい。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":142,"id":"exchange-051"},{"speaker":"のだて委員","kind":"質問・要望","question":"本日結論を出すということで、採択を主張します。住民の願いは、羽田新ルートをやめてほしいということですし、固定化回避検討会では、品川区の上を飛ばない結論は出てこない、区としても求めていないということですので、羽田新ルートの撤回を国に求めるべきだと考えますので、採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":145,"id":"exchange-052"},{"speaker":"田中委員","kind":"質問・要望","question":"本日結論を出していただきたいと思います。私の意見は不採択です。理由につきましては先ほどと同様で、国に対する要望事項でありまして、区長の立場で、いわゆる権限がないということで、国に携わる国会議員などに、この思いをお伝えいただけたらと思います。ただ、私自身の思いは、同様の思いです。ゆえに、不採択ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":147,"id":"exchange-053"},{"speaker":"のだて委員","kind":"質問・要望","question":"その下で、今回は様々説明を求めるものになっておりますので、ぜひそこは回答していただきたいと思います。それと併せて、地権者の動向をどう捉えているのかということも聞いておりますので、伺いたいと思います。それと、従前・従後の評価や補償の関係ですけれども、ここについても何がどう違うのかということで聞かれておりますので、どういう仕組みになっているのか伺いたいと思います。","respondent":"中道都市開発課長","answer":"地権者の動向ですが、再開発の組合が設立認可されたときに、公告があった日から３０日以内に、権利変換を希望しない、いわゆる転出したい方の申出ができることになります。","voiceIndex":155,"id":"exchange-054"},{"speaker":"のだて委員","kind":"質問","question":"区は今、地権者の動向を把握していないということを明確にさせていただきました。それで、従前・従後の評価・補償のところは、基準日が違うということは価格も異なってくるのかと思うのですが、そこのところを伺いたいのと、コロナ禍では、現状の中では、所有者が売却価格を決定するにはどうすればいいのかということも言われておりますけれども、そうした仕組みの流れなどを伺いたいと思います。","respondent":"中道都市開発課長","answer":"価格が違うですけれども、確かに現時点では、これが最終価格というのは提示することができないという状況ですが、一定程度の基準となる価格は提示はできていると認識はしております。","voiceIndex":157,"id":"exchange-055"},{"speaker":"のだて委員","kind":"質問","question":"つまりは、都市再開発法の中で価格が決まっていくというのは、地権者が売却価格は決められないということなのか、伺いたいと思います。","respondent":"中道都市開発課長","answer":"権利者の方が個人で売却価格を決めることはできないです。","voiceIndex":159,"id":"exchange-056"},{"speaker":"のだて委員","kind":"確認","question":"まさにそういった事業が再開発だと私も思います。その中で住民の暮らしを壊していいということにはならないと思うのですけれども、品川区としてはいかがでしょうか。そして、商店街の登記が変更になったということで書かれているのですけれども、これは区として確認されているのか、また、変更されたことで対象範囲などが変わってくるのか、この変更の理由というのですか、何が変わるのか伺いたいと思います。","respondent":"中道都市開発課長","answer":"住民の暮らしですけれども、今現在、再開発組合設立に向けて検討を進めているです。","voiceIndex":161,"id":"exchange-057"},{"speaker":"のだて委員","kind":"確認","question":"今、組合設立で進められているということなのですけれども、やはりこうした陳情でも現れておりますけれども、進めてほしくないという人たちもいらっしゃるという中で、設立に向けて進んでいるということですから、同意の確認などがされているのか、いつ頃までに計画の予定、設立しようとしているのか伺いたいと思います。","respondent":"中道都市開発課長","answer":"商店街の今後の消滅というお話ですけれども、そもそも武蔵小山のまちづくりが、商店街のパルムビジョンという、２０１４年につくられました、商店街がつくった今後１００年の商店街というところの考えを基に、区もその辺を踏まえて進めているというところで。","voiceIndex":163,"id":"exchange-058"},{"speaker":"のだて委員","kind":"質問","question":"同意については、区ではまだ出てきていないので、スケジュールも分からないということでしたけれども、もともとのスケジュールというのがあると思うので、それは区としてはつかんでいるはずだと思うのですが、ここで本組合にするための設立のスケジュールというのを伺いたいと思います。","respondent":"中道都市開発課長","answer":"もともとのスケジュールももちろんありますけれども、今、区では準備組合に対しまして、同意というのですか、同意率というか、みんなで話し合って、いかに皆さんで地域をよくしていってほしいという思いを伝えてありますので、なかなか。","voiceIndex":165,"id":"exchange-059"},{"speaker":"のだて委員","kind":"質問","question":"商店街としては、これを契機ににぎわいを高めていきたいということのようなのですけれども、やはり今、住み続けてきた人たちが追い出されることになってしまうということで、今回の陳情も出されているわけですけれども、そうすると、地域の絆も壊され、商店街に親しんできた方々も追い出されてしまうということになれば、それは活性化するということにはならないのではないかと思いますが、いかがでしょうか。","respondent":"中道都市開発課長","answer":"繰り返しになりますけれども、やはり今、商店街の話も聞きながら進めているというところ、同意につきましては今現在、話合いが行われている最中というような認識ですので、区としては、その内容を注視していきたいと思いますし、そこで出た同意などのお話の結果につきましては。","voiceIndex":167,"id":"exchange-060"},{"speaker":"西本委員","kind":"確認","question":"ちょっと確認させてください。住民が今、決めている最中ということなのですけれども、再開発するときに、準備組合の構成などは公表はしていないのですか。公表できないのですかということが１点と、それから武蔵小山のほうを先にして、再開発が始まっていると思うのですけれども、その評価というのはどういう評価を持っているのか。","respondent":"中道都市開発課長","answer":"定款等にその辺が書かれているですが、定款自体は準備組合が持っているものになりますので、そこの部分につきましては、公表という形では準備組合がどう考えているかというところで、区が公表するものではないという認識です。","voiceIndex":170,"id":"exchange-061"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、ここまでいってしまうと、どうやったら救えるの、どうやったら折衷案が出せるの、どうやったら理解を求められるのというところが、今の制度の中では見えないのです。なので、もう、透明性という意味であるならば、やはりその辺は透明性のある形で推進していかないと、品川区が行政側として入れないところもあるじゃないですか。この評価をどうしていくか。さきの１番目のお考えをお聞きします。","respondent":"中道都市開発課長","answer":"区としては１００％を目指してまちづくりをしていただきたいというところはもちろんありますが、一方で、やはりどうしてもなかなか意見が平行線のままという現状もあるというところはもちろん認識していますので、区としては、議論をどこまで深掘りしているのかとか。","voiceIndex":172,"id":"exchange-062"},{"speaker":"西本委員","kind":"質問・要望","question":"区のスタンスはよく分かります。だけれども、やはり準備組合等々の、どういう方々がとか、どういう方法でとか、何をどうしているのというのが見えないと、周りの方々というのは多分、不安だらけだと思うのです。もちろん反対者はいるし賛同者もいるという中で、これから、まちづくりで求められるのは、理解を求め合うということだと思うのです。言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":174,"id":"exchange-063"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうしたことがないように、区としてもしっかりチェック・指導していただきたいと思いますけれども、いかがでしょうか。本組合と準備組合の評価の手法の話ですけれども、仮に本組合が不成立の場合は、従前の評価をどう扱うのか、どうなっていくのかというところを伺いたいと思います。","respondent":"中道都市開発課長","answer":"強引な同意ですが、そういったお話は区には届いていないですし、そういったことがないように、準備組合にも伝えてまいりたいと思います。","voiceIndex":176,"id":"exchange-064"},{"speaker":"のだて委員","kind":"質問","question":"すみません。質問の仕方が悪かったかもしれないのですけれども、評価のところです。今、準備組合の段階で評価したというものが、本組合が設立できなかったという場合には、どうなるのかというところを伺いたいです。","respondent":"中道都市開発課長","answer":"本組合ができなかったということでは、市街地再開発事業の組合がないので、市街地再開発事業がないということです。なので、評価自体がなくなるわけです。","voiceIndex":178,"id":"exchange-065"},{"speaker":"まつざわ副委員長","kind":"意見","question":"結論を出すで、不採択でお願いします。いろいろ議論も聞いております。この市街地再開発というのは、地域で話し合って組合を立ち上げるという中で、行政からもよく話し合ってくれというお話も聞いておりますし、再開発法にのっとり、行政ができるところはしっかりとやっているというふうに、私は質疑の中で捉えましたので、不採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":181,"id":"exchange-066"},{"speaker":"若林委員","kind":"質問・要望","question":"本日結論を出すということで、当然ですけれども、今後、本組合に向かって、今、準備中ということですが、しっかりと法にのっとって、区の役割もその中で、しかるべき役割を果たされていくという意味では、しっかりと仕組みの中で進めていただきたいと思います。ということで、不採択で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":182,"id":"exchange-067"},{"speaker":"のだて委員","kind":"質問・要望","question":"本日結論を出すということで、採択を主張します。再開発での見解や用語の説明、商店街の状況の説明を求めていまして、説明されるべきですし、住み続けたいと願う住民を追い出す再開発は中止すべきだと考えますので、採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":184,"id":"exchange-068"}]},{"id":"topic-03","title":"令和５年１１月都営住宅入居者募集","agenda":"令和５年１１月都営住宅入居者募集","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"この間の応募倍率などの実績を伺いたいと思います。それと併せて、この間、やはり倍率が高い状況になっておりますので、ぜひ区としても、東京都に都営住宅の増設を求めてほしいと思いますけれども、いかがでしょうか。","respondent":"竹田住宅課長","answer":"東京都への申入れという件ですが、住宅対策は都営住宅だけではなく総合的に進めていくものと考えていますので、東京都への申入れは今考えておりません。","voiceIndex":196,"id":"exchange-069"},{"speaker":"のだて委員","kind":"質問・要望","question":"実績を伺っても、過去３回は約１０倍の倍率、昨年の８月は５２倍ということで、本当に高い倍率になっていると思います。この間、コロナ禍や物価高騰で暮らしが大変になっているという下で、都営住宅のニーズも高まっているのだと思いますので、やはり、こうしたところ、公営住宅の役割を考えていただいて、都営住宅の増設を求めるべきかと思うのですけれども、改めてお伺いします。","respondent":"竹田住宅課長","answer":"先ほどご紹介した倍率ですが、令和４年８月は、通常は５０棟近く募集があるのですけれども、このときはたまたま４棟しかなかったということで、高倍率になっているものです。先ほども申し上げましたとおり、東京都に申入れ等をする考えはございません。","voiceIndex":198,"id":"exchange-070"},{"speaker":"のだて委員","kind":"質問・要望","question":"令和４年８月が５２倍だったのは４棟だけだったからということですけれども、１０倍とかも十分高い倍率だと思いますので、やはりニーズは高まりつつあると。重要なニーズがあると思いますので、ぜひ区としても都営住宅の増設、この間、２０年ぐらいやられていないという状況ですので、求めていただきたいと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":200,"id":"exchange-071"}]},{"id":"topic-04","title":"南大井３丁目解体工事現場","agenda":"南大井３丁目解体工事現場","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"この解体工事について、アスベストの飛散などへの対応というのはどうだったのかというところを伺いたいと思います。それがもしあるとすれば、近隣住民に大きな影響がかかるということになってしまうので、そこのところを伺いたいのと、区としても、解体工事の届出というのは提出されていると思うのですが、その際のチェックというのですか、その仕組みがどうなっているのか、伺いたいと思います。","respondent":"河内環境課長、竹田住宅課長","answer":"アスベストにつきまして、お答えいたします。アスベストの届出関係ですが、適正に行われておりまして、事前に調査が行われております。ただ、お届けいただいた際には、どの業者にも申し上げるところなのですが、安全管理、それから近隣への影響を最小限に抑えること等を強くお願いしているものでございまして、今回もそのようなお願いをしています。","voiceIndex":205,"id":"exchange-072"},{"speaker":"のだて委員","kind":"質問","question":"アスベストについてはなかったということで、そういった心配はないということなので、よかったと思います。今後起きないようにしていくために区が検討していることなどがありましたら、伺いたいと思います。","respondent":"竹田住宅課長","answer":"区民の方からご心配、ご不安等のご連絡をいただいた際は、速やかに現場を確認し、適切な指導を行っているところです。先ほども申し上げましたが、届出等の際には、安全な工事現場の進行を業者に要請していきたいと考えております。","voiceIndex":208,"id":"exchange-073"},{"speaker":"のだて委員","kind":"質問・要望","question":"最後に１点、確認させていただきたいのですが、今回こうした形での解体工事現場の報告というのは、なかなか今までなかったと思うのですが、これは、先ほど、区民から声が寄せられたためということで説明がありましたけれども、どういった場合に議会に報告されるのか、基準などがあるのか、伺いたいと思います。","respondent":"竹田住宅課長","answer":"今後につきましても、工事の状況あるいは周囲への影響等を考えながら、必要があるものについてご報告させていただきたいと考えております。","voiceIndex":210,"id":"exchange-074"},{"speaker":"西本委員","kind":"確認","question":"これからも増えてくる可能性はあって、届出が必要なのだとおっしゃっていて、それで５１３件あるということですから、一件一件、現地で確認するなどというのは到底難しいことだと思うのですが、これを機会に、やはり適正な処置をしているのかという監視体制は、区として必要なのではないかと思うのですが、いかがですか。","respondent":"竹田住宅課長","answer":"現場の状況の確認ですが、必要に応じて今後も実施していきたいと考えています。","voiceIndex":213,"id":"exchange-075"},{"speaker":"西本委員","kind":"質問","question":"せっかくここで、悪い事例になるのですけれども、チャンスだと思うのです。では、野放しにしないようにするにはどうしたらいいかという方法を、やはり考えてほしいと思いますので、ぜひ工夫をしていただいて、いいチャンスなので、品川区は毅然とした態度を示していきますというぐらいのことは報道してもいいのではないかと私は強く思っておりますので、その件に関してのご意見をお聞きしたいと思います。","respondent":"竹田住宅課長","answer":"先ほど、なあなあというお話がありましたけれども、決してそういうことはございませんで、工事業者、行政側として、一線を引いて対応しています。","voiceIndex":215,"id":"exchange-076"},{"speaker":"若林委員","kind":"質問・要望","question":"ここでは９月３０日までのスケジュールというか見通しが記載されているのですが、あちらの方面にいる同僚議員からもお話がありまして、昨日現在のお話ですけれども、残りの廃材を撤去するというところが、どうも現場を見ているとクエスチョンだという感想がありました。そこを確認させていただきたい。","respondent":"竹田住宅課長","answer":"慎重に安全管理を一番に考えておりますので、時間は少し長引いているところです。それから、今後の監督ですが、先ほど申し上げましたとおり、必要に応じて現場を確認し、必要があれば業者に確認・要請してまいりたいと考えております。","voiceIndex":218,"id":"exchange-077"},{"speaker":"若林委員","kind":"確認","question":"当然、当事者として発注者の責任は多いと思うのですが、今後、解体後のいわゆる建築工事のことも、やはり近隣の方は当然ご心配されていて、解体がきちんと新しい解体業者等によって、区も最後まで見守ってという中で終わったとしても、発注者のこともあるので、次の建築工事のこともすごく懸念されているということで、ここは、通常の建築確認がどこから出されるか分かりませんけれども。","respondent":"長尾建築課長","answer":"当然、建築される際は、事前に建築確認の手続を経ていくのですけれども、その前には、紛争予防条例に基づく届出が、一定、同じような規模の建物を計画する場合であれば出てきますので、その際は現場に、工事前に看板が建って、近隣の方に一定の説明を経て、それで建築確認をして。","voiceIndex":220,"id":"exchange-078"},{"speaker":"まつざわ副委員長","kind":"質問・要望","question":"なかなか通じなくて、次の日なのですけれども、いろいろ電話が来て、向こうの監督に電話して、期日を守ってくれないと困りますよみたいなのが２回、私の周りにも実際にあったのです。何かあったときに、また注意するのが行政のお仕事なのか。そこを１個教えていただきたいのと、この事故に関して、肌感覚だけではなく、アスベスト工事に対する、何というのですか、区民の方の恐怖。その辺を教えてください。","respondent":"河内環境課長、竹田住宅課長","answer":"ほかの事例でもありますので、こういった点を今後徹底して、区民の方の安心安全につながるように進めてまいりたいと考えているところです。その他、解体現場、騒音、振動等、様々なお声をいただいているところですが、そういった内容をしっかり業者に伝えて、業者にも安全な工事の要請をしていきたいと考えています。","voiceIndex":223,"id":"exchange-079"},{"speaker":"まつざわ副委員長","kind":"意見","question":"この場合も行政の対応が相当早いということで、区民の方もしっかり安心していらっしゃったので、また引き続き、しっかりと、こういった事故を起こさないような工事を目指して取り組んでいただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":226,"id":"exchange-080"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4388#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":54575,"voices":233}},{"id":"r05-20230925-9","meetingId":"r05-cm09","date":"2023年9月25日","dateIso":"2023-09-25","committee":"文教委員会","time":"午前１０時００分～午後 ０時０５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第６７号議案、品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","agenda":"第６７号議案、品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"分かればでいいのですけれども、大本の国が政令を改正した理由と、補償額の設定の根拠がもしあれば、教えてください。","respondent":"柏木学務課長","answer":"理由と根拠ですが、内容的には同じ答弁になるかと思いますが、主な改正理由といたしましては、最低賃金の全国加重平均額、最低賃金の全国平均ですが、こちらが改定で上限が上がったということで、それが主な理由です。根拠も同様です。","voiceIndex":10,"id":"exchange-001"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"１点だけ教えていただきたいのですけれども、国が政令を出して、東京都の条例も改正されて、区も条例を改正されるということですけれども、逆のパターンというのはあるのですか。例えば、区の条例だけ変えるということは基本的にはないのですか。そこだけ教えてください。","respondent":"柏木学務課長","answer":"こちらは国、都、区と同一の補償ということになりますので、区だけ先にやるとかいうことはございません。","voiceIndex":13,"id":"exchange-002"}]},{"id":"topic-02","title":"第６８号議案、品川区立幼稚園条例の一部を改正する条例","agenda":"第６８号議案、品川区立幼稚園条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"大きく３点伺いますけれども、この内容の報告、決定等を行う教育委員会はいつ行われたのでしょうか。そこでの意見はどのようなものがあったのかが１点です。それと、閉園は再来年の４月１日なのですけれども、条例改正を１年前倒しして、本定例会で行う理由についてお伺いします。資料の記載について、反省点とかはないのかと伺いたいと思う。これが３つ目です。","respondent":"柏木学務課長","answer":"審議の中での意見等ですが、委員からは、条例改正を１年前倒しの形を取ったことは、丁寧に説明するという意味では非常にいいという意見もいただいておりますし、質問で、閉園について今までも教育委員会で何度か話があったが、閉園に向けての準備等は順調に進んでいるのかとか。","voiceIndex":27,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、教育委員会ですけれども、８月２２日ということで、これは教育委員会において報告、審議、決定という形でなされたのか、確認したいと思います。保護者からは、区立幼稚園のすばらしい先生方や幼児教育を大切にしていただきたいということを切に願っていますとの声を、改めていただきました。この声をどう受け止めるのでしょうか。どうしたらそのように正当化できるのか、改めて伺いたいと思います。","respondent":"柏木学務課長、立木保育課長","answer":"８月２２日、教育委員会での審議の在り方ですけれども、こちらは区立幼稚園条例の改正の立案請求ということで、教育委員会で審議をいただいてあります。幼児教育の部分に関してですけれども、今回、今後の区立幼稚園の方針という形で検討させていただきました中では、社会的な情勢の変化もある中で、幼保一体施設のほうの幼稚園をこのまま続けさせてもらって。","voiceIndex":29,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"継続するのは当然なのではないかと思うのですけれども、そして資源を集中するということですが、資源という言い方も、私は行政用語なのであまり好きではないのですけれども、資源の集中というのは何を指しているのかというのを伺いたいのと、それをもって充実させていくということですが、これから区立の幼保一体施設の新たな人員配置とか、新たな施策を打ったりとか。","respondent":"立木保育課長","answer":"浜川・城南の単独園２園に関しましての進め方ですけれども、昨年から進め方につきましては、いろいろご意見を私どももいただいておりますので、そういったことを踏まえながら、しっかりとやっていきたいと考えているところです。","voiceIndex":32,"id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"到底納得いくことはできないのですが、最後に態度表明で意見を言わせていただきたいと思います。質疑は終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-006"},{"speaker":"ゆきた委員","kind":"質問","question":"閉園に伴って、伊藤幼稚園で現在、児童２名が利用されている状況だと思われます。社会的な情勢の変化といえども、残された２名に対しての、通常行われている３０名前後での行事とか、集団行動で学ばれる場というものが失われているのではないかと思いますが、この児童に対しての手厚い支援等があるのかといったところでお聞きしたいと思います。","respondent":"立木保育課長","answer":"今現在、まだ５歳児も在園しておりますので、一緒に活動したりとかですね、あと、近隣に保育園が何園かございまして、そちらとの連携等もしながら、また来年に関しましては、５歳児が卒園しまして、持ち上がりまして、来年は年長１クラスのみ、２名ということになりますので。","voiceIndex":36,"id":"exchange-007"},{"speaker":"ゆきた委員","kind":"意見","question":"ご答弁あったと思われますけれども、来年はやはり２名ということになると思われますので、そういったところでの手厚い、より具体的な支援といったところを、今後ともさらに考えていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":38,"id":"exchange-008"},{"speaker":"高橋（し）委員","kind":"質問","question":"地教行法、いわゆる地方教育行政の組織及び運営に関する法律の第２１条第１項に基づく、教育委員による教育委員会の権限の一つである職務権限の一つであります公立幼稚園の廃止についての審議をし、決定する。それについての教育委員会の記録が今回ないということなので、その権限を教育委員会が行使したのかどうかは不明だと思います。いかがでしょうか。","respondent":"柏木学務課長","answer":"幼稚園の今後の方針につきましては、まず８月に教育委員会で報告いたしまして、そこで報告事項ですが、了承ということになってあります。９月に、伊藤幼稚園の閉園の延期の報告につきましてもいろいろ質疑をしながら、報告については了承されているものです。","voiceIndex":40,"id":"exchange-009"},{"speaker":"高橋（し）委員","kind":"質問","question":"８月に報告があった。そして１２月に陳情審査で、それぞれ審議をした。今、報告がありましたと言ったわけですから。そうすると、今回こうして議案として出てくるには、教育委員会で廃止に関する審議をし、それを決定したという文書がないと、ご説明が先ほど口頭で少しありましたけれども、審議はできないと私は考えますが、改めましていかがでしょうか。","respondent":"柏木学務課長","answer":"繰り返しになる部分がありますが、報告等については教育委員会として了承して、最終的には条例改正に伴う立案請求というところで、廃園については最終的な教育委員会の審議がされ、決定がされたと考えています。","voiceIndex":42,"id":"exchange-010"},{"speaker":"高橋（し）委員","kind":"確認","question":"もう一回言いますけれども、２２日の教育委員会での条例改正に関する議案、教育委員会の中で話し合う議案についての決定がなされたということは分かります。それの法的手続に関してどうだということを私は言っていて、それは、議会や教育委員会が、そして区長部局が守るべきコンプライアンスだと思っているので、今回も質問させていただいています。文書は出てこないのでしょうか。確認させてください。","respondent":"柏木学務課長","answer":"文書というのは、２２日の会議録ということでしょうか。こちらはまだ出てございませんので、近日中には公表できるかと思います。","voiceIndex":44,"id":"exchange-011"},{"speaker":"高橋（し）委員","kind":"質問","question":"そこは今の答弁で止まったのだと思うので、そこで取りあえず切ります。別の方面のお話をしますと、先ほどの地教行法の第２９条には、特に教育に関する事務について定める議会の議決を経るべき事件の議案を作成する場合においては、教育委員会の意見をきかなければならない。ということは、議案の請求が教育委員会から区長部局、総務部の文書係になるのでしょうか、そこに提出されたということですよね。","respondent":"柏木学務課長","answer":"条例改正の立案請求をさせていただいたときには、幼稚園の内容等についての質疑もある場合もございましたので、保育課長には教育委員会に出席をしていただき、質疑等も含めて、内容については確認されているものと考えています。","voiceIndex":46,"id":"exchange-012"},{"speaker":"高橋（し）委員","kind":"質問","question":"教育委員会は立案請求を区長部局に手続します。教育委員会は条例をつくることができないから。ですから、区長部局にそういう書類を提出していると思います。ですから、それを出していただければ、こういう理由で条例改正するのだなと、さっきの話に戻りますけれども、あるのですが、その点はいかがでしょうか。","respondent":"柏木学務課長","answer":"総務部に出している資料については、お見せできるかどうか、すみません、今、私のほうでは判断できませんので、確認をさせていただきたいと思います。","voiceIndex":48,"id":"exchange-013"},{"speaker":"高橋（し）委員","kind":"質問","question":"というご答弁だということです。区長部局が条例を立案する場合は、そういうことは必要ないのですが、教育委員会から立案請求をされたわけですから、そういった資料を添付していることは間違いないと思うのです。ですから、それを示していただいて、議会として議論を、先ほどホームページには出ていないというのですから、それを出すことができたのではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-014"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"先に意見だけ言わせてください。態度といたしましては、既に伊藤幼稚園の方たちの定員の手続というのも着々と進んでおられることを確認いたしましたし、先ほどゆきた委員からもありましたけれども、残っておられる２名については、最後の卒園まできちんと責任を持って、きちんと幼稚園としての役割を果たしていただくことを前提に、賛成をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"反対です。保護者と地域に愛され培ってきた伊藤幼稚園の、合理的な理由もなく一方的な閉園方針は認められません。存続して、品川区行政の責任、教育委員会の責任で、さらに発展させるべきです。浜川・城南の閉園方針も撤回するよう求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-016"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"意見だけ申し上げますが、こういった大きな条例改正に関しては、いろいろな議員からもお話があった手続が、いろいろと不備もあったのではないかと思いますので、こういった大きなことに関しては、しっかりと丁寧に手続を進めていっていただきたいと思います。これは意見で述べますが、よろしくお願いします。その上で、今回はこの改正に関しては、賛成ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-017"}]},{"id":"topic-03","title":"第６５号議案、令和５年度品川区一般会計補正予算（歳出等 文教委員会所管分）","agenda":"第６５号議案、令和５年度品川区一般会計補正予算（歳出等 文教委員会所管分）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"契約なのですけれども、事業者から金額変更の請求があったとあるのですが、請求先というのは子ども未来部なのかというのと、賃金等の変動とありますけれども、賃金等の「等」のところというのは、どんな感じなのかというのを教えてもらいたいのと、（１）と（２）のところでは、増額分の増額率とか、その辺は統一なのでしょうか、教えてください。","respondent":"立木保育課長","answer":"賃金等というところの「等」になりますが、賃金のほかに、資材等も含まれるということで聞いております。率に関しましては、国がインフレ等の物価高騰につきまして、数字を出していますので、それは共通と聞いているところです。","voiceIndex":64,"id":"exchange-018"}]},{"id":"topic-04","title":"令和４年度保護者アンケートおよび児童・生徒アンケートの結果","agenda":"令和４年度保護者アンケートおよび児童・生徒アンケートの結果","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"こちらは毎年やっているのですけれども、改めて、アンケートの委託先と、大体１回、事業費はどれぐらいかかっているのかというのを分かれば伺いたいのと、目的なのですけれども、教育施策の成果を検証し、より一層の充実とありますが、今回のアンケートを受けて、区教委としては、主にでいいのですけれども、この結果でどんな施策を一層充実させようと思ったのかを伺いたいと思います。","respondent":"中谷指導課長","answer":"委託先ですけれども、アンケートの用紙の印刷の委託というものと、保護者や児童・生徒の皆さんからいただいたアンケート結果を集計するという委託と、２つを実施しております。用紙の印刷の委託につきましては、株式会社京浜印刷、６０万円程度でやっております。","voiceIndex":78,"id":"exchange-019"},{"speaker":"安藤委員","kind":"質問","question":"３点目は、児童・生徒アンケートの１２ページの、「今住んでいる地域が好きだ」という質問なのですけれども、これを伺う理由というのは何なのかというのを聞かせていただければと思います。お願いします。","respondent":"中谷指導課長","answer":"２点目の英語が好きだという設問についてですけれども、年齢が上がるにつれて、好きだと感じている割合が減るということなのですが、全体の傾向としては確かに、いつも毎年取っている中で、その傾向はあるのですが、今回少し変化が出たことがありまして、それが何かと申しますと。","voiceIndex":80,"id":"exchange-020"},{"speaker":"安藤委員","kind":"提案","question":"選択制に関するアンケートでは、義務教育学校とそれ以外をクロス集計していますし、児童・生徒アンケートでは、２ページから６ページのように様々な成果について聞いているわけですから、来年からすぐできるのではないかと思うのですけれども、小中一貫教育がすばらしいということについて言われているので、だったら、科学的にきちんとアンケートという形で検証していただきたいのですけれども。","respondent":"柏木学務課長、中谷指導課長","answer":"単純に兄弟とかの情報よりも、実際見て、あと、教育委員会からの案内等があまり重視されていないという部分もありますので、その辺は反省して、学校案内等も見やすく。今現在、７年生から９年生までどういった指導計画を立てるかということを、教育委員会としても、まずフォーマットとなるものを教育会と協力してつくっておりまして、それをまたこれからも継続して、検証していきたいと考えています。","voiceIndex":82,"id":"exchange-021"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"アンケートの１１ページの「お子さんが卒業しても、品川コミュニティ・スクールなどの教育活動に協力しようと思う」とのアンケートに対して、肯定的な回答が約半数の結果なのですけれども、この点について、今後の改善の取組など、お考えがもしあれば、教えていただければと思います。","respondent":"中谷指導課長","answer":"それとは別に、各学校で、モデル校として実施しようとしている企画なのですけれども、コミュニティ・スクールというものが、どういった形でうまくいっているのかということを検証する、別のアンケートをやっていきたいと考えております。","voiceIndex":86,"id":"exchange-022"},{"speaker":"ゆきた委員","kind":"意見","question":"毎年なされているこのアンケートと、各学校で学校評価のアンケートもされているということで、また新しい取組として、今ご答弁があったモデル校としてのアンケートも実施されるということでしたので、そういったことも、今後ともぜひ継続して取り組んでいただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":88,"id":"exchange-023"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"例えば、修学旅行に行けなかったとか、運動会ができなかったとか、学校になかなか通えなかったとか、いろいろな制限があった中で、そういった設問というのがなかったのか、改めてお聞かせください。それと、例えば１２ページ、「学校が地域と連携することによる効果として期待するものは何ですか」といった、幾つか選択をされる設問とかがある。","respondent":"中谷指導課長","answer":"こちらにつきましては、今回、学校が地域と連携することによる効果として期待するもの、これのみ複数回答なのですけれども、当てはまるものは１個だけではなく、全て選んでいただくという形を取らせていただいて、実施したものになります。","voiceIndex":90,"id":"exchange-024"},{"speaker":"石田（し）委員","kind":"質問","question":"それぞれご丁寧にありがとうあります。アンケートというのは、特に日本人はどちらかといえば、大体偏りがちなのです。コロナに関しては、僕がなぜこれを聞いたかというと、実はそのときの状況と、今少し落ち着いてきて、それこそ修学旅行とかができるようになったときの状況は、感覚が違うと思うのです。あのときは正直、しようがないと思ってしまうではないですか。もし何かあれば、よろしくお願いします。","respondent":"中谷指導課長","answer":"今ご指摘いただきました、コロナ禍の状況でどう変わっていたかというところで、実は児童・生徒対象のアンケートの設問３と４なのですけれども、人間関係というか、人との関わりについて聞いている設問になるのですが、例えば友達と仲良くすることができるとか。","voiceIndex":92,"id":"exchange-025"},{"speaker":"せお委員","kind":"質問・要望","question":"私からは１点だけ。これなのですけれども、教育委員会からはどういったことを、今、コロナという話もあったのですけれども、より具体的に、どういった場面を想定して聞いているのかなというところと、児童・生徒からすると、どういった場面を想定できているのかなというところが分かれば、まず教えていただきたいです。","respondent":"中谷指導課長","answer":"３番・４番いずれも、まず申し上げたいのは、授業の中でというところがあるかなと考えています。","voiceIndex":95,"id":"exchange-026"},{"speaker":"せお委員","kind":"質問","question":"私は今、石田しんご委員のお話とも関係あるのですけれども、特にここの設問は、「どちらかといえば当てはまらない」、「当てはまらない」にしているお子さんが、すごく気になると思っていて、このアンケートは無記名なので、そちらにアプローチできないというか、今、いじめとか不登校とか自殺とかが増えている中で、これが５年生とかだと１割を超えているというのがすごく気になっていますので。","respondent":"中谷指導課長、丸谷教育総合支援センター長","answer":"こちらの設問については、無記名ではあるのですけれども、各学校ごとにデータをしっかり分析するというところがありますので、今ご指摘いただいたような、何割が肯定的な回答ではなかったというところも。７年生でも学級風土調査という形で調査をしておりまして、こちらも同様に、個々に対応できるような形を取っております。","voiceIndex":97,"id":"exchange-027"},{"speaker":"高橋（伸）委員","kind":"意見","question":"２点です。児童・生徒アンケートの１１ページです。これも低学年から中学年は肯定的なのですが、９年生になるとオレンジの部分は４２.７％になるのですけれども、ＩＣＴというのはすごく反比例しているのかなと私は個人的に思っていて、もっと数値が上がってもいいのかなと思っているのだけれども、これをどのように分析しておられるのか、同じ回答なのですけれども、分析のことでお尋ねしたいと思います。","respondent":"中谷指導課長","answer":"１２番、ＩＣＴですけれども、こちらについては、当てはまると回答した割合が、昨年度も同じものを取っていて、一部の学年、２年生と９年生で僅かに下がっているのですが、そのほかの学年では上がっていて、３年生と５年生では、特に５ポイント程度上がっているというような。","voiceIndex":101,"id":"exchange-028"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"そうすると、今度、７・８・９年生となると、９年生は受験とか、いろいろあると思うのだけれども、地域行事はそれぞれ地域性があると思うのですが、すごく薄れてきているなというのを、私は今年、すごく肌で感じて、このアンケートを見ると、同じような結果というか、こういうのをお示しになられたから、学校行事も、学校長がいろいろ祭礼等々のお知らせをしていると思うのだけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":103,"id":"exchange-029"},{"speaker":"高橋（し）委員","kind":"質問","question":"３点お尋ねします。具体的に、学校で地域とのつながりをつくるのも限界というか、一定のところまでになるので、そうすると、地域活動課、先ほどの町会のお話に出てきましたが、あとは地域のスポーツ団体、スポーツ推進課などとの連携というのを、具体的に教育委員会として、あるいは学校としては、どう進めていこうと思われているのでしょうかというのが１つ目。よろしくお願いします。","respondent":"中谷指導課長","answer":"各教科で好きが減少してしまうというところと、学力との関係というところでしたけれども、これまでの学力の意欲と知識・理解の部分でしたり、思考・判断・表現力の部分との関連性というのが、非常に相まっているというところがありまして、ご指摘いただいたとおり。","voiceIndex":105,"id":"exchange-030"},{"speaker":"高橋（し）委員","kind":"質問","question":"地域との関わりで、今、具体的に動いているところで、地域への部活動の移行ということで、品川区でそういうことに取り組んでいるというある保護者の方で、お子さんがラグビーをしていて、残念ながら品川区では学ぶ機会がないということで、ですから、そういうのを品川区でやってもらったら、それがあれば参加していきたいという前向きなお話をいただいているので、これは今。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":107,"id":"exchange-031"},{"speaker":"吉田副委員長","kind":"質問","question":"この質問はとても難しくて、基本は教育委員会がしっかりやるべきなのだけれども、こういう目的でやりたい、こういうことに活かしていきたいという趣旨の下、どういうアンケートを取るべきかということについては、そういう専門のところもあると思いますので、その辺について検討されたのかどうかということと、それから、このアンケートを議会としては、ここの文教委員会という場でご報告を受けて。","respondent":"中谷指導課長","answer":"ただ、やりたいという趣旨に関しては、教育委員会が持っていなければならないと思うので、そこをしっかりこれまでどおりやっていきつつも、例えば、大学の有識者の方ですとか、そういった方にご意見を聴くということも一つできるかなと、お話を伺って思いましたので。","voiceIndex":109,"id":"exchange-032"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"委託先については、おっしゃるとおり、ぜひ、まずは教育委員会の中で目的とか趣旨はきちんと議論していただきたいと思います。もし委託するとしても、その辺については、それを前提にお願いしたいと思います。それから、２つ目のフィードバックにつきましても了解いたしました。これは要望でとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":111,"id":"exchange-033"}]},{"id":"topic-05","title":"子育て支援情報発信アプリ","agenda":"子育て支援情報発信アプリ","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"これが２点目。３点目は、最後の下に、「試行運用開始後も利用者の声をくみ取り」とありますけれども、どのようにくみ取っていくのか、これまではどのようにくみ取っていたのか伺いたいと思います。","respondent":"藤村子ども育成課長","answer":"どのように今後くみ取っていくかというところなのですけれども、今まで使っていただいている方の声と、新しくダウンロードされた方の声というのは、逐一こちらにも関係団体等とか、個人からも情報が入ってきますので。","voiceIndex":118,"id":"exchange-034"},{"speaker":"安藤委員","kind":"質問","question":"少なくない数の方が利用しているのかなと思ったのですけれども、アクセス数という話がありまして、アクセス解析なのかなと思うのですけれども、どれだけの人に活用されているのか、数字的なものでいうとイメージできるようなアクセス数になるのか、直近でいいので、教えてもらいたいのと、今回、経費というところで、なぜ更新かというのがあるのですけれども。","respondent":"藤村子ども育成課長","answer":"更新の理由というところですけれども、既存のパパママ応援アプリを運用している業者が、以前はこういった形のアプリの運用に力を入れている会社だったのですけれども、現在は事業の配分というか、そちらの会社でアプリに力を入れているというよりは。","voiceIndex":120,"id":"exchange-035"},{"speaker":"安藤委員","kind":"質問・要望","question":"要望です。すみません、しつこいのですけれども、アクセス数というのを具体的に紹介できる数字はないのですかというか、これぐらいの人が直近だと見ていましたとか、このお知らせについては、これぐらいアクセスがありましたとか、そういうのがあるといいなと思うのですけれども、それがあれば最後に伺って、終わりにします。","respondent":"藤村子ども育成課長","answer":"アクセス数の個別のものというのはございませんので、お答えしかねるのですけれども、区のお知らせというところにはアクセスが多くあるという形になっております。","voiceIndex":122,"id":"exchange-036"},{"speaker":"せお委員","kind":"意見","question":"少し細かい話で恐縮なのですけれども、新しくなるということでうれしいのですが、前から私はいろいろな機会で、児童センターもそうですが、そのところとかで「こうえんしょうかい」を開くと、エリアがまず出てきて、公園名が出てくる。説明してくれているアプローチというのを、その方法も工夫してほしいのですけれども、その辺の検討はどうなっていますか。","respondent":"藤村子ども育成課長","answer":"ただ、ホーム画面のアイコンからそちらのアプローチという形には、今はなっていないので、そちらを含めて、どうできるかというところを今後検討したいと思います。","voiceIndex":125,"id":"exchange-037"},{"speaker":"せお委員","kind":"質問・要望","question":"例えば、「こうえんしょうかい」となっていて、せっかくアイコンがあるのに、ここが行けないので、そういうのもそうですし、そういう声も反映していただいて、つくっていただきたいなというところです。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":129,"id":"exchange-038"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"使い勝手が悪いのです。なぜかというと、情報とかは発信されていても、そもそもアプリを何に使うかというところに、僕は行き着いていないと思っていて、例えば母子手帳、今は母子手帳と言わないで母子・父子手帳と言うのでしょうか、要は手帳のアプリと連携をして、そのアプリを常にお母さん、お父さんが使っていると、いろいろなアクセスができるわけです。そういうところなのです。","respondent":"藤村子ども育成課長","answer":"例えば、先ほどお話しいただいた医療機関の検索とか、そういった機能も付与する予定で考えておりますし、そういうところですので、オンラインでの予約ですとか、写真と日付をリンクするというところは難しいですけれども、皆さんのご要望を捉えて。","voiceIndex":131,"id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5108#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":38318,"voices":138}},{"id":"r05-20230925-5","meetingId":"r05-cm09","date":"2023年9月25日","dateIso":"2023-09-25","committee":"総務委員会","time":"午前１０時００分～午前１１時５８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を50件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"塚本副委員長","kind":"意見","question":"前例に沿って、議題前に撮影ということでお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":3,"id":"exchange-001"}]},{"id":"topic-02","title":"冒頭に申し上げましたとおり、取り上げる順番を変更して行います。まず、(2)第７０号議案、スタッキングチェア他の買入れ","agenda":"冒頭に申し上げましたとおり、取り上げる順番を変更して行います。まず、(2)第７０号議案、スタッキングチェア他の買入れ","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"よくほかのところでも定価の何掛けとか必ずいろいろな話が出るのですけれども、これは入札なので総金額で結構ですが、そういうときに、もちろん当初に見積りとかをいろいろ取られたり、いろいろ行政側で予定価格等を決めたりするわけですから、そういうときに、こういう掛け率というのはどういう扱いをしているのかというところを教えていただけると。","respondent":"佐藤（聡）経理課長","answer":"案件によりますけれども、競争入札を原則といたしまして、それぞれ札を入れていただいているというところで、契約に関してはその入札のところで一定の競争が働いて、価格が低下していると認識しているところです。","voiceIndex":15,"id":"exchange-002"},{"speaker":"石田（秀）委員","kind":"質問","question":"そこは非常に分かるのですけれども、ただ所管から出てくる請求、では経理課としてもその事務作業を経理課がやりますよというだけなのか、それはやはりどこかでその整合性をある程度取っておかないと、特に動産の場合はそういう掛け率というのが私はあると思っているので、そこら辺のところは、今のお話だと連携が、確かに所管のことを信じるのはそれで構わないのだけれども。","respondent":"佐藤（聡）経理課長","answer":"ネットの価格との整合ですけれども、これに関してはほかの自治体等の取組も見ながら、今後も研究していきたいと考えております。","voiceIndex":17,"id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"こういう動産に対しては区の積算でやるのかと思うのですが、その辺はどうなのですか。それで、そうすると、掛け率は言えないと思うのですが、今石田秀男委員も言いましたけれども、一定の掛け率というのを区であらかじめ決めておいて、予定価格というのを決めているのですか。教えてください。","respondent":"佐藤（聡）経理課長","answer":"その上でですけれども、建設事業等につきましては一定の仕組みといいますか、やり方がある程度共通しているところもありまして、国ですとか都の基準を用いて積算しているという状況ではありますけれども、逆に動産の買入れになりますと、買入先も非常に多岐にわたるということと。","voiceIndex":19,"id":"exchange-004"},{"speaker":"須貝委員","kind":"質問","question":"しかし、これは予定価格というのを出しているのですよね。そうすると何か区のほうでこういう方式で予定価格を先に作るのが普通ではないのですか。それだったら最初から予定価格など要らなくて、一般に入札だけやればいいわけですよね。そこら辺について、もう一回だけお願いします。","respondent":"佐藤（聡）経理課長","answer":"入札の一定の基準を出すことで、不調にならないという効果もあろうかと思います。そういったところを踏まえて、予定価格については出しています。","voiceIndex":21,"id":"exchange-005"}]},{"id":"topic-03","title":"第６９号議案、西五反田公園改修工事請負契約","agenda":"第６９号議案、西五反田公園改修工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"これは区民にとって非常に使い勝手としては、例えば乳母車、高齢者をはじめ私はすごく使いにくいと思うのですが、この辺は何か、スロープはスロープで出入口は必要だとして、一定の水平になるような工事も今回入っているのでしょうか。そうしないと、場所が場所で工事も大変だと思うのですが、その辺のご見解だけ教えてください。","respondent":"高梨公園課長","answer":"今回の公園改修にあたりまして、バリアフリー化をどのように図っていくかというようなところを検討したところ、どうしてもこの細長い公園の全域にわたって今のバリアフリー基準に間に合うようなスロープ等を設置することは困難であるという結論、設計の結果になってあります。","voiceIndex":35,"id":"exchange-006"},{"speaker":"須貝委員","kind":"質問・要望","question":"周りに樹木もあってやや暗い感じもしますし、ぜひ明るく開放感のある、できるだけ皆さんがそこの段にたどり着けるような工夫をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-007"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"今回この西五反田公園改修で３者の入札があって、東急グリーン・日緑建設共同企業体が落札したということで、公園のことについてはあまり私も知らないことがあるので教えていただきたいのですが、３者の応札があって、仮にどこが落札したとしても、基本的にはこの絵に描いてあるような遊具だとか形というものは一緒だという前提なのか。","respondent":"高梨公園課長","answer":"今回の入札はＪＶの形で３者、計６社の名前が記載されてありますけれども、いずれも品川区内の公園の維持管理や、新設公園の改修工事等をやっていただいている会社ですので、この３ＪＶ、３者いずれの会社が落札したとしても。","voiceIndex":38,"id":"exchange-008"},{"speaker":"塚本副委員長","kind":"質問","question":"実施の違いは出ないということで、結果においての品質というかできるものについてはよいということで伺いました。素材だとか人件費だとかいろいろあると思うのですけれども、その辺のコスト削減、安くやるためのノウハウみたいなところで、どういったところがあると受け止めていらっしゃるか教えていただければと思います。","respondent":"高梨公園課長","answer":"価格を抑えるための工夫といったところです。これは各社によって様々やり方はあろうかと思うのですが、昨今建設物価の高騰等もあって、なかなか材料を安く仕入れるというようなところは難しいのかなということを、業者とのヒアリングの中では感じているところです。","voiceIndex":40,"id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それからいろいろな希望もあるじゃないですか。例えばドッグランを造ってくれとか、大きい公園であれば、そういういろいろな皆さんの希望もある。そういうのを一回やったほうがいいような気がしてならなくて、せっかくこのようにお金もかけていい公園ができているので、そこら辺をもっと前に出してやっていただきたいと思っているのですが、こういうのはどうお考えですか、お伺いします。","respondent":"高梨公園課長","answer":"実際公園課のほうにも、ボールを使える公園はどこがありますか、犬が立ち入ることができる公園は一体どこでしょうかというようなお問合せが多く寄せられているところもありますので、広報の仕方等、もっと皆さんに分かっていただけるように、前向きにできるように。","voiceIndex":42,"id":"exchange-010"}]},{"id":"topic-04","title":"第７５号議案、品川区長等の退職手当に関する条例の一部を改正する条例","agenda":"第７５号議案、品川区長等の退職手当に関する条例の一部を改正する条例","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"普通、民間企業ならば、それぞれ東京都在職中は在職中の算定で退職金が出て、また次の会社へ行ったら次の会社の同じような在職期間で出るというのが一般の通例だと思うのです。そうすると、もしそういうことならば、東京都在職期間中の退職金に関しては、これは東京都に請求できるのですか。もらえるのですか。その辺についてお聞かせください。","respondent":"勝亦総務課長","answer":"こちらのほうはあくまでも区のほうで支払いをするという形の考え方です。","voiceIndex":55,"id":"exchange-011"},{"speaker":"須貝委員","kind":"質問","question":"何か日頃、東京都と区で様々な予算の問題でもめていますけれども、こういうときはもう品川区で最後全額払うという、何かちょっと不思議な気もするのですが、一応そういうようなことでほかの自治体でも前例があるということですか。","respondent":"勝亦総務課長","answer":"我々一般職等につきましてもこういった通算規程がございまして、例えば都の職員が国家公務員になった場合は、東京都もそうですけれども、その期間についても退職した時の自治体が支払うというような形で運用しています。","voiceIndex":57,"id":"exchange-012"},{"speaker":"大倉委員","kind":"質問","question":"区の職員でも、今、国のほうに行ったり、出向で都のほうからも来ていただいたりというところがありますが、副区長になると退職手当がまた条例で決まっていて一定だというところで、手当を都の職員として都の期間働いてきて、給与、退職手当が幾らまであって、区に来ると副区長として退職手当が年幾らと条例で決まっている部分が出て、それでまた数年、分からないですけれども。","respondent":"勝亦総務課長","answer":"品川区を退任されて、また引き続き東京都に戻られるような場合につきましては、一番最初に東京都に採用されたときから東京都に在職していたものとみなすという形で東京都のほうでも運用していただいて、最後に東京都を退職するときに全ての期間在職していたとみなして通算して。","voiceIndex":59,"id":"exchange-013"},{"speaker":"大倉委員","kind":"質問","question":"そうすると、品川区で副区長をやっているときの退職手当の計算というのは、都に戻ったときにはどういうふうになるのかというのを教えてください。","respondent":"勝亦総務課長","answer":"東京都の退職手当の取扱いについては東京都のほうで最終的に決定する事項かとは思いますけれども、基本的には職員として在籍していたものとして計算をすると聞いております。","voiceIndex":61,"id":"exchange-014"},{"speaker":"大倉委員","kind":"確認","question":"確認ですけれども、そうすると、東京都の職員としてずっと勤めていたという取扱いになるだろうということでいいでしょうか。","respondent":"勝亦総務課長","answer":"おっしゃるとおり、東京都の職員として在職していたものとして、在職期間、それから給与月額等を計算して、最終的に退職手当を計算、算出することになります。","voiceIndex":63,"id":"exchange-015"},{"speaker":"松本委員","kind":"確認","question":"最後のところの、(3)で都や国に戻らない、ずっと品川区で勤めていただいて終わった場合には、例えばその方が東京都の職員になられたのが２２歳だとしたら、２２歳からどこまで勤められるか、例えば６５歳だとしたら６５歳までの全部を品川区が持つというような立てつけになっているということでよろしいか、まず確認させてください。","respondent":"勝亦総務課長","answer":"おっしゃるとおり、東京都に任用されてからの期間を通算して支払うことになります。","voiceIndex":65,"id":"exchange-016"},{"speaker":"松本委員","kind":"質問","question":"多分これは東京都と調整の上なのだろうとは思うのですけれども、そうすると、逆パターンに穴が空いているのかなと思いまして、それほど事例としてはないかもしれませんが、品川区の職員が東京都の副知事になった場合というのは、東京都側に本件と同じような規程はあるのでしょうか、ないのでしょうか。","respondent":"勝亦総務課長","answer":"すみません、現状東京都知事等の退職手当の状況については確認できておりませんけれども、基本的に考え方は同じになりまして、こういった事情、今回は少し特殊なパターンであるのですけれども、あった場合には東京都と協議をしながら決めていくような形になっております。","voiceIndex":67,"id":"exchange-017"},{"speaker":"松本委員","kind":"確認","question":"今回これまでなかなかなかったような事例ということで対応していただいたと思うのですけれども、ましてや区から副知事になるということはそれほどないのかもしれませんが、ただ、区と東京都は上下関係ではありませんので、こちら側から副知事に抜擢されたときに、この退職金のところで不利にならないようにというところは、これは今回どうのこうのという話ではないし、東京都の話でもあるのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"質問","question":"そうすると、その場合は都の職能はどういう扱いになるのですか。品川区の副区長という職能があるのかどうか。特別職だからどういうふうに職能するのかわからないけれども、そういうランクがないのではないですか。例えば民間では全くそういうのはないから、こういうのがあるということは、そこの職能の部分の評価とかはどういう形で捉えるのですかというのを教えてください。","respondent":"勝亦総務課長","answer":"最終的に東京都が再度東京都の職員として任用するときにどのように取り扱うかというのは、東京都が最終的に判断すると考えています。","voiceIndex":70,"id":"exchange-019"}]},{"id":"topic-05","title":"令和５年請願第１０号、品川区に導入予定の事務事業評価のあり方に関する請願につきましては、予定表４の報告事項(1)行政評価シートの決算特別委員会への提出","agenda":"令和５年請願第１０号、品川区に導入予定の事務事業評価のあり方に関する請願につきましては、予定表４の報告事項(1)行政評価シートの決算特別委員会への提出","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私はそれはいいことだと思っています。それはいいことなのだけれども、それだったら、職員のところという話は何度もしているのだけれども、スクラップがないと、これはこういう事務事業評価とかをやって、では誰がスクラップのところの判断をやるのですか。評価するのも、この評価はいいのだけれども、評価委員会みたいなものをしっかりやっていただくのはいいのだけれども、スクラップはどうするのですか。","respondent":"吉岡政策推進担当課長","answer":"それが今なのかというところにもお答えさせていただいた部分ではありますけれども、このままだと評価作業で職員が疲弊してしまうというようなご意見もございましたけれども、こういった今年度の実施も踏まえまして、今後スクラップのあり方ということも含めまして。","voiceIndex":86,"id":"exchange-020"},{"speaker":"石田（秀）委員","kind":"提案","question":"どうしてそういうことを言うかというと、例えば私はもっと職員の方が新しい事業というか新規事業をいろいろな形で提案して、職員の方々から持ち上がって新規事業を出してくる形がもっとあっていいと思っていて、上から出すのではなくて、そういうところでやってみようよという意識が、特にコロナでそういうのが全くなかったと思っていて、それをせっかくこうなったのだから。","respondent":"吉岡政策推進担当課長","answer":"そういった中で、やはり効果的かつ効率的な行政評価というのは何だろうというところを改めてしっかりと検証させていただいて、この意図を職員にしっかりと理解していただいて、効果のある評価となりますように引き続き検討していきたいと思います。","voiceIndex":88,"id":"exchange-021"},{"speaker":"大倉委員","kind":"質問・要望","question":"何点かご質問させていただきたいのですが、この評価シート自体はどういう基準に基づいてこういった評価の出し方になったのかというのを教えていただきたいのと、今お話があったスクラップを誰がやるのかというところは、非常に大事なところだなと話を伺っていて思いました。","respondent":"吉岡政策推進担当課長","answer":"ＰＤＣＡサイクルの中で、この行政評価、事務事業評価のＣ、いわゆるチェックというところになりますので、なぜこれをやるのかというところをしっかりと理解した上で、職員負担のほうも極力軽減ができるようなシステマチックなやり方といったものも検討しながら。","voiceIndex":90,"id":"exchange-022"},{"speaker":"大倉委員","kind":"質問・要望","question":"職員の負担というところでは、本当にチェックを何度もしていって、また上げてチェックをしてという大変さがあるということは伺っておりますので、一定効率的で効果的なやり方というのはぜひ考えていただきたいと。民間企業とかを見ると、もっと早いサイクルで出したりというところもありますが、そういったことも踏まえて、職員の負担と効率化というところで今後考えていっていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":92,"id":"exchange-023"},{"speaker":"須貝委員","kind":"質問","question":"ですからそれぞれこういう評価を作ってこういう政策をやったけれどもどうだったか。そう考えるとどうなのか。しかしそこの道路をきれいにしても、人が１日に１０人しか通らなかったらどうなのだ、公園も１日に３０人しか利用しなかったらどうなのだ。そういう効率化というのは、私は行政として考えてはいけないのではないかなと思うのですが、すみません、その辺についてまず見解をお聞かせください。","respondent":"吉岡政策推進担当課長","answer":"ですので、今ご指摘にあったその効率性だけで何か評価が決まっていくということではございません。一方で、やはり効率性が悪い部分につきましては、ほかの手法で何か効果的にできないかというところをやはり模索していく必要があるかと思います。","voiceIndex":93,"id":"exchange-024"},{"speaker":"須貝委員","kind":"質問","question":"その区が行政としてやることならば、まず多くの区民の意見を聞く。アンケートでも何でもそうですが、窓口に来たその人達の声を拾う。そしてさらに、今度職員の方がこういう相談があって、こういうふうに改善したらどうですか。そこで１人でも２人でも区民の方を助けられたら、それがやはり行政の仕事ではないかなと思うのですが、その辺についてちょっともう一回ご見解をお聞かせください。","respondent":"吉岡政策推進担当課長","answer":"そういった区民の方の声を広く聞くというところは今までやっているところですので、そちらのほうは当然踏まえながら、この行政評価はそういった部分も評価しながらしっかりと進めていきたいと考えております。","voiceIndex":95,"id":"exchange-025"},{"speaker":"須貝委員","kind":"提案","question":"最後に、我々とすれば、そういう多くの区民の一つひとつの声をできれば開示して、箇条書きでもいいので教えてほしいです。それから職員の方からこういう提案があったとか、こういうふうにすれば、より区民の皆さんが楽になるのではないか、使い勝手がよくなるのではないか、本当に助けられるのではないかという声を、私たちとすれば開示してほしい。一応意見だけ言わせてください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":97,"id":"exchange-026"},{"speaker":"松本委員","kind":"意見","question":"１点今回の請願との関係で、やはり人件費の部分というのが様々な事務事業評価の関係ではここが大事だよねという話が出てきていると思いますので、今回お出しいただいていますこの見本ですけれども、こちらの中で、もちろん人件費の記載はあるのですけれども、人件費との関係でどのように見たらいいのかというところをご説明いただければと思います。","respondent":"吉岡政策推進担当課長","answer":"人件費に関するこのＡ３の行政評価シートの見方というところですけれども、５番の財務情報の1)行政コスト計算書のところですけれども、行政費用にあります給与関係費、あとはそこから少しおりていただいて、その他の上側にあります賞与退職引当金繰入額。","voiceIndex":98,"id":"exchange-027"},{"speaker":"松本委員","kind":"質問","question":"他の自治体の例を見ますと、例えば正職員の方の人件費と非正規の方の人件費ということで分けたりという形を取られているところ、あるいは工数で計算していくというところもあるかと思いますけれども、今回はこういった手法は取られていないということでいいのかと、そういった手法を取られていない理由というのを改めて伺えればと思います。","respondent":"吉岡政策推進担当課長","answer":"正規職員、あるいは会計年度任用職員、こういった部分が各事業ごとに配賦されているというようなところです。","voiceIndex":100,"id":"exchange-028"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１点だけ、何度もすみません。そうすると予算の編成を１％とか、執行率の悪いところをどうしようとか、しかしそれの原因はどこにあって、ではこれからどうしようかというのが必ずあるはずなのです。これはもちろん書くのだけれども、そういうことだけには陥らないようにしていただきたいなと。だって１％というのは、全体を取ればそういうふうに言うのは簡単ですから。お願いでいいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":102,"id":"exchange-029"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"スケジュール的なところで１点だけ確認させていただきたいのですけれども、この決算特別委員会への提出ということで、決算特別委員会が１０月２日から開催されて、行政評価の今後のスケジュールで政策評価委員会が１０月ということになっています。その辺のスケジュールで、一応それを受けてからということになっている段取りなのだろうと思うのですけれども、そこだけちょっと確認です。","respondent":"吉岡政策推進担当課長","answer":"この政策評価委員会のスケジュールというところですけれども、こちらは１０月３０日に政策評価委員会が行われるというところで、一応内容といたしましてはこの政策の評価ですとか、あるいは政策にひもづく事務事業評価。","voiceIndex":103,"id":"exchange-030"},{"speaker":"塚本副委員長","kind":"提案","question":"決算特別委員会等々で多分このシートを使って質問される可能性もあると思います。そこでのいろいろな議会からの意見、提案、そういったものが日程的には無理がないような感じで組まれていると思うのですけれども、どういった形でそれが反映されるのかというのを一応確認させてください。","respondent":"吉岡政策推進担当課長","answer":"今回の政策評価に関しましては、防災と、あと環境という２つの政策分野で行うことになっておりますけれども、そういった議会の中でご意見をいただいた部分については、こういった政策評価委員会の中でも参考にするというところで考えているところです。","voiceIndex":105,"id":"exchange-031"},{"speaker":"塚本副委員長","kind":"確認","question":"理由としては、ご説明が担当理事者からございましたけれども、基本的にここに書かれている請願の趣旨・要旨というところについては包含した形で実施しているということを確認させていただけたし、これからやることであるので、それに対してどのような課題なりが出てくるということは今後考えられますけれども、それは改めて今後、最初の今年度の事務事業評価が終わって報告等をいただく中で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":109,"id":"exchange-032"},{"speaker":"大倉委員","kind":"質問・要望","question":"本日結論を出すということで、態度については不採択でお願いいたします。請願については、この１から６番の全てについて今ご説明いただいたり、議論の中でも確認ができましたが、しっかりと組入れられて行っているということでありますので、不採択ということでお願いできればと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":110,"id":"exchange-033"},{"speaker":"須貝委員","kind":"質問","question":"本日結論を出すということで、今回いろいろ議論しましたが、この請願に対して、要旨の一部に対しては評価できるところもありますが、やはり全体としては私は反対します。不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":111,"id":"exchange-034"},{"speaker":"松本委員","kind":"意見","question":"本日結論を出すで、私としては会派としては採択と申し上げします。もちろん先ほどのお話だと、恐らくそこ自体は工数から始めてこの人件費を出されているので、そういったところは今後またそれほど負担をかけることなくできるのかなと考えています。そういった思いも込めて、本件には採択という意見を述べさせていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":112,"id":"exchange-035"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。理由は、もう何度も先ほど来言いましたけれども、まずこれ自体をどうするか。請願については不採択ですけれども、私はこれについて必ずどういうふうにやっていくか、そちらのスクラップを含めた目的が先だと思っているので、それをまず優先していただきたいと思っていて、この今の請願については不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":113,"id":"exchange-036"},{"speaker":"須貝委員","kind":"質問","question":"すみません。それに、固定資産税はどんどん増える一方で、高級マンションまで建って、もう入っていくならば、区に行く割合の調整もそうですが、やはりもっと２３区に分担してやるべきではないかと私は思って、もともとこれで十分都の経営も運営も成り立っているのですから、そもそも昔の算定で今日まで続いているということに非常に違和感、異常を感じています。意見だけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":121,"id":"exchange-037"},{"speaker":"石田（秀）委員","kind":"質問","question":"いきなり金額がばんと東京都に入る割合が増えるという形で見ればいいのでしょうか。そうすれば、こういうのを区でみんな判断できるようになるわけで、こういうことというのは、時代も変わったけれども、私はそこの部分のそういう議論はあってもいいのかなと思っているけれども、そういうのは全く今は多分議論が出てこないけれども、そういうのをどうお考えなのですか。それは答えられませんか。","respondent":"遠藤財政課長","answer":"現在特別区の中では、固定資産税は区のほうでという話は特に出ていないところですので、まず特別区の中で方向性が示されて、東京都と協議という形になるのかなと考えているところです。","voiceIndex":122,"id":"exchange-038"}]},{"id":"topic-06","title":"令和５年陳情第２８号、政党機関紙の庁舎内勧誘活動の自粛を求める陳情","agenda":"令和５年陳情第２８号、政党機関紙の庁舎内勧誘活動の自粛を求める陳情","exchanges":[{"speaker":"塚本副委員長","kind":"質問・要望","question":"本日結論を出すということで、不採択でお願いします。理由は今の自民党と基本的に一緒で、現状そういう事実がないということなので、不採択ということです。一応今後そういったことがもし仮に職員等からあった場合には、適切に対応していただきたいということはお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":142,"id":"exchange-039"},{"speaker":"大倉委員","kind":"質問・要望","question":"本日結論を出すということで、態度については不採択でお願いいたします。議員からまたそういった購読等がある場合は、ぜひ相談をして対応していっていただくようにしていただきたいと思いますし、またそういった相談ができるような体制もあるというふうに認識しておりますので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":143,"id":"exchange-040"},{"speaker":"須貝委員","kind":"意見","question":"本日結論を出すということと、不採択でお願いいたします。現状、品川区役所内においてこういう事実がないということならば、今回の陳情者がどういう意図でこういう陳情を出したのかちょっと知りようもないのですが、現状問題ないということで、今回については不採択とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":144,"id":"exchange-041"},{"speaker":"松本委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いいたします。一方で、ここに書かれている議員が職員に対してハラスメントを行うという事例は他の自治体では見られておりますし、規則を破って何がしか議員が職員の方に政党機関紙を勧誘するということがなされないように気を付けていただきたいと思いまして、そちらは要望しますが、本日の陳情については不採択という意見を述べします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":145,"id":"exchange-042"},{"speaker":"石田（秀）委員","kind":"質問","question":"結論を出すで、不採択でお願いします。以前にもこのような陳情があったかなと思いますが、そのときもこのようなことはないというお話があったと記憶しておりますけれども、今の説明でも同じような形でありました。私はそういうことも含めれば相談体制もできているということであれば、もしあるならばしっかりその対応をしていただければ、その体制も整っていると考えていますので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":146,"id":"exchange-043"}]},{"id":"topic-07","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"前も聞いたかもしれないですが、こういう工法で下流部シールドするのですが、これは耐久期間として、大体どれぐらいもつものなのですか。教えてください。","respondent":"佐藤（聡）経理課長","answer":"所管から聞いている範囲ということですけれども、基本的には工法としてはシールド工法ということなのですが、下水道に関してはかなり長期間もちまして、現状でいきますと、老朽化工事というのを現在並行して進めているというところがありますので。","voiceIndex":153,"id":"exchange-044"}]},{"id":"topic-08","title":"専決処分の報告について（報告第３０号）","agenda":"専決処分の報告について（報告第３０号）","exchanges":[{"speaker":"大倉委員","kind":"質問・要望","question":"ご説明ありがとうございました。変更概要のところの加湿器というところで、これは加湿器を学校各教室に設置するというのは、なぜこのように急に決まったのでしょうかという、そこについて教えていただきたいと思います。各学校の教室に加湿器があるのかちょっと分からないのですけれども、こうして急に出てきたことについて、どういう経緯なのか改めて教えてください。","respondent":"佐藤（聡）経理課長","answer":"所管に聞いておる範囲ですけれども、加湿器の追加につきましては、新型コロナウイルス感染症の流行前、設計当初はポータブル対応、備品による対応を考えていたのですけれども、その後学校の湿度管理を確実に行うために。","voiceIndex":159,"id":"exchange-045"},{"speaker":"大倉委員","kind":"質問","question":"分かりました。もともと付ける予定だったけれども、もう少し感染症対策も含めて性能のいいものにしたほうが、より子どもの環境衛生を向上させるということで、改めてよろしいでしょうか。","respondent":"佐藤（聡）経理課長","answer":"委員のご趣旨のとおりではありますが、当初はいわゆる備品ということで、物を教室に置くということを考えていたと聞いておりますが、その後の検討の結果、いわゆる天井に加湿器を付けるというような形で整備を考え直したということで聞いております。","voiceIndex":161,"id":"exchange-046"}]},{"id":"topic-09","title":"専決処分の報告について（報告第３１号）","agenda":"専決処分の報告について（報告第３１号）","exchanges":[{"speaker":"大倉委員","kind":"質問","question":"すみません、また変更のところで申し訳ないですけれども、一足制は第四日野小学校改築前も一足制を導入していたという認識で、そのまま、また今回も一足制になるということで始めていたのかなと思うのですが、ここに書いてあるのを読むと、一足制に伴う昇降口、もともと計画としては一足制を導入される予定はなかったけれども、下駄箱を設置してやっていく方向だったのが。","respondent":"佐藤（聡）経理課長","answer":"品川区立小・中学校の一足制に関しましては、本年の２月に文教委員会で報告されておりますけれども、モデル実施ということで始めていると聞いております。第四日野小学校もモデル実施という形で進めていると聞いております。","voiceIndex":167,"id":"exchange-047"},{"speaker":"大倉委員","kind":"質問","question":"今、分かりました。そういうことだということを認識しました。一方で、第四日野小学校はもう改築が進んでいて、もうできているという認識ですけれども、ここは改めて工事をやり直すということでいいのでしょうか。","respondent":"佐藤（聡）経理課長","answer":"第四日野小学校の工事に関してですけれども、先日第１期工期の工事が終了いたしまして、その部分に関しては９月１日から供用開始しています。","voiceIndex":169,"id":"exchange-048"}]},{"id":"topic-10","title":"専決処分の報告について（報告第３２号）","agenda":"専決処分の報告について（報告第３２号）","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"これは専決のことを少しお聞きしたいのですけれども、インフレスライドで構わないのですが、上がっているのでそういうことが出てくると思うのですが、これは現実問題、今、物によっては大分下がってきている、半値近くになってきているものもあったりして、こういう情報というのは行政側として、上げてほしいほうはいろいろな比較をしてどんどん出してきますよね。","respondent":"小林（剛）施設整備課長","answer":"ただ、我々が把握している中では高止まっている状況ですので、極端に今下がっている状況については見受けられない部分がありますが、今後も引き続き情報等を注視していきながら、適切な単価設定あるいは発注金額の設定等については注視したいと考えています。","voiceIndex":176,"id":"exchange-049"},{"speaker":"石田（秀）委員","kind":"質問","question":"あれだけの大規模火災がありますとね。そういうことというのが起きているわけじゃないですか。だからそういうのは、行政側がいろいろな団体からどれだけ情報を取れるかというのはあるかもしれないけれども、そういうところと連携して情報を取ってみたらどうなのかなと思うのだけれども、そういうことはやったことがないような気がしているのだけれども、そういうのは駄目ですか。","respondent":"小林（剛）施設整備課長","answer":"団体との意見交換も、これは金額だけではないのですが、品川区建設防災協議会であったり、先ほどの木材という関係でいきますと、例えば高知県の木材協会は東京の方に窓口がありますので、そういうところと情報共有につきましては常日頃行っているところですが。","voiceIndex":178,"id":"exchange-050"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2276#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":37592,"voices":183}},{"id":"r05-20230926-6","meetingId":"r05-cm09","date":"2023年9月26日","dateIso":"2023-09-26","committee":"区民委員会","time":"午前１０時００分～午前１１時３９分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を22件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和４年度指定管理者による管理に対するモニタリング・評価の結果","agenda":"令和４年度指定管理者による管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"えのした委員","kind":"質問・要望","question":"きゅりあんは利用者からの要望があって、窓口キャッシュレス決済の導入について、令和５年、今年２月から利用を開始したとありますが、キャッシュレスの内容はどの辺まで導入されたのかをお伺いしたいのと、きゅりあんは、利用者からの要望があったということですが、ほかにも総合体育館のほうでも現金のみとしているので、電子申請対応だったり。","respondent":"篠田文化観光課長、三井スポーツ推進課長","answer":"こちらは区全体として取り組んでいるやり方がございまして、クレジットカードですとか、ＰａｙＰａｙとか、そういったものに対して、一般的なものに対して対応していくという形になってあります。総合体育館のキャッシュレス化については、現在まだ検討中でございまして、来年度以降進められるように検討しています。","voiceIndex":7,"id":"exchange-001"},{"speaker":"えのした委員","kind":"質問・要望","question":"私も一区民として総合体育館のほうで、現金で払っていたことがありますので、こちらも進めていただければと思います。今年の夏もかなり暑い日が続いて、熱中症対策なども含めると、こちらのアリーナも冷暖房の効果を、避難所の学校と同程度にしていただきたいなという、区民の方からのお声が上がっております。こちらのほうは、今後の予定などがありましたら、お聞かせ願えますでしょうか。","respondent":"篠田文化観光課長","answer":"現場では、そういった声を受けて、先んじて、例えば冷風機ですとか扇風機、そういったものを設置しているのですけれども、なかなかそれでは厳しいよというお声もいただいているので、現状、施設整備課と調整して、何ができるのかといったことを検討している段階です。","voiceIndex":10,"id":"exchange-002"},{"speaker":"えのした委員","kind":"意見","question":"私も扇風機ですとか、そういうのをしているという話は聞いていたのですけれども、能力は変わらないというお話ではありますが、体感的にガラス張りというところがあるようであれば、快適な、避難するような事態がないに越したことはないのですけれども、万が一の場合のためには、施設整備課の方とできるだけ早めにそういった調整をしていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":12,"id":"exchange-003"},{"speaker":"山本委員","kind":"質問・要望","question":"それぞれ質問します。足元の利用者満足度が９０％程度と、すごく高いことはとてもいいことだと思うのですけれども、前年度と比較すると、５ポイントほど下がっているなというのが目に留まりまして、それはなぜかということをお聞きしたいのと、あとはそれに先立ってどういうアンケートの取り方をしているからこういう形になるというところ、アンケートの取り方についても教えていただければと思います。","respondent":"小林商業・ものづくり課長、篠田文化観光課長、三井スポーツ推進課長","answer":"その中で施設全体の満足度ということで、これまで実施してきたところでは、例年９割前後の満足度をいただいているところです。今、手元にその辺の細かい集計したものを持ってきていないものですから、個別の例としては申し上げられないのですけれども、私の記憶にある限りでは。初めに、電子申請とキャッシュレス決済の話になりますが、キャッシュレス決済のほうは、令和６年度以降順次検討していくというお話をしたのですが。","voiceIndex":13,"id":"exchange-004"},{"speaker":"山本委員","kind":"質問・要望","question":"それぞれ、ありがとうございました。今後ともよろしくお願いします。それから、プロスポーツのところは、やはり今までやっていらっしゃる方々との調整があるというのも理解しておりまして、急にすぐに使えなくなると、それは使っている区民の方々の立場がどうなのだというのもありますので、そこは段階的に理解を得ながら、ぜひコミュニケーションを取って進めていただきたいというのが要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-005"},{"speaker":"あくつ委員","kind":"確認","question":"幾つか確認をさせてください。ＳＨＩＰなのですけれども、「評価の視点」別のコメントのところ、２枚目の２、予算執行（財務）の視点というところで、収入については、「３階ホール、４階ラウンジ会費・オフィス使用料のいずれも予算見込みを上回る利用料収入を確保した」と。まあ、マイナスですね。赤字という言い方が正しいかどうか分かりませんが。","respondent":"小林商業・ものづくり課長","answer":"３階のほうは、基本的にイベントの内容につきましては、借りたところがそのまま実施しているという、その大きな違いがあるというところが、この財務の構造の違いです。","voiceIndex":18,"id":"exchange-006"},{"speaker":"あくつ委員","kind":"質問","question":"分かりました。予算執行（財務）の視点のところで、「予算枠内での執行に取り組んだ」というコメントになっているので、ということは今のご説明だと、そもそも４階はマイナスになる前提で運営をしているということなのだと思うのです。これはもう当初からそういうことであって、今後何か黒字化を図っていくとか、そういうことは特にない、これは難しいということなのでしょうか。","respondent":"小林商業・ものづくり課長","answer":"お尋ねのとおりでございまして、４階につきましては、区内企業、あるいは起業家の皆さんに対するソフト事業の充実をしっかりやっていくということで、予算を立てるときから、これは指定管理料の支出を前提とした予算を組み立てておりますので。","voiceIndex":20,"id":"exchange-007"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私も、この間ＳＨＩＰでの会議など、何回か参加させていただいて、非常にいい施設だなと思って、今後とも活用をさせていただきたいと思います。戻ってこられるような仕組みになっているのかがちょっと心配で伺いたいということと、予算執行の視点の最後に、「補助金を積極的に活用」という言葉が、こことスクエア荏原のほうも出てくるのですかね。この補助金というのは何を指しているのかを教えてください。","respondent":"篠田文化観光課長","answer":"導入したというのは、もともとあったのですけれども、一応例外扱いとしてやっていたものを通常の形として導入したという形になります。こちらに関しましては、引き続き利用できるように、支払いに来ていただかなくてもいいような対応を今やっているという状況です。","voiceIndex":22,"id":"exchange-008"},{"speaker":"あくつ委員","kind":"意見","question":"１０月の頭に大ホールのこけら落としということで、能をやるということですけれども、舞台装置の方が戻ってこられるということで、非常によかったと思います。最後の口座振替のところも、私はそこを見逃していましたけれども、これはやっていただいているということで、承知しました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":24,"id":"exchange-009"},{"speaker":"横山委員","kind":"質問・要望","question":"ご説明、ありがとうございました。１つずつ伺ってまいります。そこで確認なのですけれども、現在想定しているキャパシティの上限のようなものはあるのでしょうか。たくさんご利用いただくというのはすごく喜ばしいことなのですけれども、利用のしづらさにつながってしまったり、ウェブ会議などニーズの変化もあるかと思いますので、その辺りの状況を確認させていただきたいと思いました。","respondent":"小林商業・ものづくり課長","answer":"上限値というのは何か規約とかルールを定めているものではございませんけれども、４階のコワーキングスペースの中で、我々は、そこである程度作業を毎日継続してできるようにロッカーを提供しているのですが、その上限というのが大体ありまして、それからいきますと今現在。","voiceIndex":25,"id":"exchange-010"},{"speaker":"横山委員","kind":"質問・要望","question":"ご説明ありがとうございました。次に、きゅりあんです。３のサービス向上および業務改善の視点なのですけれども、「利用者からの要望が多い従来の来館による抽選会を再開する」と記載があります。抽選会は実際ご自身でいらっしゃってやりたいということだとは思うのですけれども、どういった理由からそのようなご要望になっているのかなという背景が分かりましたら、教えていただけたらと思います。","respondent":"小林商業・ものづくり課長、篠田文化観光課長","answer":"そこには会員以外の方も含まれるわけですけれども、例えば、セミナーの内容、あるいは時間の長さはこれぐらいでいいのかとか、講師の先生には、引き続きまたこういう人を呼んでほしいのか。私からは、まずきゅりあんの利用者アンケートの関係です。昨年は実施していなかったので、それ以前のアンケートに対する対応状況という形になろうかと思います。申し訳ございません。","voiceIndex":27,"id":"exchange-011"},{"speaker":"横山委員","kind":"質問・要望","question":"といいますのも、所管はちょっと違うのですけれども、健康センターも同じくトレーニング室といいますか、トレーニングルームには例えば、体重計ですとか、様々な測定機械みたいなものが置かれていまして、あくつ委員の会派で今回の一般質問でもありましたけれども、女性の健康もそうですし、女性だけではなくて、様々な方が運動してその後どういった成果が出ているのかということをリアルタイムに把握して。","respondent":"三井スポーツ推進課長","answer":"電子申請、キャッシュレスのほうは検討をそのまま進めていきたいと思います。トレーニング室なのですけれども、申し訳ありません、今回資料を持ち合わせておりませんで、体重計のどういうものが設置されているのかというのは確認して、別途回答させていただければと思います。","voiceIndex":30,"id":"exchange-012"},{"speaker":"横山委員","kind":"質問・要望","question":"ちょっと細かいことを聞いてしまいました。ぜひ確認していただいたり、また保健センターですとか、そういったところと連携していただいたり、またスポーツ協会も様々な知見等をもっていらっしゃるかと思いますので、確認していただきながら、総合的に区民の皆さんの健康の増進につながるような形で考えていただけたらなと思います。要望で終わらせていただきます。","respondent":"篠田文化観光課長","answer":"抽選会の関係です。抽選会に関しましては、今移転中に関しましては、こみゅにてぃぷらざ八潮までおいでいただくのが難しいということで、職員が代行していたのですけれども、委員ご指摘のとおり、やはり基本的には利用者がご自身の目で見て確認したいという思いが強うあります。","voiceIndex":32,"id":"exchange-013"},{"speaker":"藤原委員","kind":"質問","question":"そもそもなのですけれども、指定管理者の制度を導入した理由を教えていただけますか。","respondent":"篠田文化観光課長、三井スポーツ推進課長、小林商業・ものづくり課長","answer":"ご案内のとおり、指定管理者制度は、役所がやるよりも合理的で効率的な事務運営、施設運営を目指して国のほうで導入されまして。体育館につきましても、効率性と専門性、効果的に民間にやっていただくということで、指定管理制度を導入しているものです。ただいまの２人の課長の答弁ともちょっと重なる部分もありますけれども、特にＳＨＩＰの中では、品川ビジネスクラブ。","voiceIndex":34,"id":"exchange-014"},{"speaker":"藤原委員","kind":"質問・要望","question":"ＳＨＩＰにしても、再任用の方が行かれていますよね。その連携というのがすごくうまくいっていて、私はすばらしいと思っているのですけれども、やはり緊張感、やはりこういう仕事で、こういうふうにしていかないと、５年後という思いとか、緊張感でやっていっていただきたいと思っているのですよ。その辺については、所管ではどういうふうに考えてやっているのか、その辺について教えていただけますか。","respondent":"小林商業・ものづくり課長、篠田文化観光課長、三井スポーツ推進課長","answer":"そういうものを指定管理者の選定の手続きの中で、きちんと新しい創意工夫なり、意欲というのが出ているかどうか。ただ、これも緊張感をもってやっていかなければ、入替えというのは当然想定されるところですので、それは文化振興事業団のほうも認識していますので。５年間、また５年間ということで、それでは緊張感がなくなってしまうということは本当にあるかと思いますので。","voiceIndex":38,"id":"exchange-015"},{"speaker":"藤原委員","kind":"確認","question":"今、文化観光課長が答弁してくれたことで、すごく安心しました。いや、どうせ申し込んでも、あそこは決まっているからとならないように、様々な事業者が来てほしいと心から思っています。そうですね。これだけ質問しておいて最後にちょっと言いますが、今の指定管理者、事業者は、私の評価は高いですから。でも、議員として確認だけをさせていただきました。今後ともよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-016"}]},{"id":"topic-02","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"西村委員長","kind":"確認","question":"進め方としましては、まず事前に配付しましたこちらのクリーム色の冊子を基に、私から視察先について概要を、とても簡単にお話ししますので、その後で視察先への質問や確認したい事項などがございましたら、ご発言をお願いしたいと考えています。本当に早口でお話ししてしまったのですが、視察先で特に質問や確認したいことがございましたら、今おっしゃっていただければと思います。いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-017"},{"speaker":"あくつ委員","kind":"質問・要望","question":"いろいろご調整いただいて、ありがとうございました。ありがとうございました。迷わない！お亡くなりになった場合の手続きの一覧が１５７ページと１５８ページにありますが、昨日も議論になっていたところで、これ以外に、何か冊子みたいなものがあるのか、分かりやすいパンフレットみたいなものがあるのかどうか。ちょっと取ってつけたような質問ですけれども、３つぐらい挙げさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-018"},{"speaker":"横山委員","kind":"質問","question":"長崎市のほうは、ＤＭＯとの連携や観光マーケティングの基盤づくりというところとちょっとかぶってしまう部分もあるのですけれども、１１９ページの「ＡＩなどを活用したデジタルマーケティングの強化」であったり、ＭＩＣＥ誘致などを、今までの分析等だけではなくて、ＡＩ等をどういうふうに使ってやっているのかというところはお聞きしたいなと思いました。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-019"},{"speaker":"あくつ委員","kind":"質問","question":"イメージということで、１１月１日の長崎市は、午前中に長崎市の新しい市役所に全員で行って、観光の所管課からこのことを聞いて、おくやみ窓口も見て、お昼には終わるということで、２時間ぐらいを想定しているでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-020"},{"speaker":"あくつ委員","kind":"質問","question":"質問が結構たくさんあるから、あちらとしてもいっぱい答えたいでしょうし、こちらもいっぱい聞きたいと思うので、時間はたくさんいただいていたほうがいいですね。","respondent":"西村委員長","answer":"２点目は、もし視察の行程途中で発熱されたという方が出た場合も想定しておくということで、委員、同行理事者、書記のうち視察の行程の中で発熱された方が出た場合には、ほかに感染している方がいる可能性や感染が広がる可能性があるため。","voiceIndex":58,"id":"exchange-021"},{"speaker":"横山委員","kind":"質問","question":"昼食は移動中も可能性があるというお話もあったのですけれども、１日目ですか。どういう感じで予定されているのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-022"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2970#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":32019,"voices":61}},{"id":"r05-20230926-7","meetingId":"r05-cm09","date":"2023年9月26日","dateIso":"2023-09-26","committee":"厚生委員会","time":"午前１０時００分～午後 ３時４４分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を94件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"意見書（案）","agenda":"意見書（案）","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"忙しい中、ありがとうございました。ただ１点だけ、３段落目の最後のほうなのですけれども、こうした事態を受け、世論調査では、健康保険証の廃止について「延期」を求めるということになっているのですけれども、「延期・中止」を求める声が７割というふうにしていただけたらと思います。たしか、三十何％ずつで、両方合わせて７割という、それが世論調査の結果だと思うのですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":4,"id":"exchange-001"},{"speaker":"こんの委員","kind":"質問・要望","question":"昨日の結果を受けて、このような意見書が出されているのは理解しておりますが、昨日も態度表明をさせていただきましたということもあって、今回これについては提出者にならないということで考えております。延期を求める。そのことを公明党としても国に訴え、国民の不安を払拭することが前提ということも求めてきましたので、現時点で出す意見書ではないと、このように反対いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":6,"id":"exchange-002"},{"speaker":"こしば副委員長","kind":"質問","question":"私も、昨日の審議では、態度表明のところで不採択、請願の趣旨、願意には沿わないということで質問させていただきましたので、私もこんの委員同様に提出者として名前を出さない方向でお願いしたいと思います。という意味で、意見書には反対をします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":8,"id":"exchange-003"},{"speaker":"やなぎさわ委員","kind":"意見","question":"先ほどのこんの委員とこしば副委員長の反対の表明、提出者にならないというのは理解しました。ただ、そういったことも踏まえての議論がきのう行われたと承知しておりますので、私は賛成として署名いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":12,"id":"exchange-004"},{"speaker":"筒井委員","kind":"質問","question":"この意見書のなかの延期ということはいいのですけれども、一番最後の段落のところで、この状況ですと、何か無期限に延期をするということにも捉えられるかもしれないので、私としては、無期限ではなくて、やはり一定の期間があるということはしかるべきで、いつまでもだらだらとやるわけにはいかないという考えを持っておりますので、ですから、最後の段落の令和５年秋の健康保険証の廃止を一定期間延期しと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-005"},{"speaker":"鈴木委員","kind":"質問","question":"書かれているので、それは、どれぐらいかかるかというのは分からないので、それが一定ということだと思うのですけれども、その一定というのは、国民が安心して利用できる環境が整うということが一番必要なわけではないですか。それが整わないで強行するということをやめてくださいよということなので、ここの中に入っているのではないかと思うのですけれども、それでは駄目ですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-006"},{"speaker":"筒井委員","kind":"質問・要望","question":"ちょっとあまりにも環境が整うまでというと、ちょっと抽象的過ぎるかなということで、それは本当にただ１人の反対意見も出ないような状況まで延期しなければいけないのかとなると、それはあまりにも不合理というか現実的ではないので、例えば世論調査の延期中止を求める声がゼロ割にならなければいけないのかというと、それはまた違うと考えていますので、現状は７割ですけれども、２割、１割。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-007"},{"speaker":"筒井委員","kind":"確認","question":"この数字の客観的根拠があるのですか。〔「あります」と呼ぶ者あり〕それを確認していただいて。〔「３０」と呼ぶ者あり〕そのとおりでしたら、そのままで。「延期・中止」。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-008"},{"speaker":"ひがし委員","kind":"意見","question":"確か昨日の請願にも持ってきていて、細かいデータがあったと思うのですけれども、そこをもう一回調べて、データが正しいとすると、延期と中止を合わせてちょうど７割ぐらいだったかな。そこは確かに事実を載せたほうがいいのかなと思うので、調べた上でそれが間違っていなければ、「延期・中止」でいいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":36,"id":"exchange-009"},{"speaker":"ひがし委員","kind":"意見","question":"個人的にはそれは多分書かなくても後半の部分で賄えている気がしているので、あえて載せる必要性というのは、そこまで感じはしないのですけれども、ほかの委員たちがそれでいいのだったら反対するところではありません。もともと載せなくても、この後半の部分に理由が書かれているので、あえて。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":39,"id":"exchange-010"},{"speaker":"鈴木委員","kind":"意見","question":"だから、６人が一致できるというふうなところでやったほうがいいかなと思うので、「一定」というのを入れたほうがいいという意見があって、それがどうしても駄目だということでなければ、入れればいいかなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":44,"id":"exchange-011"},{"speaker":"鈴木委員","kind":"意見","question":"廃止を延期すべきが３７％、それで撤回すべきが３２％、合わせてということで、データとして出ています。多分これはいろいろなところで、そういうデータが出ていますので間違いない。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":46,"id":"exchange-012"}]},{"id":"topic-02","title":"令和４年度指定管理者の管理に対するモニタリング・評価の結果","agenda":"令和４年度指定管理者の管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"おぎの委員","kind":"質問・要望","question":"全般的に見回して、１点質問させてください。コロナ等の問題もあり、利用者が減ったとかいろいろあると思いますが、毎回話題になる人件費も、あまりマイナス続きだと上げづらいのかなという業者も、経営のほうも心配になりますが、赤字が続いている状況の施設について大丈夫なのでしょうか。区の相談とか、そういった体制などは整っているのかお聞かせいただきたいと思います。","respondent":"松山障害者支援課長","answer":"今事業者もご努力していただきまして、区のほうもコロナの業務継続支援金ですとか、実際に感染対策の物品ですとか、できるだけ指定管理者のほうにバックアップを継続はしています。","voiceIndex":57,"id":"exchange-013"},{"speaker":"ひがし委員","kind":"質問","question":"そこで、働いている人が安心して働いていくために、この結果というのは指定管理の方々が出してくださった評価を区として見て評価して出されているモニタリングだと思うのですけれども、働いている方々の本当の声というか、働きやすさみたいなところが、ここにはなかなか出てこないところもあるのではないかなと思うのですけれども、社会保険労務士と対面させて。","respondent":"菅野高齢者福祉課長","answer":"これは指定管理者制度の中で、指定されてから３年目ということなので、５年の指定期間のうち必ず１度は指定管理施設はやるというような形になっておりますので、その中で労働環境がどうなのかというところは、チェックをさせていただいているところと。","voiceIndex":62,"id":"exchange-014"},{"speaker":"ひがし委員","kind":"質問・要望","question":"第三者の目が入っているということを聞いて、とても安心しました。やはり、自分も医療現場で働いていて、評価というのを、病院に対する評価とか、働き方の評価をしていて、そこから結構部署の改善とかが図られていたので、その結果をぜひ区のほうでも確認をして、連携をしてアドバイスができるような関係性を作っていただきたいなというふうに思います。もう一点だけ。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-015"},{"speaker":"筒井委員","kind":"確認","question":"ちょっと確認を含めてお聞きしたいと思うのですけれども、高齢者福祉課所管施設分、また障害者支援課所管施設分の施設、先ほど、収支が、赤字がずっと続いているのがかなり目立つのですけれども、それに対して区として補填などは行わず、翌年度の指定管理料、運営委託料とかで調整していくということでよろしいのでしょうか。","respondent":"菅野高齢者福祉課長、松山障害者支援課長","answer":"赤字の部分についての補填というところなのですけれども、このモニタリング・評価で赤字が出ているからすぐ補填を行うというわけではなく、先ほども障害者支援課長が申し上げましたが、そこでモニタリングも得て、状況の確認もして。ただし、コロナの件でちょっとその間厳しい状況にあるところもこちらのほうでは状況把握をしておりますので、区と一緒になって、区に代わって指定管理を行っていただいておりますので、区として支援できることというものを。","voiceIndex":66,"id":"exchange-016"},{"speaker":"筒井委員","kind":"意見","question":"分かりました。一方、高齢者地域支援課所管分の施設は、結構黒字が続いているのかなと思いまして、障害者支援課所管分の施設と高齢者福祉課の所管施設とのこの差はなぜ生まれたのかということと、収支の表の載せ方が、高齢者福祉課所管施設と何か、なかなか違うのか、特に人件費が載っていないのですけれども、それはどういった理由なのかをご説明願います。","respondent":"川原高齢者地域支援課長","answer":"高齢者地域支援課に記載をしております収支の内訳についてだけ人件費の記載がないのかという部分について、ご説明をします。指定管理料の中の収入の一番上の項目、例えば７ページ、東品川わかくさ荘を見ていただきますと、管理運営委託料というふうに書かれてあります。","voiceIndex":69,"id":"exchange-017"},{"speaker":"筒井委員","kind":"意見","question":"支出の項目のところで、人件費というのが載っていない。これはどういう、例えば３ページ、事業運営費の下は書いていないけれども、人件費とかはどうなっているのかなというふうに思いまして、その辺りを。","respondent":"川原高齢者地域支援課長","answer":"委員ご指摘のとおり、こちらの支出の部分に人件費という項目は出していない形です。いずれも施設運営費の中に含まれているような表記をしているためです。","voiceIndex":71,"id":"exchange-018"},{"speaker":"筒井委員","kind":"質問","question":"おいおいまた別の機会にも伺いたいと思います。高齢者福祉課所管施設分のモニタリングのご説明で、２ページに虐待防止委員会というのが、２ページの４番目のところに書いてあるのですけれども、これは在宅支援の現場でもこうした虐待というのが過去にあって、こうした委員会が設置されたのか、そしてほかの施設でも一律こうした虐待防止委員会というのがあるものなのか、そうしたことを教えてください。","respondent":"菅野高齢者福祉課長","answer":"施設によって、この辺りのところはいろいろ会議体の設置の仕方があると思うのですが、ここの品川総合福祉センターの八潮在宅サービスセンターにおける虐待防止委員会というのは、例えばデイサービスで通所されている方が、入浴のときにあざがあるとか。","voiceIndex":75,"id":"exchange-019"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。そうしたことで、いろいろそうしたご家族とかにアドバイスとか、予防的な措置のためにそうした委員会を開いてチェックをしていこうという試みでこの委員会があるということでよろしいのでしょうか。","respondent":"菅野高齢者福祉課長、松山障害者支援課長","answer":"こちらの２ページのところにも記載されておりますが、例えば各職員が気になっていることの共有ということで、デイサービスの送迎時に変わったことがある場合など、早期に確認して関係機関とも連携したというところなので。要は、ヒヤリ・ハットも含めた委員会であると認識しております。","voiceIndex":77,"id":"exchange-020"},{"speaker":"筒井委員","kind":"質問・要望","question":"最後に、健康センターのところなのですけれども、このデータは品川健康センターと荏原健康センターを合わせたデータなのでしょうか。品川健康センターと荏原健康センター、まだ何か施設によって、特色とか利用者のニーズとかが違ってくるかなと思っているのですけれども、このデータについて、合わせてのものなのかを確認させてください。","respondent":"若生健康課長","answer":"こちらの健康センターの部分については、品川健康センターと荏原健康センターを合わせたデータになってあります。","voiceIndex":80,"id":"exchange-021"},{"speaker":"筒井委員","kind":"質問・要望","question":"分けて評価結果を出していただくと大変ありがたいのですけれども、その点いかがお考えでしょうか。","respondent":"若生健康課長","answer":"指定管理業務として品川区立健康センターというので、一つの指定管理業務として行っているという位置付けで、報告としては、当然毎月の業務報告等では品川健康センター、荏原健康センター、それぞれの状況というのは指定管理者から聞き取ったり。","voiceIndex":82,"id":"exchange-022"},{"speaker":"筒井委員","kind":"質問・要望","question":"そうしたほうがこうした議会での評価もしやすいのかなと考えていますので、例えばコメントに（品川健康センター）とか、別なコメントに（荏原健康センター）とか、どの健康センターで、こうしたお声が出たのかなとか、ちょっと分かりやすく表記していただくとありがたいので、今後ぜひともご検討をよろしくお願いします。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-023"},{"speaker":"おぎの委員","kind":"質問","question":"ちょっと細かいところの内容になるのですが、もし分かっていたらお聞かせください。西大井つばさの家の評価の１７ページ、積極的に評価した事項というところに、品川区知的障害者グループホーム連絡会というものが出てきますが、こちらはどういった連絡会なのでしょうか。","respondent":"松山障害者支援課長","answer":"１７ページの西大井つばさの家の品川区知的障害者グループホーム連絡会ですけれども、区内の知的障害者を対象とした区立、民間を問わず、全ての事業者に西大井つばさの家の指定管理者の社会福祉法人福栄会が声をかけさせていただいて、一緒に情報交換をしたり。","voiceIndex":86,"id":"exchange-024"},{"speaker":"おぎの委員","kind":"意見","question":"法人がいろいろありますけれども、こういった横のつながりで連携をとっているということを聞いて、すごく心強いなと思いました。ぜひこういったことは区からも後押ししてあげたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":88,"id":"exchange-025"},{"speaker":"鈴木委員","kind":"質問","question":"ちょっと障害者のところから伺いたいのですけれども、先ほどの虐待のところなのですけれども、虐待の件について、相談件数とかがどれぐらいあるのかというのが、虐待の相談というのがどれくらい、ちょっと法人ごとにあるのかもしれないのですけれども、全体でも結構ですし、ちょっと相談がどれくらいあるのかというのを伺いたいのと、多分認定されたものというのはないのかと思うのですけれども。","respondent":"松山障害者支援課長","answer":"障害者の虐待防止に関する状況ですが、事務事業概要のところにご報告させていただいているのですけれども、相談、通報の受理件数は、令和４年度で２７件ということで、令和３年度も２７年、その前が、令和２年度が２０件でしたので。","voiceIndex":90,"id":"exchange-026"},{"speaker":"鈴木委員","kind":"意見","question":"身障者会館のところなのですけれども、２ページの対応方針というところで、「医療的ケアの必要な障害者の受入れ態勢を整えていることを積極的に発信するとともに、利用促進、稼働率の向上を図る」と書かれているのですけれども、３ページのほうを見ると、「職員の人員体制を２対１の加算体制にして、看護師を２名体制とした」と書かれているのですけれども。","respondent":"松山障害者支援課長","answer":"看護師の２名配置というのもそもそもしておりましたので、また、あと、医師が週に１回回診しているという手厚い状況ではありますが、今のところ、ちょっと、その方の状況は、お一人になってしまうので、あまりにも限定的な状況になってしまうので、ちょっと差し支えますので。","voiceIndex":92,"id":"exchange-027"},{"speaker":"鈴木委員","kind":"質問","question":"分かりました。ということは、体制としては、今１人ですけれども、これから希望される方がいらしたら、定数は何人ぐらいまで受け入れられるのか。多分ピッコロでも、人工呼吸器の方は受け入れてないので、ここも人工呼吸器を受け入れるというところまでは行かないで、今でもやはり人工呼吸器を受け入れてくれるところは、まだ、ちょっとないというふうなことで考えていいのでしょうか。","respondent":"松山障害者支援課長","answer":"今のところ、なかなかこれだからという状況にはないですけれども、これだから受け入れる、受け入れないということはここでは答弁はできませんけれども、その方の状態によるということと運営体制、運営体制というのは人員体制だけではなく、そのほかの方の状況にもよるです。","voiceIndex":94,"id":"exchange-028"},{"speaker":"鈴木委員","kind":"質問・要望","question":"２７ページのぐるっぽの問題なのですけれども、令和４年９月から、ぐるっぽが、これまではグロー・ゆうゆう・愛成会が指定管理者をしていたのが、３年間で福栄会に替わったわけですけれども、本当にこれはどういうふうになっているのかというのをちょっと伺いたいのですけれども、このときに職員もそれまでゆうゆうとか愛成会とかでお仕事をされていた方が、福栄会になったとしても。","respondent":"松山障害者支援課長","answer":"障害児者総合支援施設ぐるっぽについてのお尋ねです。１０月から福栄会ということで一本化して指定管理となりました。","voiceIndex":96,"id":"exchange-029"},{"speaker":"鈴木委員","kind":"質問","question":"それも、どうしてこんなに下がってしまったのか、相談を希望する人というのはすごく多いのではないかと思うのですけれども、それは、人員体制とかも取れないとか、そういうこともあるのか、ちょっとそこら辺の中身について伺えたらと思います。","respondent":"松山障害者支援課長","answer":"子ども発達相談室なのですが、すみません、説明の中でお伝えすればよかったのですが、令和３年度から令和４年度にかなり減って見えるのは、少しカウントの仕方が、統計の仕方が前の指定管理者と異なっておりまして、実質的には、実際。","voiceIndex":98,"id":"exchange-030"},{"speaker":"鈴木委員","kind":"質問","question":"それと、あと令和４年度に委託料は増やしていますけれども、赤字になっているというのは、これは１年目で引継ぎとかで重ねて配置するとか、多分そういう部分もあったと、そういうことで考えて、こういう収支、そして事務費がすごく増えているのですけれども、そこら辺のところも、なぜこうなっているのかというのが分かったら教えてください。","respondent":"松山障害者支援課長","answer":"先ほど体制についても出ていましたけれども、体制につきましては強化をいたしまして、現在では地下のクリニックのところを子ども発達相談室の場所として使用しまして、１日複数件、場所を増やして、また人を増やして、相談に対応しています。","voiceIndex":100,"id":"exchange-031"},{"speaker":"鈴木委員","kind":"質問","question":"愛成会がやっていたところなのですけれども、３０ページですが、ショートステイが６名から令和４年に１２名に増えて、倍に増えたにもかかわらず、今すごく使えないという話を聞いていまして、今までは、毎月１週間ぐらい使えたのが、２日ぐらいしか使えないということで、そういう話を何人かの方から伺っているのですけれども、これは６名から１２名に増やすキャパシティーはあったということなのですか。","respondent":"松山障害者支援課長","answer":"でも、いずれにしましても、企業就労の人気は高く、ほかの就労継続支援Ｂ型も苦戦しているような状況です。","voiceIndex":102,"id":"exchange-032"},{"speaker":"鈴木委員","kind":"質問・要望","question":"今回のぐるっぽなのですけれども、去年の１０月から福栄会になって、それまでのぐるっぽの満足度というのはすごく高くて、利用者や障害者団体の方々から事業者を替えないでという声がたくさんある中で福栄会に替わったわけですけれども、そのときにやはりこれまでのサービスを低下させないと、そういうものがあったと思うのですけれども、でも実際に福栄会に替わったときに、これまでと違うだったりとか。","respondent":"松山障害者支援課長","answer":"ぐるっぽに限らず、ほかの指定管理施設もそうですけれども、地域的には指定管理者にご相談いただくというのが一番かと思います。それでもなかなかということでしたら、区のほうにご一報いただくのが通常の流れです。","voiceIndex":105,"id":"exchange-033"},{"speaker":"やなぎさわ委員","kind":"質問","question":"障害者支援課管轄の３３ページの相談件数なのですけれども、前年度のモニタリングに比べて、令和２年とか令和３年は１万件を超えていたと思うのですが、今回、件数が変わっているというか、変更になっている。これは何か理由がありますでしょうか。","respondent":"松山障害者支援課長","answer":"３３ページの相談件数。","voiceIndex":109,"id":"exchange-034"},{"speaker":"やなぎさわ委員","kind":"質問","question":"続けていきます。改善が必要とされる原因と分析。これは一般的なところですけれども、例えば、前年度とかと同じような内容が何年も続いたりとかしている場合とかというのは、区で例えば指導したりとか、そういったことは行っていますでしょうか。","respondent":"松山障害者支援課長","answer":"全般的に、通常改善が必要な事項としては、改善が必要な事項というのを、ご自分たちで自己分析をして上げてきているものですので、指定管理者としても認識をしていると。","voiceIndex":115,"id":"exchange-035"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ほかのところは大体７件見ると６５％ぐらいとか、高いと７０％ぐらいの人件費率のところで黒字になっているところもあるというところを見ると、一応このモニタリングの中で、設備投資があったというような記載もあるのですが、令和３年度も同じような人件費率で赤字になっているので、何か特別な事情があるのかとちょっと推察されるのですが、何か区としての受け止めというか。","respondent":"菅野高齢者福祉課長","answer":"７１ページの、杜松特別養護老人ホームの件だと思いますので、お答えします。","voiceIndex":117,"id":"exchange-036"},{"speaker":"やなぎさわ委員","kind":"意見","question":"そうですね、やはりもともとの人数が少ないというのが、ほかの、７つある特別養護老人ホームの中で、多分特徴のところだとは思っていたのですけれども、つまり、ショートステイも１１５％となっていて、実際にはもう少し、１００％を超えているけれども、伸び代があるのかなと思いつつも、でもやはり特別養護老人ホーム自体が９４.９％ということで、かなり埋まっていて。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":119,"id":"exchange-037"},{"speaker":"こんの委員","kind":"質問・要望","question":"全ての所管で共通にまず確認をさせていただきたいのですけれども、それは心身障害者福祉会館のほうで参考にあります。「監視カメラの設置、夜間の機械警備により、不審者の侵入・不審物の持込みに備えている。救急１１０番を設置して、防犯設備・防犯意識強化を図っている。全体的に、それぞれの事業者でも、こうした施設での対応はどうなっているのか、その辺をまず確認させてください。","respondent":"松山障害者支援課長、菅野高齢者福祉課長、川原高齢者地域支援課長、若生健康課長","answer":"ご質問いただきました防犯や危機管理意識に対しての対策なのですが、こちらの会館以外でも、それぞれの施設できちんとですね。高齢者施設においても障害者施設と同じように、安心・安全を重視し、地域に開放しつつも、例えば認知症高齢者の方が。高齢者地域支援課が所管する８施設のうち４施設の住宅に関しては、緊急の通報装置を設置しているような形です。健康センターにつきましては、指定管理業務の中に施設の維持管理の項が入っておりまして、こちらについては。","voiceIndex":121,"id":"exchange-038"},{"speaker":"こんの委員","kind":"質問","question":"ご答弁のとおりだというふうに思います。やっていらっしゃらないということはないだろうと思っておりました。このやっているというところのモニタリングも、きちんとされたらどうですかというのが１つです。それぞれお答えいただければありがたいです。","respondent":"松山障害者支援課長、菅野高齢者福祉課長、川原高齢者地域支援課長、若生健康課長","answer":"実際、モニタリングの際には、それぞれの現場の施設に行き、緊急１１０番とかを確認しておりますけれども、ただ、より防犯意識。高齢者福祉施設におきましても、例えばこのモニタリングの総括シートのところの４番の組織管理体制や業務の適正執行などのところに。ゆうゆうプラザに関しても同様に防犯への取組というところで報告は上げてはいただいているところですので。そういったものも含めまして、今後適切にこういったところをお知らせできるような形を検討してまいりたいと思います。","voiceIndex":126,"id":"exchange-039"},{"speaker":"こんの委員","kind":"提案","question":"今、把握の数字がもしなければ、それはそれなのですけれども、後で教えていただければいいのですが、そうしたことの、働きかけというのですか、常に防犯意識で何をどうしておいたら入居者の、未然に防げるのかという発想というところを持ち合わせて、こういう対策、指定管理者の業務のお願いというのでしょうか、そういうことが必要だと思うのですけれども、いかがでしょうか。","respondent":"川原高齢者地域支援課長","answer":"生活安全担当課長等々、いろいろチラシの配布物などの連携を取っておりまして、いただいたものは例えば高齢者住宅の掲示板に貼ったりとか、あと住宅担当のほうにも職員を含めて、指定管理者にも啓蒙を行っていただく、また、その他、高齢者クラブなどでもチラシを配ったりなど。","voiceIndex":131,"id":"exchange-040"},{"speaker":"こんの委員","kind":"質問","question":"今スマホを持っていらっしゃる方がほとんどで、自動通話録音機というのは固定電話対応なのでどうかというふうに思うのですけれども、自動通話録音機としなくても、何かそうしたものの対応、それぞれ個別のお部屋にいらっしゃるわけですので、そうしたものの対応ということも必要なのかなと思うところですけれども、今どんなことがされているのか、どんな感じでしょうか。","respondent":"松山障害者支援課長","answer":"ただし、スマートフォンを持っていても、例えば発達障害の方は、外で災害時、地震が起こったときにどう対応していいか分からないということがございましたので、やはり、そういった場合の訓練として、ここに電話するのだとか、今いる場所は。","voiceIndex":133,"id":"exchange-041"},{"speaker":"こんの委員","kind":"質問・要望","question":"分かりました。ぜひ、引き続きというか、どのような対応をされているのかを、お互いに情報を共有し合ってやっていただきたいと思います。救急通報システムというシステムを、見守りというのはつけていらっしゃると思うのですけれども、各お部屋の、救急通報システム、ご利用されている、こうしたことも必要かなというふうに思いますが、こうしたものの指定管理者のほうの対応というのはあるのでしょうか。","respondent":"川原高齢者地域支援課長","answer":"ご指摘いただきました地域通報システムは各住戸に設置している、わかくさ荘には設置をしています。","voiceIndex":135,"id":"exchange-042"},{"speaker":"こんの委員","kind":"質問","question":"主に防犯、防災、そしてひとり暮らしの方の見守りという角度で質問させていただきましたが、ほかのモニタリングの内容は、ほかの委員が質問していたところでありますけれども、毎年行われるこのモニタリングの項目というのを、やはり視点をいろいろなところで変えて、事業者が出す事業計画に基づいて、ご自分たちで自己評価をしたものという説明はありましたけれども、こちらの視点もきちんと持ち合わせて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":137,"id":"exchange-043"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それで、口から食べ物が食べられるというのは、もう人生が全然こう、経管栄養とは全く違う人生に、何て言うのですか、人生の集大成のときに、その人らしい生き方がそのまま継続できるみたいな、そういうところになっていくことにもつながるので、ぜひ私はこの教訓を全体に広げるという形で取り組んでいただけないかなというふうに思ったのですけれども、そういうものというのは。","respondent":"菅野高齢者福祉課長","answer":"施設の連絡会だとかそういったところで、好事例等を紹介していけたらと考えています。ご指摘ありがとうあります。","voiceIndex":139,"id":"exchange-044"},{"speaker":"鈴木委員","kind":"質問・要望","question":"最後にもう一つ、単純なことなのですけれども、高齢者住宅のところのモニタリングのところに、何戸なのかという、具体的に、例えば八潮わかくさ荘は４０戸とか、そういう戸数が記されていなかったかなと思うのですけれども、そこのところはちょっと具体的に書いていただけたらなと思ったのが１つと、それから先ほどもありましたけれども、ゆうゆうプラザのところでは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":141,"id":"exchange-045"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"今、鈴木委員の話に補足でお話というか、要望します。大体時給１,５００円で働くような方を派遣する場合、ほぼ同額、要は３,０００円。〔「要望か」と呼ぶ者あり〕要望です。しかし、介護業界とかは利益が上がっていないというような状況がありますので、ぜひその点を、鈴木委員のご要望と同じですけれども、対策等を考えていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":143,"id":"exchange-046"},{"speaker":"こしば副委員長","kind":"質問","question":"高齢者福祉課の所管のところで、認知症例についてちょっとお聞きしたいのですけれども、総じて利用率が低めなところもあれば、６割ぐらいのところもありまして、その低めなところを見てみますと、地域のニーズと、要求ですね、サービスにミスマッチがあったとか、そういった例が出ておりまして、最初の、大井在宅サービスセンターのところだとそういった原因が提示されているのですけれども。","respondent":"菅野高齢者福祉課長","answer":"そこだと、そこに至る前の予防、まだ在宅にいらっしゃる方に力を入れたいというところで、在宅サービスセンターのほうからはそういう提案がありましたので、その辺りのところは今後も協議しつつ。","voiceIndex":145,"id":"exchange-047"},{"speaker":"こしば副委員長","kind":"質問・要望","question":"今、回答いただいたとおり新しく予防のプログラムを導入していただいた施設、指定管理業者も当然ありますので、ぜひ今回のこのモニタリング評価の結果を各指定管理者で共有をしていただき、ぜひ区のほうからも適宜アドバイス等をしていただきたい、要望も含めてお願いをしたいのですけれども、何かご意見がありましたらお願いします。","respondent":"菅野高齢者福祉課長","answer":"引き続き認知症デイサービスの利用率に限らず、事業者とは顔の見える関係といいますか、常に連携を取りつつ、いいものをサービス提供していけるように区としても支援していきたいと思います。","voiceIndex":147,"id":"exchange-048"}]},{"id":"topic-03","title":"品川区立心身障害者福祉会館、品川区立発達障害者支援施設、品川区立上大崎つばさの家指定管理者候補者の選定","agenda":"品川区立心身障害者福祉会館、品川区立発達障害者支援施設、品川区立上大崎つばさの家指定管理者候補者の選定","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"昨日、議案となった大起エンゼルヘルプの東大井の多機能ホームと、５年前のときは多分ここのところが同じ指定管理者であるというので出されたと思うのですけれども、大起エンゼルヘルプのほうは、１５年たって公募というふうな形になったので、同じ時期ではないところで出てきたということなのですかね。","respondent":"松山障害者支援課長","answer":"指定管理期間のお尋ねです。1)の心身障害者福祉会館は、５年間を経過しております。１期を経過しております。2)、3)の社会福祉法人げんきにつきましては、２期を経過しておりまして、１０年間経過しているものです。","voiceIndex":154,"id":"exchange-049"},{"speaker":"鈴木委員","kind":"意見","question":"分かりました。ということは、今回は公募しないけれども、上大崎つばさの家と発達障害者の支援施設のほうは、５年たったこの次には、１５年たつので公募すると、そういうことで進めるということで、スケジュール的にはいいということですね。分かりました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":156,"id":"exchange-050"}]},{"id":"topic-04","title":"令和６年度分品川区立高齢者住宅（単身用）補欠登録者の募集","agenda":"令和６年度分品川区立高齢者住宅（単身用）補欠登録者の募集","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"毎年、こういう形で募集されているものですけれども、昨年の応募者というのは何人いたのかを伺いたいと思います。募集内容で６０人程度ということでありますけれども、応募された方は全員というか、ここに当たっていれば全員ということで、それがおおよそ６０人くらいになるだろうと、そういうことでの６０人程度ということで捉えていいのかということの確認をさせていただきたいと思います。","respondent":"川原高齢者地域支援課長","answer":"３点ご質問をいただきました。１点目、おおよその募集人数に関しては、先ほど申し上げた人数です。全ての方を、募集の受入れをさせていただいているところです。そして、令和４年度の募集、申請者数と入居数ということでよろしいでしょうか。","voiceIndex":161,"id":"exchange-051"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これは１年間に１回しか募集がないので、途中で立ち退きになった方とかは申し込むのができないという仕組みなので、ちょっと私は、１年間に２回ぐらい申込みの期間を作っていただきたいということで、これは毎回言っているのですけれども、取りあえずその要望は改めてさせていただきたいと思います。それから、まだまだ高齢者住宅があるのだよということを知らない方もたくさんいるのですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":165,"id":"exchange-052"},{"speaker":"筒井委員","kind":"確認","question":"確認なのですけれども、この申請資格の(5)の意味は、この住宅を申請される方が、ご自身で契約した賃貸住宅に今住んでいるという意味でよろしいのでしょうか。","respondent":"川原高齢者地域支援課長","answer":"はい、委員のおっしゃるとおりです。賃貸契約書等で確認しています。","voiceIndex":167,"id":"exchange-053"},{"speaker":"こんの委員","kind":"確認","question":"１つは、申請の流れのところで、申込みをされて、実態調査・審査というところがありますけれども、この実態調査について少し確認なのですけれども、立ち退きというところは大家からの立ち退きがいつ頃かというのは書面でいただくので、ここは把握をしやすいというか、確認をしやすいというところなのですが、いわゆる、住まいが劣悪な環境にあるというところの確認は。","respondent":"川原高齢者地域支援課長","answer":"劣悪の方への確認の仕方のご質問です。こちらは訪問調査という形で、令和４年度から全件調査をしています。区の職員と委託をしている宅地建物取引士の事務所のほうと同行して、確認を複数で行わせていただいている形です。","voiceIndex":170,"id":"exchange-054"},{"speaker":"こんの委員","kind":"確認","question":"そのような体制で訪問をしてくださってということですが、ということは、いわゆる外観もさることながら、お部屋の中の状況も見てくださっているという理解でいいのでしょうか。そういう体制をとられる以前に、外観だけ見られて、中は見られないというような調査の仕方が行われていたと認識しております。お願いします。","respondent":"川原高齢者地域支援課長","answer":"委員ご指摘のとおりです。日時の調整をして、アポイントも取らせていただいて、お部屋の中も全て確認させていただいているところです。","voiceIndex":172,"id":"exchange-055"},{"speaker":"こんの委員","kind":"質問","question":"どこから発生しているか分からない、この臭いの原因というのでしょうか、そういうので住めないと。そういう臭いというか、生活衛生上というのですか、劣悪というのは老朽化とかそういうのは見た目で分かるのですけれども、いわゆる生活衛生上といったところも、保全の、そうしたものに値するのか、その辺は調査ではどうされるのですか。","respondent":"川原高齢者地域支援課長","answer":"実際に複数名で実態調査をする際に、全ての今の状況を聞き取り、目で見るような形になっておりますので、臭いというご報告をいただいた際には、そこの部分も確認するような形で、きちんと調査表のところに印をするような形にしております。","voiceIndex":174,"id":"exchange-056"},{"speaker":"こんの委員","kind":"質問","question":"借り上げのほうの住宅のところをちょっとお聞きしたいのですけれども、オーナーとの連携というところで、オーナーはオーナーですから、居住者の方々のいろいろなご相談、あるいは生活状況などに対応しなければいけないというところがありますけれども、おひとり暮らしの高齢者の方で、夜間、緊急、そうしたときには、救急車なのか警察なのか、そうした対応が１番目だというふうに思うのですけれども。","respondent":"川原高齢者地域支援課長","answer":"庁舎の開庁時間帯に関しては、大家のほうでちょっと対応し切れないような内容であれば、職員が現場に同行して確認することもあるのですけれども、基本的には、緊急通報の誤作動が結構多くて、それは幸いよかったりするのですけれども、まれに人が倒れていらっしゃって。","voiceIndex":176,"id":"exchange-057"},{"speaker":"こんの委員","kind":"質問","question":"区の高齢者住宅のほうはというか、所管の係の方々、職員の方々、本当に住居の方々のサポートをよくしてくださっているのは、私も何件かご相談をつなげさせていただいたときに、事細かにやってくださっている対応はよく存じておりますので、引き続き大家との対応も、ぜひその点をお願いしたいと思いますが、いかがでしょうか。","respondent":"川原高齢者地域支援課長","answer":"ここ何年かコロナでできていなかったのは、大家との対面での懇談会というのを今年度久しぶりに実施することができまして、そういったところで、それぞれの家同士のいろいろな事例の共有であるとか、情報を共有し合いながら。","voiceIndex":178,"id":"exchange-058"}]},{"id":"topic-05","title":"生活保護法による保護の基準の一部の改正","agenda":"生活保護法による保護の基準の一部の改正","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"ちょっとよく分からないのですけれども、１つ目の黒丸というのは、世帯人員１人当たり月額１,０００円を加算するということになっているのに、実際になんか加算されていないというか、ここにプラスで加算されるということなのですかね。令和５～６年度基準というのがありますよね。令和５～６年度基準、ここにプラスで１,０００円加算されるということなのか、ちょっと教えてください。","respondent":"豊嶋生活福祉課長","answer":"説明が足らず、大変申し訳ありませんでした。一番右側の表の令和５～６年度基準というものは、全て加算した後の金額となります。","voiceIndex":185,"id":"exchange-059"},{"speaker":"鈴木委員","kind":"質問","question":"そうすると、何か１人当たり１,０００円を加算すると言っているのに、実際は、例えば高齢者の単身世帯６５歳の方も、７万６,８８０円から７万４,２５０円で、単身の若年の５０代の方も、７万７,０００円から７万４,０００円にということで、改正後基準そのものが、１,０００円加算するどころか、もう何千円も減っているというのは、何でこういうふうに減っているのですかねと思って。","respondent":"豊嶋生活福祉課長","answer":"ご説明いたします。令和４年に、先ほどの基準部会が設けられまして、そこで金額が決まりました。その令和４年の基準部会の会議の中で使われたデータが、２０１９年の全国家計構造調査というものをデータとして使ったということが国から言われております。","voiceIndex":187,"id":"exchange-060"},{"speaker":"鈴木委員","kind":"質問","question":"憲法第２５条の最低生活費の保障という、そこのところを保障することにならないのではないかと思うのですけれども、何というのですか、その算定の仕方はちょっとおかしいのではないかなと思うのですけれども、何でそういうふうに、２０１９年のということになってしまっているのか。社会が大きく変化するということを捉えていない算定だと思うのですけれども、そういうのは国で検討されなかったのですかね。","respondent":"豊嶋生活福祉課長","answer":"ただ、委員がおっしゃられているように、先ほどから申し上げているとおり、国が経過的加算と特例的加算と申しまして、それだと、さすがに今の物価高とコロナ禍の影響をのみ込むことができないであろうということから。","voiceIndex":189,"id":"exchange-061"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういうところの階層を基に計算するので、生活保護費そのものが下がってしまう。それで、令和７年以降は検討するということですので、ぜひ現場でそういう実態をつかんでいる区としても、最低生活を保障するというところで、コロナ、物価高、そういう生活そのものが反映されるような形で国にもぜひ意見を言っていただきたいと思いますけれども、いかがでしょうか。","respondent":"豊嶋生活福祉課長","answer":"ただ、委員おっしゃられているように、特にケースワーカーは、現場の様子をよく把握しておりますので、その辺りは状況を見ながら、他区の様子も見ながら適切に判断したいというふうに考えています。","voiceIndex":191,"id":"exchange-062"},{"speaker":"鈴木委員","kind":"質問・要望","question":"多分品川でも減っていると思うのですけれども、それというのは様々な要因があると思うのですけれども、コロナに対しての対策で緊急小口だったりとか、総合支援資金だったりとか、住宅、住居確保だったりとか、様々な貸付けだったりとかということも、生活保護にならないで、貸し付けでしのいでいると、そういうこともあったということも私は影響しているのではないかなと思うのですけれども、そのときに。","respondent":"豊嶋生活福祉課長","answer":"微減です。今大体４,２００世帯前後というふうに聞いております。その大半の理由が、残念ながら死亡という形で、大体私は全ての決定調書を見ていますけれども、大体７０代どころか８０代、９０代の方もかなり多く、その中には含まれているという現状があります。","voiceIndex":193,"id":"exchange-063"},{"speaker":"鈴木委員","kind":"質問","question":"社会福祉協議会とかに聞いても、全く何て言うのですかね、自分たちとは関係がないところですみたいな、そんな感じなので、私は区としても生活福祉課のほうで、そういう貸付けのところの返済で大変な状況というのは努力してつかんでいただけたらと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":195,"id":"exchange-064"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"先ほど鈴木委員もご指摘のとおりなのですけれども、あくまで要望ですけれども、今回、国の基準額が下がったというのが、生活困窮者の方たちに合わせてというか、生活保護が上回ってしまったので、生活困窮者の方に合わせて下げるというようなお話だったと思いますけれども、逆に、むしろ生活困窮者の人を引き上げるぐらいの、下に合わせるのではなくて、上に合わせるような。","respondent":"豊嶋生活福祉課長","answer":"基準額なのですが、全ての方が下がったわけではなくて、基準額が上がっている方もおります。","voiceIndex":197,"id":"exchange-065"},{"speaker":"筒井委員","kind":"確認","question":"確認なのですけれども、この改正前基準（Ａ）、改正後基準（Ｂ）、令和５～６年度基準（Ｂ）とありまして、本来ですと生活保護法第８条第１項の保護基準が改正されて、本来は改正後基準（Ｂ）になるということでよろしいのでしょうか。改正前基準が現行、改正後基準が本来この改正法に基づいたらこうなると、ただ令和５～６年度は臨時的・特例的な対応でこの額になるということでよろしいのでしょうか。","respondent":"豊嶋生活福祉課長","answer":"委員おっしゃるとおりです。","voiceIndex":201,"id":"exchange-066"},{"speaker":"筒井委員","kind":"質問","question":"そうなると、今後特例的な対応はどこまで続くかどうか分からないのですけれども、特例が終わったらこの改正後基準（Ｂ）の値段になってしまうということですよね。これからさらに、そこまで景気が急激に回復するとは思えないのですけど。それで、かつ改正後基準ですとマイナスになる人が多いと見えるのですけれども、その点については区としてどうお考えなのでしょうか。","respondent":"豊嶋生活福祉課長","answer":"令和７年度以降については、令和７年度予算の編成過程において改めて検討するというふうに、国が現時点で言っておりますので、そこについては状況を見ていきたいというふうに考えております。","voiceIndex":203,"id":"exchange-067"},{"speaker":"こんの委員","kind":"質問・要望","question":"先ほど、２０１９年のデータを基にというご説明、いわゆるそういったことが国で行われて、この基準額になったということなのですが、どんな議論が行われていたのかというようなことは、国からの何か通知の中に、そうした議論の末にこうした方向性が決まったみたいなものというのは何か来ておりますでしょうか。ありましたらご紹介ください。","respondent":"豊嶋生活福祉課長","answer":"残念ながら手元にはございません。申し訳ありません。","voiceIndex":206,"id":"exchange-068"},{"speaker":"こんの委員","kind":"確認","question":"その中で生活を頑張ってしていただくというわけなのですけれども、お金の管理というところで、関連でちょっとお聞きしたいというふうに思うのですけれども、改正の話とは違って、制度の話というか、受給者のお金の管理というところを参考にちょっと状況をお聞きしたいのですけれども、ご自分でお金の管理ができなくなってしまった人のために管理をしていただく、そうした支援員というのでしょうか。","respondent":"豊嶋生活福祉課長","answer":"大変難しい問題でございまして、やはりご同意をいただかないとお金ですので、我々のほうで、この人はこうだからということで勝手にすることはできません。","voiceIndex":208,"id":"exchange-069"},{"speaker":"こんの委員","kind":"質問・要望","question":"ケースワーカーがお一人で１００件以上の対応をされていらっしゃいますので、できる限り地域の資源、その受給者の周りにいらっしゃる、あるいは遠く離れたご家族の方とも連携が取れるような形で受給者のサポートができる態勢がとれたらなというふうに思いますので、今回のこの改正に当たっても、お話を多分、ご通知を出して理解がすぐできる方と、そうではない方と。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":210,"id":"exchange-070"}]},{"id":"topic-06","title":"０歳児見守り・子育てサポート事業『見守りおむつ定期便』の実施","agenda":"０歳児見守り・子育てサポート事業『見守りおむつ定期便』の実施","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"初めての施策になるわけですけれども、４番の事業内容のところで、「有資格者等」と書かれているのですけれども、有資格というのはどんな資格なのかということと、直接はチェックリストを基にということなのですけれども、チェックリストを基に毎月養育状況の確認をすると、そういうことになるのでしょうかということも教えていただきたいと思います。","respondent":"石橋品川保健センター所長","answer":"今回ですが、委託をさせていただき、実施をいたします。委託ですが、株式会社ＴＮＣプロジェクトというところに、品川区簡易型プロポーザル方式で、こちらのほうを選定させていただきました。","voiceIndex":215,"id":"exchange-071"},{"speaker":"鈴木委員","kind":"質問","question":"そうすると、全員が助産師、保健師、保育士、看護師ということで、これだけの資格のある人が、毎月来て、こういうおむつとかを持ってきて、そしていろいろと相談にも乗ってくれて、支援もしてくれると、そういうことを希望者全員に行うと、そういう事業になるということでしょうか。そして、そうすると何人体制ぐらいで、この事業をされるのかについても教えてください。","respondent":"石橋品川保健センター所長","answer":"ご質問になります。こちらですが、毎月有資格者の方が訪問し相談を受けるというお話でしたが、今回、この実施の報告の、厚生委員会の資料にも書かせていただいています「有資格者等」と、まずあります。","voiceIndex":217,"id":"exchange-072"},{"speaker":"鈴木委員","kind":"確認","question":"１２人を確保するということなのですけれども、ちょっと私、助産師や保健師とか、こういう有資格を１２人、こういうおむつを玄関先で５分と、そういうふうなところに確保するというのはすごく大変ではないかなというふうな思いがするのですけれども、ちょっとそこら辺の見通し、少なくともこれぐらいは有資格者を確保するとか、それとも全て子育て経験、子育て経験というのと。","respondent":"石橋品川保健センター所長","answer":"今回、一応１０月から申請等を郵送するということで、半年、今年度は実施いたしますが、予算額は１億８,０００万円を予定しております。次年度は通年での実施になりますので、３億５,５００万円を予算額として計上する予定になっております。","voiceIndex":219,"id":"exchange-073"},{"speaker":"鈴木委員","kind":"質問","question":"どういうふうに想定されて、この額というのが出てきたのか伺いたいと思います。子育て経験のある人というのだけで採ったときの研修というのは、どんな研修を何時間とか、かなりちょっと何というのですかね、プライバシーに関わる部分でもあったりもするし、また、支援が必要だと判断するということも含まれる仕事の中身になると思うので、その研修というのはどういう中身なのかもちょっと伺えたらと思います。","respondent":"石橋品川保健センター所長","answer":"研修の内容ですが、一般的に接遇研修ですとか、そういったチェックリストを基に、訪問に対するロールプレイングですとか、例えば、ご自宅まで行って見守りの商品をお渡し、保育用品をお渡しして、終わってというところまでのロールプレイングですとか。","voiceIndex":221,"id":"exchange-074"},{"speaker":"鈴木委員","kind":"意見","question":"このＴＮＣプロジェクトというところは、こういう今回委託されるような事業というのはどこかで経験されているところなのか、ちょっとＴＮＣプロジェクト、この受託するところがどういう会社なのか、その点をお聞かせください。","respondent":"石橋品川保健センター所長","answer":"福岡市と品川区のスキームは全て一緒ではないのですけれども、各対象とする世帯のご家庭を回って、一応手渡しで商品を渡すというところは、既に経験をされているというところで、スキームはしっかり提案のときもお伺いできたので評価される部分だと考えています。","voiceIndex":223,"id":"exchange-075"},{"speaker":"鈴木委員","kind":"質問・要望","question":"初めてのこういう施策ですので、いろいろなところも、こういうおむつ宅配というのはちょっとネットで見たら、明石市だけでなく、ほかのところでも始めたというのが出ていましたので、そういうのが本当に子育て支援につながるというふうなところで取組を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":225,"id":"exchange-076"},{"speaker":"ひがし委員","kind":"質問","question":"見守りおむつ定期便は、実家が福岡なものでお話を聞いていて、こういうのが始まるのだというのを聞いていたので、品川でも始まるのがうれしいなというふうに思っているのですけれども、明石市とか、ほかのところの区を見ていると、おむつ、お尻拭き以外の用品も結構置いていたりするのですが、品川もその点、おむつ、お尻拭きに限らず、ほかの用品も検討しているのでしょうか。","respondent":"石橋品川保健センター所長","answer":"今回、育児用品は５６品を用意しております。紙おむつ、布おむつ、お尻拭き、手口拭き、離乳食、粉ミルク、あとは飲料水、麦茶等ですね。０歳児のご家庭でよく使用するものを数多く取りそろえております。","voiceIndex":227,"id":"exchange-077"},{"speaker":"ひがし委員","kind":"質問・要望","question":"どの事業でも思うのですけれども、申込みの仕方が結構しにくかったりとかするので、ホームページの見やすさと申込みのしやすさというところも注視していただきたいなと思うのと、あとは、先ほどもお話が出ていましたけれども、有資格者をなるべくというところでいくと、医療業界も結構人員の確保が厳しいというお話を聞いていると、実際問題ちょっと、どのぐらい費用が充てられるか分からないのですけれども。","respondent":"石橋品川保健センター所長","answer":"今のところは０歳児までということで実施をしますが、１歳児以降ですと、いろいろ児童センターとか利用する場所がありますが、また、今回実施をしてみて、いろいろご要望等もお伺いしながら、年１回、年数回、区民の方、利用者の方にアンケートを実施して。","voiceIndex":229,"id":"exchange-078"},{"speaker":"筒井委員","kind":"質問・要望","question":"それで、今回の委託に当たりまして簡易プロポーザルでこの受託者を決めたかと思うのですけれども、かなりの数の申込みがあったかと思うのですけれども、今回ＴＮＣプロジェクト、ホームページも拝見しているのですけれど、テレビ西日本のグループ会社ということで、こういうこともやられているのかなと考えていますけれども、今回株式会社ＴＮＣプロジェクトが、ほかの業者と比べて何か特筆すべき点とか。","respondent":"石橋品川保健センター所長","answer":"見守りの実施報告ということで、私どもは、最終的に支援が必要なご家庭に対しては、即時性を持って区に報告していただきたいと考えております。","voiceIndex":232,"id":"exchange-079"},{"speaker":"こしば副委員長","kind":"質問","question":"この見守りおむつ定期便なのですけれども、この支援員の方が訪問と同時に必要な消耗品をお渡しするということで、１日１８０人のところにお届けするということなのですけれども、イメージで言いますと、おそらくかなりの量になると思うので、何か軽トラックとかそういったものと一緒に多分移動されるのかなというようなイメージを持っているのですが、どんな感じなのでしょうか。","respondent":"石橋品川保健センター所長","answer":"おむつ等の、なかなか物理的にちょっと大きいものを持って移動という形になりますので、やはり自動車の車種等は特に指定はしてないのですけれども、そういったツールを使っていただき、自動車を使っていただき、見守りしながら配達も兼ねていただくというところで考えております。","voiceIndex":235,"id":"exchange-080"},{"speaker":"こしば副委員長","kind":"質問","question":"一緒に届けるときに、今、ＴＮＣプロジェクトのほうに委託をされるということなのですけれども、そのプロジェクトのほうは消耗品の運搬も兼ねているものなのでしょうか。それはまた別に、品川区のほうで準備をされるということなのですか、そういう運搬は。","respondent":"石橋品川保健センター所長","answer":"今回の委託の中に、運搬も全て兼ねてということで委託をしています。","voiceIndex":237,"id":"exchange-081"},{"speaker":"やなぎさわ委員","kind":"提案","question":"今のこしば副委員長の宅配というか、届けるというお話は、すごく興味深いのですけれども、実際、現時点で、ＴＮＣプロジェクトから、どういう方法で、例えば車の車種がどうだとか、そういったような提案というのは、今のところはないのでしょうか。","respondent":"石橋品川保健センター所長","answer":"車を使って配達をするということは伺っているのですけれども、特にちょっと車種まではお伺いしてない状況になります。","voiceIndex":240,"id":"exchange-082"},{"speaker":"やなぎさわ委員","kind":"質問","question":"イメージとしては、ドライバーがいて、有資格者等の方がいて、２人で回るというようなイメージでしょうか。","respondent":"石橋品川保健センター所長","answer":"その辺りに至りましても、今回、委託の仕様内容には特に、こちらのほうから何人で回るということは指定をしていないため、一応総数、毎月３,４００件を対象としているのですけれども、１か月に１度必ず回れるという形で依頼をしますということでお願いしているので。","voiceIndex":242,"id":"exchange-083"},{"speaker":"やなぎさわ委員","kind":"意見","question":"先ほどちょっとお話があった１２人職員が基本いて、１日１２人で１８０件回るということは、１人当たり１５件１日で回るということで、結構これというのは厳しいかなというような、訪問先でも５分ぐらい話すというお話なので、移動時間とか車を止める場所とかも含めて考えていたら結構ばたばたしてしまって、渡すだけ渡して、特に見守りもできなくなるような危険性があるのですけれども。","respondent":"石橋品川保健センター所長","answer":"その辺りにつきましては、今しっかり回れるように受託者と連携をして調整をしてまいっているところです。必ず訪問時間が短くならないように、しっかり対応して進めてまいります。","voiceIndex":244,"id":"exchange-084"},{"speaker":"やなぎさわ委員","kind":"質問","question":"先ほどほかの委員もご指摘がありましたけれども、有資格者等で、やはり、今のところ７０％以上が資格者だと、そういうところは特に設けないということなのですけれども、どうしても、ないとは思いますけれども、利益とかを優先したりとか、人材が集まらないと、もういいや、いいやという感じで、取りあえず応募に来た無資格者の方を入れてしまうということで、無資格比率が上がるということも考えられるので。","respondent":"石橋品川保健センター所長","answer":"そのお話をお伺いしておりまして、品川区では可能な限り有資格を配置させたいと思っているところの思いを受託者のほうにはしっかり伝えておりますので、１１月の見守り開始のこの１か月ですね、しっかりその辺りは受託者と連携をとって。","voiceIndex":246,"id":"exchange-085"},{"speaker":"やなぎさわ委員","kind":"質問","question":"はい、かしこまりました。よろしくお願いします。子育て関係をやっても、ちょっと何か独自の思想をやられている方とかもいらっしゃるかもしれません。すみません。そもそもなのですけれども、例えば、今回委託ということですけれども、今後でも何でもいいですけれども、区の事業、区の管轄として、区で職員を集めてやるというようなことは、特にお考えはないのでしょうか。","respondent":"石橋品川保健センター所長","answer":"本事業は最終的に支援が必要ですとか、相談事があるご家庭に関しては、区の保健師等の専門職がしっかりフォローしてまいりたいと考えております。今の時点では、区の正規職員ですとか、そういった職員を配置して見守りをするということは想定していないところになります。","voiceIndex":248,"id":"exchange-086"},{"speaker":"おぎの委員","kind":"質問","question":"初めての事業ですので、どういった形なのかなと思っておりましたが、ちょっと今お話を聞いていまして、こちらの文章にあります「孤独感や不安感を払拭して、何かあったときに、区の保健師などにつなげる」ということを趣旨に置くのであれば、有資格者にこだわる必要はないのかなという気もしますし、５分間で赤ちゃんを見て、健康状態をチェックしたり、子育ての。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":252,"id":"exchange-087"},{"speaker":"こんの委員","kind":"質問・要望","question":"今までの質疑で、スキームや体制は分かりました。ぜひ頑張っていただきたいというふうに思います。それで、すくすく赤ちゃん訪問事業、これは４か月までの事業ですけれども、こちらはこちらで訪問して対応されている、そこでもリスクヘッジをしている。非常に厚くリスクヘッジをしていく態勢は非常にありがたいなと思うのですけれども、この関係性というか、連携とか、そこら辺は何かされるお考えですか。","respondent":"石橋品川保健センター所長","answer":"確かに４か月、早いうちから申請された方に至りましては４か月目、２回訪問という形になってしまうかもしれないのですけれども、すくすく赤ちゃん訪問でまた支援が必要でしたり、その前から、例えば見守り訪問で１か月から訪問させていただいて支援が必要ということで。","voiceIndex":254,"id":"exchange-088"},{"speaker":"こんの委員","kind":"質問","question":"その辺が、お互いに情報を持ったものが共有されていくほうが、より一層その支援につながるかなというふうに思うのでぜひお願いします。すくすく赤ちゃん訪問事業のほうでもそうなのですが、ご案内しても、それに応じない。訪問はいいです。こういうご家庭も間々あります。そこへのアプローチはどんなふうに考えていらっしゃるのでしょうか。","respondent":"石橋品川保健センター所長","answer":"最終的に勧奨しても全く音沙汰がない方ですとか、勧奨したけれども、訪問に来てほしくない理由、そういったところは、品川保健センターや荏原保健センター、大井保健センター等の保健師のほうで内容等を確認し、あと、すくすく赤ちゃん訪問ですとか。","voiceIndex":256,"id":"exchange-089"},{"speaker":"こんの委員","kind":"質問・要望","question":"そのためにも今回のこれは、月に１回行っていただく、お元気ですかとお声をかけていただくこの事業は、大変に大事だというふうに思います。これは申し込んだときに、土日をご希望といった場合も対応するのでしょうか。夜間を希望と言った場合も、いわゆる訪問していただきたい日時、そうしたことは平日昼間だけなのか、それとも土日、夜なども聞いていただけるのか、その辺のところを教えてください。","respondent":"石橋品川保健センター所長","answer":"ただ、本事業はまだ始まっていない事業になりますので、先ほどもお話ししました年数回アンケートを実施させていただき、そういったニーズが高かったりしたときには、また今後この事業をどう展開させていくかというのは考えていく必要があると思っていますので、そのときに。","voiceIndex":258,"id":"exchange-090"},{"speaker":"こんの委員","kind":"質問・要望","question":"まだ始まっていない事業なので、どの程度のニーズかというのが分からないかと思いますけれども、ぜひそのアンケート等でニーズがあるようでしたらば、訪問の日時等も、そうした拡充というところも考えていっていただければなと思いますので、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":260,"id":"exchange-091"}]},{"id":"topic-07","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"こんの委員","kind":"質問","question":"すみません。コロナの前の話をして恐縮なのですが、コロナの前の視察のときには、この勉強会では、部長などからご説明という場面があったと記憶しているのですけれども、今日は部長からのこの視察の内容は、今委員長が説明したので全部ということですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":276,"id":"exchange-092"},{"speaker":"こんの委員","kind":"意見","question":"部長がお話ししないで、委員長が全部話してしまっていると私は思ったので、皆さんは知らないことで、私はその前から経験があったので、ちょっと、あれ、変わったのかなと思ったのです。すみません。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":280,"id":"exchange-093"},{"speaker":"こんの委員","kind":"確認","question":"すみません、段取りは委員長のほうでということでした。それはそれなので。確認です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":283,"id":"exchange-094"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3672#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":83366,"voices":286}},{"id":"r05-20230926-8","meetingId":"r05-cm09","date":"2023年9月26日","dateIso":"2023-09-26","committee":"建設委員会","time":"午前１０時００分～午後 ２時２１分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を62件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、第４回の協議会が行われたということで、その中での議論はどんな意見が出たのかを伺いたいのと、今回、示された資料で３つの章の説明をしていただきましたけれども、それ以外の点については、変更とかはないということなのですか。ネットワーク路線とかのところは変更ないのかどうかを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"初めに、第４回でいただいたご意見ですが、今回、自転車ネットワーク路線をお示しし、学校の前あるいは学校の近傍で整備された場合、ぜひ学校、特に中学生に自転車通行のルールなどの交通安全教育の実施も併せて実施していただきたいという意見、あるいは鉄道事業者の方からは。","voiceIndex":5,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"ネットワークも変わっていると思ってお聞きしたので、やはりそうなのですね。今回、新たに示された施策の中で、新規のところや検討のところなどが新たに出てきておりますけれども、その中で当日利用の短時間無料設定の導入を検討されるのはよかったと思いますので、ぜひ実施をしていただきたいと、これは要望しておきたいと思います。","respondent":"鈴木都市計画課長","answer":"商店街での駐輪場の対策、整備ですが、やはりまとまった用地を確保して駐輪施設を設けるのはなかなか難しいというところは商店街からのヒアリング等でも判明しているところでございまして、そうした中で、例えばですが、武蔵小山商店街などでは。","voiceIndex":7,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"それで、ちょっと基本的なことにもなってしまうのですが、今回、計画の推進のところで、自転車通行空間の整備延長が目標に入りましたけれども、令和４年度、現状が１９.４kmということで、目標値が５７.７kmとなっているのですが、これは今回示されたネットワークの全長が何kmかが分からないのですけれども、全部整備するということなのか、それとも何割ということなのか、そこを伺いたいと思います。","respondent":"鈴木都市計画課長、森道路課長","answer":"お示ししている目標の数字については、区道部分のネットワークの総延長ということでお示ししている数字です。今の整備に加えて今回ネットワークとして設定されたところについては、これから具体的な実施計画といいましょうか、どこの路線からやっていくか、あるいは年間どのぐらいを進めていくべきかというようなところを計画期間の中で。","voiceIndex":9,"id":"exchange-003"},{"speaker":"のだて委員","kind":"質問","question":"具体的にはこれからということで、そうすると今、出されている新たなネットワークの整備するところの延長もまだ具体的には分かっていないということなのかもしれないですが、この目標値が全体の整備に対してのどのぐらいになるのかを知りたいのですが、いかがでしょうか。","respondent":"森道路課長、鈴木都市計画課長","answer":"今のところから５７.７kmの差分をしっかりと整備をしていく中で、年間どのぐらいを進めていくか、あるいはどこから進めていくかをいろいろな交通の鉄道をつなげるだとか。今、道路課長がご説明した８８ページ、ネットワーク全体とすると、区道、都道、国道全体を含んでネットワークと。この８８ページにはまだそのうちの区道部分しかお示ししていないと。","voiceIndex":12,"id":"exchange-004"},{"speaker":"渡辺委員","kind":"質問","question":"１点、ご説明と資料を拝見しながら、とても要点がまとまっていることと、どれも本当に必要性の高いものが整理されたのだと、今、説明を伺って思いました。それはもう大前提だと思うのです。そのときにこれだけきれいにまとまって、分かりやすくしたのだけれども、情報量もとても多いから、これがどう伝わるのかと思ったのです。広報の必要性、重点化。この辺で考え方をお知らせください。","respondent":"鈴木都市計画課長","answer":"場合によってはイベント、あるいは公園に遊びにきたお子さんへのお声がけをしながらの交通安全の周知ですとか、様々な機会、様々な手法を活用しながら、ホームページもこれまで自転車、交通安全は非常に重点的に区民周知をさせていただいたのですが。","voiceIndex":16,"id":"exchange-005"},{"speaker":"渡辺委員","kind":"質問","question":"今、民間の企業だとかもやはり広報のところは改めて力を入れ直している。この案件はやはり全区民、各世代共通で、すごく力を入れることが理解をされるのではないかと。恐らく議会もそうだと思うので、手法はまだこれからだと思いますが、ぜひここは重点に広報力の展開を期待して、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"でも申請が非常にやりづらいと言っておりましたし、申請をしても二、三か月かかってしまうということがあったので、そういうのもちょっと改善をしてほしい。ここには表現できないと思うのですけれども、より簡便性のある形でお願いしたいと思います。それから商店街とのコラボレーションの中で、商店街、店舗に来られる方の自転車排除という考え方はやめてほしいのです。お考えをお願いします。","respondent":"工藤交通安全担当課長","answer":"２点目、商店街の自転車の排除の考え方はやめましょうというところのお話なのですけども、これは商店街を所管する課と連携をとりまして、また引き続きどういった形がより適切なのかを検討してまいりたいと思います。","voiceIndex":20,"id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"もう自転車で来るなですから。１点が整備優先度の地図があるのですけれども、ちょっと小さいので、これは大きいのをいただけないですか。キックボードはまた違うので、ここに入らないかもしれないのですけど、ただ、いずれにしても、何かしらの改正のときには、電動キックボードも入れないといけないのかと思いますので、それを念頭に入れてつくっていただきたいと思いますが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"特にはやはり安全に乗っていただくのがまず一番かなですので、その表現をさらに強化して載せるのか、施策のほうで載せていくのかは少し検討させていただいて、先ほどの１０年の期間の中の５年目の見直しの中で、さらに充実した見直しをその辺も含めて図っていきたいです。","voiceIndex":22,"id":"exchange-008"},{"speaker":"西本委員","kind":"質問","question":"たくさんの質問にお答えいただきまして、ありがとうございました。電動キックボードはやはり５年目の改定に向けて、いろいろ変わると思うのです。なので少し意識をしていただければありがたいと思っています。そして、学校のイベントについて、分かるのです、駐輪場の件は。あまりにやり方がひど過ぎるので、あまり気持ちいいものではないので、お願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"基本は自転車活用推進計画ということでありますので、自転車を利用する方が主体となっての計画で、例えば交通安全の視点からいうと、車を運転する方の視点から見て、自転車走行に対しての危険性を感じるような場面もあるわけですが、この推進計画はあくまでも車を運転している方が、自転車走行に対しての何か呼びかけるということではなくて、自転車そのものを運転されている方自身に対する活用なり。","respondent":"鈴木都市計画課長","answer":"そのレーンを車側が踏んで走行してもいいのかとか、そうしたところは一定、やはり車を運転する方への周知も必要だというところもありますので、そこは内容に応じて歩行者あるいは車を運転する方への啓発周知も行っていきたいです。","voiceIndex":26,"id":"exchange-010"},{"speaker":"田中委員","kind":"質問・要望","question":"なので、子育て送迎ルートをつくることの目的というか趣旨が、やはり私は親に対して安全対策をもっと強く求めるとするならば、逆にこういうルートをつくってしまうと、ここはもう子どもを乗せている自転車が主体となって通ってもいいルートだと公が認めてしまうことにつながると、かえって安全対策上、課題が出てしまうのではないかという思いがあるのですが、その辺の考え方はいかがでしょうか。","respondent":"鈴木都市計画課長","answer":"今後も増えていくというところで、そうしたできるだけお子さんをお連れになった自転車を利用する方が、このルートについては安全・安心に乗っていただくというところで、何かこう取組が進められないかということでここでは提案させていただいているところなのですが。","voiceIndex":28,"id":"exchange-011"},{"speaker":"田中委員","kind":"意見","question":"商店街についての、個々の商店街とのやり取りというか特性がありますので、例えばここに武蔵小山と中延の事例がありますけれども、これが一つの事例として、それぞれの個別事情もありますので、例えばシャッターが閉まっている、営業してないところを先ほどの話ではそこも駐輪スペースとして活かしたらどうかというのもありますが、逆で、シャッターは閉まっているけれども、搬入だとかいろいろな観点でとか。","respondent":"鈴木都市計画課長","answer":"商店街のところは、まさに施策の地域特性を踏まえたというところで、商店街の取組について書かせていただいてありますので、委員のご指摘のとおり、商店街も商店街という言葉のひとくくりではない、それぞれの商店街が抱える状況ですとか、利用実態ですとか。","voiceIndex":30,"id":"exchange-012"},{"speaker":"若林委員","kind":"確認","question":"計画の策定、素案の段階ですけれども、お疲れさまです。というところを気づいたり、スピードが出ているなとか、歩道上、ちょっと危険な走行なのかというのが見受けられた場合は、あくまでも自転車安全利用指導員なので、キックボードはそういう意味ではちょっと縦割りではないですが、声をかけないとか、そこら辺はキックボードを見る目というのはどんなものなのでしょうか。","respondent":"工藤交通安全担当課長、鈴木都市計画課長","answer":"基本的には、自転車のルール、マナーを周知しましょうというところで配置しているのですが、当然、交差点等を通る方は、自転車だけではなくて歩行者等もありますので。この見直しの中では、ＰＤＣＡというお話もございましたが、具体的にはＰＤＣＡという言葉は書かせていただいておりませんが、区で毎年行う事務事業の評価の中でも、当然、評価、見直しを行ってまいりますし、この推進体制、区民。","voiceIndex":33,"id":"exchange-013"},{"speaker":"若林委員","kind":"質問・要望","question":"そうするとキックボードについても、マスコミ報道でも、歩道を２０km／ｈ出して人を死傷してということも大きく早速、取り上げられるようになって、先ほどの続きになりますけれども、キックボードの書きぶりは、指導員も含めてもう少ししっかりこれはルールを自転車同様、区としてはという姿勢を、またその根拠となるような書きぶりを私はもうちょっとしたほうがいいと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-014"},{"speaker":"のだて委員","kind":"質問・要望","question":"ルールというか、事故がないようにしていただきたいと、要望しておきたいと思います。ほかの旧東海道も入ったということで、商店街だと、やはり当然、歩行者もたくさんいらっしゃるということで、安全配慮はしていくということですけれども、戸越銀座では自転車に乗って通行してほしくないというような話も聞いたことがありますので、そこは商店街としっかり連携をしてやっていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-015"},{"speaker":"のだて委員","kind":"質問・要望","question":"これはこの間、ずっと求めてきているところですけれども、もう少し具体的なところも書いていただけると、この事業の内容がより詳しく分かると思いますので、よろしくお願いします。区で行っていると思いますが、伺いたいと思います。それと、事業収支の概要というところで、人件費というのが環境学習交流施設のところでしか出てこないのですけれども、ほかのところではどうなっているのか伺いたいと思います。","respondent":"竹田住宅課長、工藤交通安全担当課長","answer":"それから労務関係ですが、住宅につきましては、５年に一度、指定管理者を選定しております。その際に詳しく聞き取りをしておりますが、５年の間にも、適宜行っていきたいと考えております。収支の概要につきましても、同様です。指定管理の人件費の記載がない部分ですけれども、人件費については支出の一般管理費の中に含まれておりまして、約１億８００万円ということで、支出全体のおおむね４６％に当たるです。","voiceIndex":45,"id":"exchange-016"},{"speaker":"のだて委員","kind":"質問","question":"それぞれの指定管理者について伺ったのですけれども、それぞれご答弁いただけたらと思います。","respondent":"工藤交通安全担当課長、河内環境課長","answer":"労務関係ですが、こちらのほうも５年に一度の契約でございまして、その際にチェックをしています。都度、担当と指定管理者とやり取りをしておりまして、チェックはしています。労務管理につきましては、同じく５年でございまして、毎年きちんと精査している状況です。定例会議の中で、こういった流れについては確認を行いながら、進捗管理をしています。","voiceIndex":48,"id":"exchange-017"},{"speaker":"のだて委員","kind":"質問","question":"人件費のことについても伺ったので、後でお答えいただけたらと思うのですけれども、適宜、労務関係についてはチェックをしているということなのですが、そのチェックの内容が分からなかったのですけれども、どのように見ていらっしゃるのか、適宜やっているというのはどういった形でやられているのかを伺いたいと思います。","respondent":"竹田住宅課長、河内環境課長、工藤交通安全担当課長","answer":"それから労務関係の確認方法ですが、５年に一度の契約のときは詳しく、それから５年の間に、中間点で人件費等を確認しています。そういったところもありまして、人件費とのトータルの中で労務管理を行っているです。労務管理の関係ですが、こちらは都民と接する非常に重要な役割を担っておりますので、接遇対応、態度等に関しまして、日々。","voiceIndex":51,"id":"exchange-018"},{"speaker":"のだて委員","kind":"質問・要望","question":"住宅のところで伺いたいと思いますが、宅建管理センターのほうで、滞納者１件当たりの対応回数が、令和４年度は３.３９回ということですが、これとあっ旋から入居までの平均日数、８５日ということで、これは区営住宅ではどうなのか、区民住宅ではどうなのかというところを伺いたいと思います。ある意味、仕方がないところがあると思うのですけれども、区の考えを伺いたいと思います。","respondent":"竹田住宅課長","answer":"宅建管理センター分からです。滞納者１件当たりの対応の回数ということで、令和３年度と令和４年度を比較しますと増えていると見えるところですが、どちらかだけということだけではないのですが、どちらが多いかといいますと、区営住宅のほうが若干多いかと考えております。","voiceIndex":55,"id":"exchange-019"},{"speaker":"のだて委員","kind":"質問","question":"それと、人員配置の中で、少し繁忙期のところで課題が見られたということなのですが、そういった事態になってしまったのはなぜなのかというか、予算でいくと収支がプラスになっているので、予算的な問題ではなかったのかどうかというところを伺いたいと思います。社会科見学にも多くの区立学校が来ているということなのですが、何校来たのか伺いたいと思います。","respondent":"河内環境課長、竹田住宅課長","answer":"それはそれでいいことだと思うのですが、今後、そういったものがまた成果を残せますように、しっかりと対応していきたいということで、職員の増で対応するというところで進めているところです。区営住宅のほうは滞納者の対応回数が多いのではないかということですが、使用料だけに限らず、区営住宅のほうは、入居されますと２０年、３０年と長く入居されている方が多くいらっしゃいますので。","voiceIndex":57,"id":"exchange-020"},{"speaker":"のだて委員","kind":"質問・要望","question":"住宅のところでは、定期点検ではなくて、高齢者とか、入居者への巡回の頻度を伺っておりますので、そこをお答えいただければと思います。それと、環境学習交流施設のところでは、人員配置と予算の関係で伺ったのですけれども、予算的な問題ではなくて、予想以上の来館者が来たからということでいいのか、確認です。","respondent":"竹田住宅課長、河内環境課長","answer":"大変失礼しました。入居者への巡回ですけれども、先ほど申し上げたとおり、入居者が大分高齢化しておりますので、その方のご事情に合わせまして、月１回でいい方、あるいは毎週等、ご事情に合わせて巡回しております。ご質問の件ですが、要因といたしましては、予想を上回るご利用者がいらっしゃったことに伴う結果ということで分析しています。","voiceIndex":60,"id":"exchange-021"},{"speaker":"西本委員","kind":"質問・要望","question":"１点目が宅建管理センターのほうですけれども、２ページ目にサービス向上というところで、本人の了解を得てという単身高齢者世帯の緊急連絡先ということをやっているのですが、これはとても必要なことだと思うのですけれども、了解を得なくても、緊急時の対応についての連絡先はしっかりされているということでよろしいのでしょうか。それともそれは別にしているのですか。","respondent":"竹田住宅課長","answer":"もし不必要ならば権利放棄していただけますかというようなことを確認して対応しているのが現状です。区民住宅につきましても、ご本人様了解の上、極力、緊急連絡先をお聞きするようにしております。それから収支の記載のほうですが、分かりにくくて大変申し訳ございません。","voiceIndex":64,"id":"exchange-022"},{"speaker":"西本委員","kind":"質問","question":"緊急連絡先というのはそれでいいのですか。身寄りがないという方はしようがないかもしれないのですけれども、そういう形で戸籍を取ったりとかしてやっていくということになるのでしょうが、でもそうではなくて、普通に住宅を借りるときというのは保証人であったりとか、緊急連絡先とかを必ず書くのではないのですか。だから、なぜ本人の了解になってしまうのでしょうか。そこを教えてください。","respondent":"竹田住宅課長","answer":"ただ大きな金額が不測の事態として必要になるという場合も、昨今はありませんけれども、可能性としてはありますので、そういった点は契約の中で、その他の事項については協議するという文言がありますので、指定管理者と十分協議しながら、補填等のやり方については。","voiceIndex":66,"id":"exchange-023"},{"speaker":"西本委員","kind":"質問・要望","question":"だけれども、基本的には緊急連絡先は登録することとしておかないと、それでいいとなってしまうではないですか。なので、細かい話、やはりどういうものに使われているのかということは、はっきりと提示できるような資料のつくり方は今後、検討していただきたいと考えていますので、これは全体の話になるので、ここだけの話ではないと思いますので、意見として申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-024"},{"speaker":"田中委員","kind":"質問・要望","question":"時間も大分迫っているので、まとめてお伺いをいたします。だからこういう表現だと、宅建管理センターに対しての責任といいますか、対応を求め過ぎているような気がしてしまうので、その辺のお考えをお聞かせいただきたいと思います。","respondent":"竹田住宅課長、河内環境課長、工藤交通安全担当課長","answer":"それから訪問回数の件ですが、先ほど申し上げましたとおり、区営住宅は高齢者の方が多くいらっしゃいますので。そのバランス感覚がやはり大事になってまいりますので、そういったところの努力も含めまして、縮減に対して一定の努力、成果があったと認識しています。ラックの交換についてですが、こちらは委員、ご説明のとおり、区民の声を受けまして交換しています。間隔の狭いところで３０cmのラックがあります。","voiceIndex":70,"id":"exchange-025"},{"speaker":"田中委員","kind":"質問","question":"住宅管理に関しましては、それぞれの指定管理者の方の努力によってというところと、また住む方の年齢層等々の対応だということでよく分かりました。それとエコルに関しましては、極めてアクティオの努力も相当ある。こういう方を指定管理として決定をされた区の目利きというのでしょうか、いい方を選んでいただいた。引き続き、その成果を期待したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-026"},{"speaker":"まつざわ副委員長","kind":"質問","question":"ほかにいかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-027"},{"speaker":"のだて委員","kind":"質問","question":"この間の取組については、若干ご説明があったのですけれども、いろいろやってきた中での新規を含めて、どんな話合いが行われてきたのかというところを伺いたいと思います。それで、この地域で今、防災上の様々な課題があるということで、その課題というのは何があるのか、伺います。この申請については、どういったチェックをされたのか、伺いたいと思います。","respondent":"小川木密整備推進課長","answer":"１点目、地域とどのような話合いがあったかというご質問ですが、こちらは先ほど申しましたが、平成２６年度から事業推進業務を行ってございまして、その中で、平成２７年度より地区に入りまして、意見交換会または個別調査等を実施してきているところです。","voiceIndex":80,"id":"exchange-028"},{"speaker":"のだて委員","kind":"質問・要望","question":"審査はいろいろ理念などを含めてやられているということで、その内容と結果が選ばれたということはよかったということだと思うのですが、どういったところを評価されたのかというところを伺いたいのと、いろいろ意見交換の中では声が出ているということなので、そうした地域とも、よく話してやっていただきたいと。密に連携、意見交換をしてやっていただきたいと思います。","respondent":"小川木密整備推進課長","answer":"今、１点、法人をどう評価したかというご質問があったかと思いますが、やはりこの不燃建築公社に関しましては、品川区は今、３つの防災街区整備事業を行っておりまして、この３つの事業に全て関わっているという実績がしっかりとあるといったところが。","voiceIndex":82,"id":"exchange-029"},{"speaker":"西本委員","kind":"質問","question":"やはり少し気になるのが、平成２６年度よりいろいろされているということなのですけれども、そこで進展があまりなされていないということをお聞きしたと思うのです。なので、ここは危険な箇所だということの自覚がどれだけあって、協力体制をどれだけとることができるのか、その辺の感覚的なところになるかと思いますけれども、それはいかがですか。","respondent":"小川木密整備推進課長","answer":"我々としましては、そういったところもしっかりと関心を持ってもらえるように、今、推進機構を指定させていただきましたので、ちょうど明日からまた戸別訪問を行わせていただいて、しっかりと事業手法等について検討させていただきたく。","voiceIndex":85,"id":"exchange-030"},{"speaker":"西本委員","kind":"質問","question":"ただ、安全性を含めて、こういう形にしたいと思っているという、本来は皆さんの意見を聞きながら、考えていくということが一番いい筋道なのだろうけれども、ただイメージがつかないということであれば、危険性を啓発するとか、それからこういうイメージを持って、このまちをつくっていくのだとか、そういうのを少し提示してもいいのではないかと思うのですが。","respondent":"小川木密整備推進課長","answer":"推進機構と区がしっかりと連携して、より今まで示した以上の計画を地域の皆様のお考え等を踏まえながら提案していきたいというところと、併せてやはり地域の危険度がかなり高いのだというのが、皆様もご認識はあるかと思いますが、いま一度しっかりとお伝えして。","voiceIndex":87,"id":"exchange-031"},{"speaker":"西本委員","kind":"質問・要望","question":"今、無関心だから、割と静かなのだろうと思うのです。結局、何もないと、どこに行ったらいいのだとか、ここを追い出す気かとか、いわゆる建築紛争でよく言われるようなことが起きてしまうので、そうではなくて、まち全体の安全それから本人の安全、健やかな生活ということを中心に、ぜひ交渉し続けていただきたいと思いますので、時々、報告をいただくと、うれしいかなと思いますので、お願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-032"},{"speaker":"田中委員","kind":"質問","question":"今回の件に関して、先ほどのご説明を聞いて少し疑問に感じたことがあるのですけれども、極めて個人的な話でいうと、私、平成１１年に区議会に入りまして、平成１７年までおりました。その辺の要因、それぞれの地権者の方の関心が薄いとかも少し説明はありましたが、両者を比較したときに、特に旗の台四丁目は結構、時間が経過してしまっているという印象を強く持ったのですが、いかがでしょうか。","respondent":"小川木密整備推進課長","answer":"地域内、高齢化も進んでおりまして、それと所有者と賃借人、それぞれもいろいろな状況がございまして、様々なご意見をいただいている中で、区としましても区の持っている用地等もございませんし、また、未接道であったり狭小地の場合は。","voiceIndex":91,"id":"exchange-033"},{"speaker":"田中委員","kind":"質問","question":"そういう状況にある中で、今回、この密集法はもう多分、同潤会のときにも既にあった法律だとは思うのですが、逆にここに来て動き始めた要因は、これまでの長年のご努力の積み重ねによって、地権者の状況も把握できるようになって、また地権者の方の関心度合いも少しずつ高まってきたから、こういう状況に今、現在なっているということなのでしょうか。","respondent":"小川木密整備推進課長","answer":"動き出した要因の一番大きなものといたしましては、やはり不燃建築公社からの申請をいただいて、ここを何とか防災上の課題を解消していきたいといったところでございまして、公社と区が連携して、これから地権者の皆様としっかりお話し合いをさせていただきながら。","voiceIndex":93,"id":"exchange-034"},{"speaker":"田中委員","kind":"質問・要望","question":"木密対策を区が主体的に行う中で、個々の対応はどうしてもこういう不燃建築公社などの働きによらざるを得ないということなのでしょうか。あるいは力というか、容量的に１か所ずつしか対応できないので、今回はようやく旗の台のほうに公社の対応が向くようになってきたのか。その辺の公社側の意向といいますか、考えも含めて、お聞かせをいただきたいと思います。","respondent":"小川木密整備推進課長","answer":"個々の対応等に関しましては、これから不燃建築公社と区のほうで連携して、地域に入るに当たっても、公社任せにはせず、区も同席して、しっかりと戸別訪問等に当たっていくといったところです。","voiceIndex":95,"id":"exchange-035"},{"speaker":"田中委員","kind":"質問・要望","question":"要は公社頼みということなのですか。あったとするならば、そこも並行して委ねるというか、届出を出してくださいというアプローチもしないといけなくなると思うのですが、その辺、改めてお聞かせいただきたいと思います。","respondent":"小川木密整備推進課長","answer":"ほかの地区については、やはりその地域の状況等を踏まえながら、いろいろと取組については、検討してまいりたいと考えています。","voiceIndex":97,"id":"exchange-036"},{"speaker":"若林委員","kind":"確認","question":"ちょっと確認等、します。このいわゆる密集法の第３００条に基づいて指定したのは、この公社にかかわらず、区内では、初めてなのでしょうか。","respondent":"小川木密整備推進課長","answer":"品川区では初めてでございまして、都内でも初めてです。","voiceIndex":100,"id":"exchange-037"},{"speaker":"若林委員","kind":"質問","question":"都内でも初めてですか。そうですか。そうすると、業務内容は第３０１条の中で大体定められていているのですけれども、いわゆる２３区の中では実績はないということですね。そうすると、否定的な意味では全然ないですけれども、いわゆる公社にとっても第３００条に手を挙げて、指定されたのは初めてという理解でいいでしょうか。","respondent":"小川木密整備推進課長","answer":"委員のおっしゃられるとおり、公社にとっても初めてです。","voiceIndex":102,"id":"exchange-038"},{"speaker":"若林委員","kind":"質問","question":"例えば何か法的な根拠を持って、強制力という言い方ではないのかもしれませんけれども、いわゆる今までの単独ではできなかったことができるようになるといった違いがあれば、明確に教えていただければ。","respondent":"小川木密整備推進課長","answer":"今までと何が違うのかのご質問ですが、密集法に基づく指定という形になりますので、法定の下で、防災街区の推進を行っていくということが前提となる地区と位置づけられますので、指定された法人につきましては、早い段階で土地の買取りが行えたり。","voiceIndex":104,"id":"exchange-039"},{"speaker":"まつざわ副委員長","kind":"質問","question":"ほかにご質問はございませんか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":106,"id":"exchange-040"},{"speaker":"のだて委員","kind":"質問・要望","question":"平面図などをつけていただくと、遊具はどこにあったりということがより分かりやすかったと思うので、それは今後の資料改善として要望しておきたいと思います。そうした声も聞いておりますので、残していただきたい。そして、今後、防球ネットをつけるということですけれども、バスケットボールができるようなバスケットゴールが設置されるのかどうか伺いたいと思います。","respondent":"高梨公園課長","answer":"今後とも、分かりやすい資料の作成には努めてまいりたいと考えています。迷路のほうは、現行のものは安全基準を満足してございませんので、撤去をいたしますが、同じような機能の迷路遊具に更新をしたいと考えています。","voiceIndex":110,"id":"exchange-041"},{"speaker":"田中委員","kind":"質問・要望","question":"極めて細かい話で恐縮です。これがちょっと小さくてよく見えないのですけれども、ネットの左側のところが、仮に滑り台で、たしかその広がる形のものは赤いやつなので、これがまさにそれなのかなと思ってしまうのですが、すみません、極めて細かい話で恐縮ですが、そういう声があるということと、それに対するお考えをお聞かせいただきたいと思います。","respondent":"高梨公園課長","answer":"細かいところですけれども、今後、公園改修に当たっては、細かいところの声もできるだけ拾って、可能な限り、ニーズに合った遊具が設置できるように努めてまいりたいと考えています。","voiceIndex":113,"id":"exchange-042"},{"speaker":"西本委員","kind":"確認","question":"１点だけ確認いたします。公園便所なのですけれども、これは防災トイレという認識でよろしいですか。災害のときでも使えるような形にしているという認識でよろしいでしょうか。","respondent":"高梨公園課長","answer":"トイレの下部にピットがございまして、有事の際にはそこにためることができるということで、災害時も対応できるということで整備をする計画です。","voiceIndex":116,"id":"exchange-043"},{"speaker":"まつざわ副委員長","kind":"質問","question":"ほかにいかがでしょうか。よろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":118,"id":"exchange-044"},{"speaker":"のだて委員","kind":"質問","question":"今回、工期が９１日延伸するということなのですが、そうすると、この子供の森公園の隣のところで立坑があると思うのですが、今後の公園の範囲拡大とかそういったところとの影響というのはないのかどうか、伺いたいと思います。","respondent":"北原河川下水道課長","answer":"最後に工期延伸に伴う影響についてですが、現在のところ、令和６年度末までに子供の森公園隣接地を返却できるように考えてございまして、今後の施工方法も含め、検討しています。速やかに返却できるように努めてまいります。","voiceIndex":122,"id":"exchange-045"},{"speaker":"まつざわ副委員長","kind":"質問","question":"ほかに質問はありますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":124,"id":"exchange-046"},{"speaker":"まつざわ副委員長","kind":"質問","question":"初めに、(1)議会閉会中継続審査調査事項についてですが、お手元の申出書（案）のとおりでよろしいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":125,"id":"exchange-047"},{"speaker":"まつざわ副委員長","kind":"質問","question":"(2)委員長報告についてです。昨日の議案審査の結果報告については、正副委員長にご一任いただけますでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":127,"id":"exchange-048"},{"speaker":"まつざわ副委員長","kind":"確認","question":"報告が終わりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":131,"id":"exchange-049"},{"speaker":"のだて委員","kind":"質問・要望","question":"周知をやっていくということですけれども、ぜひ知らない人がいないという形で広く周知をして、皆さんから意見をしっかり聞いていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":132,"id":"exchange-050"},{"speaker":"まつざわ副委員長","kind":"確認","question":"報告が終わりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":135,"id":"exchange-051"},{"speaker":"のだて委員","kind":"質問","question":"朝５時から夜までお疲れさまです。ご苦労さまです。今回、被害がなかったということで本当によかったと思うのですけれども、今回のこうした一連の流れの中で、課題が何かあったのか、改善点などがありましたら伺いたいと思います。","respondent":"平原防災課長","answer":"ありがとうございました。課題といいましょうか、これまで風水害対応につきましては、令和元年に台風第１５号、第１９号が来たときに、初めて、自主避難施設を開設することとしました。","voiceIndex":136,"id":"exchange-052"},{"speaker":"西本委員","kind":"質問・要望","question":"９月８日の台風１３号なのですけれども、今回も避難場所が設置されて、開設しなかった、準備のみということなのですが、これはまだまだ周知徹底がされてないと思うのです。地震のときの避難所と土砂災害等々に対する避難所が周知徹底されてないと思います。なのでその辺を一工夫していただきたいと思いますが、いかがでしょうか。","respondent":"平原防災課長","answer":"ご指摘のとおり、しっかりと分かりやすい形で、今回につきましても、ホームページ、Ｔｗｉｔｔｅｒ等々でお流しさせていただいたところですが、随時、事前の周知を含めまして、工夫して進めてまいりたいと考えています。","voiceIndex":139,"id":"exchange-053"},{"speaker":"田中委員","kind":"質問・要望","question":"のだて委員同様、本当に感謝申し上げます。早朝から遅くまでお疲れさまでした。それで、この中のまず台風１３号対応の１０時の時点で、巡回パトロール出動とありますが、これは職員の方だけの巡回だったのか、通常というか、協定上、建設防災協議会の方による巡回パトロールということもお願いをしている部分がありますが、今回はどういう対応だったのか、お聞かせいただきたいと思います。","respondent":"平原防災課長","answer":"台風１３号の対応につきましては、今、委員がご指摘のとおり、職員の巡回に加えまして、協定事業者のご協力も得て行ったところです。","voiceIndex":142,"id":"exchange-054"},{"speaker":"田中委員","kind":"質問・要望","question":"そうしますと、職員の方に対しては、５時３４分からの警報によって対策本部が設置されてということで、情報共有はできているかと思うのですけれども、協議会の方に対してはどういう形で連絡をし、１０時の時点以降、どういう形で巡回パトロールが行われ、最終的には解散になったわけですが、どこまでどういう形で協議会の方の協力体制を維持してきていただいたのか、そこをお聞かせいただきたいと思います。","respondent":"平原防災課長","answer":"各社別々のところから向かっていただくというよりも、連絡員を災害対策本部に派遣いただいて、そのような共有できる場の下に、指揮統括して実際の活動に動いていただいているところですので、共有体制から実際の動き。","voiceIndex":144,"id":"exchange-055"},{"speaker":"田中委員","kind":"質問","question":"そうすると、５時３４分の時点から連絡員の方に連絡が入って、そこからもう体制を整えていただくようなお願いになっていたのでしょうか。","respondent":"平原防災課長","answer":"今回は注意報というところからスタートいたしましたが、どのようなシグナルになったときに、どう動くかということをあらかじめ決めておりましたので、今回でいきますと、１０時という形で巡回パトロールを開始しましたが。","voiceIndex":146,"id":"exchange-056"},{"speaker":"若林委員","kind":"確認","question":"確認で、今の協定事業者のくだりですけれども、いわゆるこの台風１３号は大雨警報。ルールがあるということで、大雨警報の発表なのか、洪水注意報発表なのか、その確認と、そうすると９月１５日の大雨は、これも大雨警報が発令されていて、洪水注意報も。こちらも、そうするとこの文面ですと協定事業者は出ていないような形かと理解していたのですが、そこら辺はどうなのでしょうか。","respondent":"平原防災課長","answer":"台風１３号につきましては、先ほどの繰り返しになりますが、事前の情報で、土砂災害に係る何らかの気象情報が出る可能性があったということで、土砂災害ですので、崖地の対応が必要となることで、あらかじめ、建設防災協議会のところの崖に対応するところのお願いをして。","voiceIndex":150,"id":"exchange-057"},{"speaker":"まつざわ副委員長","kind":"確認","question":"行政視察の同行理事者につきましては、中村都市環境部長との報告を区長より受けておりますのでご報告いたします。次に、お手元の行政視察についての資料を基に、視察先の概要について確認していきたいと思いますが、これ以降は、同行される都市環境部長のみお残りいただき、その他の理事者の方は、ご退席いただいて結構です。どうもお疲れさまでした。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":153,"id":"exchange-058"},{"speaker":"まつざわ副委員長","kind":"質問・要望","question":"進め方については、まず、事前に配付いたしました資料を基に、私から視察先についての概要をお話しし、その後に、視察先への質問や確認したい事項などの発言をお願いしたいと思います。次に、視察先で特に質問や確認したい事項、ご要望等がございましたら、ご発言いただきたいのですが、先日の岡山市と同様に、高松市からも現時点での質問事項があれば、お知らせいただきたいとのご依頼がございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":154,"id":"exchange-059"},{"speaker":"西本委員","kind":"質問","question":"すみません、岡山市への質問ですけれども、もうお渡しになっているのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":155,"id":"exchange-060"},{"speaker":"西本委員","kind":"質問","question":"そうなのですか。さらっとでいいのでどんな内容を出されたのかなという。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":157,"id":"exchange-061"},{"speaker":"まつざわ副委員長","kind":"質問・要望","question":"１０月４日までに、事務局にご提出いただけたらと考えています。そこで、１点目はマスクの着用についてです。マスクの着用は現在、個人の判断に委ねられておりますが、基本はそのとおりとしたいと思いますが、視察先から着用を求められた場合などを含め、委員長の判断に応じて、すぐに着用できるよう、各自で準備していただくようお願い申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":159,"id":"exchange-062"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4390#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":59644,"voices":159}},{"id":"r05-20230926-9","meetingId":"r05-cm09","date":"2023年9月26日","dateIso":"2023-09-26","committee":"文教委員会","time":"午前１０時００分～午後 ２時３８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を71件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第１回および第２回品川区学事制度審議会の実施報告","agenda":"第１回および第２回品川区学事制度審議会の実施報告","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"開催予定なのですけれども、今月もやるのかというか、全体としてこれまで２回やったと、９月も開催するとなると、これから６回、計８回の開催ということでよろしいでしょうか、伺いたいと思います。","respondent":"柏木学務課長","answer":"毎月１回という予定ですが、１２月については実施しないということを考えてありますので、３月まで全８回という形になります。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"提案","question":"逆に言うと、既に区教育委員会の中では、提案内容がある程度固まっていなければこういう運営にはならないのではないかなと思うのです。中身について伺いたいのですけれども、第１回、第２回の意見交換で出た主な意見の内容を紹介していただきたいのと、あと、第２回のほうですけれども、最新の就学人口推計というのが報告されたようですが、この内容について伺いたいと思います。","respondent":"柏木学務課長","answer":"第２回のほうにつきましては、集合住宅について、分譲と賃貸では就学人口の発生状況が違うのか、普通教室の確保が難しい学校においての通学区域見直しの有効性について。","voiceIndex":7,"id":"exchange-002"},{"speaker":"安藤委員","kind":"確認","question":"最後がよく分からないのですが、議論の方向性が示されたと書いてあるのですけれども、これは何なのかという質問なので、教えてもらいたいです。安定的に児童・生徒を受け入れる態勢を確保するための方策ということを審議してほしいということですが、これはこれまでも示されていますけれども、学区の変更のことなのでしょうかという確認で、それ以外にもあるのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"それで、学区の変更のことも方策の一つに入るということでいいですかという確認を後でしてもらいたいと思います。ということなので、ホームページへの掲載を早くしてほしいのですがそれがいつになるのか、前回と同じような要旨という形で出るのか。そうでないと何を審議したのか全然分からないということで、そこら辺の資料の掲載もお願いしたいのですけれども、いかがでしょうか。","respondent":"柏木学務課長","answer":"今回の文教委員会に出しております実施報告の資料につきまして掲載するかどうかについては、検討します。ただ、こちらの資料につきましては区議会のホームページのほうにも出ておりますので、二重で出すのかというのは考えたいと思います。","voiceIndex":12,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"それこそほとんどが文言整理なので、事実上、パブリックコメントにかかっている時点でもう決まるのです。なので、２つ目の質問は、地域の方の声を、案をつくる前の段階で、このメンバーとは別に、このメンバーの方に審議してもらう上でも何らかの酌み取りの手段、それは事務局が汗をかく必要があると思うので、その上で審議をしてもらうことが大事だと思うのですけれども、その点についてはいかがでしょうか。","respondent":"柏木学務課長","answer":"初めに、当日資料の掲載につきましては、現在のところ掲載する予定はございません。個別的な情報等もありますので、現在のところ掲載する予定はございません。","voiceIndex":14,"id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後の点は、ぜひそれにとどまらず、事務局としても地域や保護者、子どもにとって重要な事柄ということはよく自覚されていると思うのです。非常に実質的な地域の声、生の声も含めて審議の材料とできるように、受け身だけではなく積極的に役割を果たしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-006"},{"speaker":"ゆきた委員","kind":"質問","question":"７月４日の文教委員会にて学事制度審議会の設置について報告がありましたが、その場で７月に諮問、１２月にパブリックコメント実施、翌年の３月に答申で、令和７年度新入学者から申請の適用を開始することを目指すというふうにありました。このスケジュールに関しては、変わりはないでしょうか。","respondent":"柏木学務課長","answer":"現時点ではスケジュールについては、当初お話ししたとおりで進めてあります。","voiceIndex":18,"id":"exchange-007"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"１点だけ確認です。以前、文教委員会で要望させていただいたパブリックコメントを行うということについての、その前の段階の周知といったところで工夫とか、何か進捗があれば教えていただければと思います。","respondent":"柏木学務課長","answer":"以前ご要望いただきまして、すみませんが、審議会のほうでパブリックコメントの内容等についてもまだ審議をしてないものですから、その審議の中で事前通知等の審議もさせていただきたいと考えています。","voiceIndex":20,"id":"exchange-008"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"ご答弁ありがとうあります。以前もお伝えさせていただいたとおりで、パブリックコメントをやる前の、それをやるということの周知については、なかなか周知がまだまだきちんとされていないかなというところがあるので、保育園の掲示とか、あとチラシとかで周知の検討を図っていただければと思います。こちらは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-009"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"１点だけ、メンバーですけれども、おおよそでいいので、どのくらいの平均年齢なのかを教えていただきたいと思います。","respondent":"柏木学務課長","answer":"すみません、全員の年齢を把握していないので、何とも言えないところがありますけれども、４０代後半、平均だと多分５０代ぐらいですか。","voiceIndex":24,"id":"exchange-010"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"なぜこれを聞いたかというと、結局、区教育委員会だけではなくて、これはもう区全体に言えることなのだけれども、何かの会議体で物事をいろいろ決めていくときに、結局平均年齢が高いのです、どの会議体も。なので、もうちょっと幅広いメンバー構成にしたほうがもっと充実した会議体になるのかなと思いますので、その辺のメンバーについて、もしご意見があれば教えてください。","respondent":"柏木学務課長","answer":"今後、学事制度審議会に限らずほかの会議体等につきましては、検討する内容によっても年齢を各世代から選んだほうがいいものとか、専門の方たちだけでやったほうがいいものがあると思いますので、それは各会議体、審議会等含めまして。","voiceIndex":26,"id":"exchange-011"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"でも、この設置目的を見ると、私はそういった方たちの声も十分反映するべきではないかなというふうに思うのです。そうすると、会議体だけではなくて、ほかの政策にも絶対つながっていくと私は思うので、そういった意味も含めて、ぜひこういった会議体にはそういった観点も取り入れていろいろ今後は検討していただきたいなと思うので、最後に、それについてご意見があれば教えてください。","respondent":"柏木学務課長","answer":"少し繰り返しになる部分はありますけれども、会議体の目的等に合わせてメンバーの選定というのは考える必要があると考えております。","voiceIndex":28,"id":"exchange-012"},{"speaker":"せお委員","kind":"質問","question":"私からも、今の石田しんご委員と似ているところがあるのですけれども、本当に多様な方が入ってほしいなというのは、私もそういう思いがあります。今回、第１回で欠席委員の方が１名いらして、第２回で２名いらっしゃるのですけれども、これはオンラインでも一緒に行うハイブリッドというか、そういった形では検討されなかったのですか。","respondent":"柏木学務課長","answer":"本審議会ですが、基本的には対面で実施ということで考えてございましたので、オンラインについては検討してございません。ただ、今回欠席された方は仕事の関係でほかの所に行くという理由ですので、多分オンラインにしても参加はできなかったという部分はあります。","voiceIndex":31,"id":"exchange-013"},{"speaker":"せお委員","kind":"意見","question":"この３年ぐらいオンラインの必要性というのはずっと言われていたので、そこはもうちょっと前から検討してほしいなと。","respondent":"柏木学務課長","answer":"最初のオンラインについては、今後、区役所には来ることができないけれどもオンラインなら参加できるという場合は検討させていただきたいと思います。","voiceIndex":33,"id":"exchange-014"},{"speaker":"せお委員","kind":"質問・要望","question":"そこら辺は理解しました。若い世代、そして高齢者の方もいろいろな思いが、子どもに対する思いがあったりする方もいらっしゃるので、そういった方も中心に入っていただいて、オンラインがあることでまた気軽にというか、しっかり皆さんの意見を集約できるのかなと私も思いましたので、そこはちょっと要望させていただきましたので、検討をお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-015"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"３つ目は、学区についての検討がなされると思うのですが、前回もそうでしたけれども、これはある程度煮詰まってからの話になるかと思いますが、今でももういろいろな区民の方からどうなるのだろうみたいなお話があって、特にご兄弟で学区が変わってしまった場合は、なかなかまた同じ学校では厳しいのではないかというご心配とかがあるので、経過措置も含めてそういうところまで検討して。","respondent":"柏木学務課長","answer":"学区の変更等で兄弟がですが、こちらについてはまだ審議されてございませんので、現時点ではちょっとお答えはできません。","voiceIndex":37,"id":"exchange-016"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"審議事項の2)については、未改築の学校がある云々ということだったのですが、確認したいのですけれども、学校の再編成に伴うことに関しては今回の審議事項には入っていないと別の機会にお尋ねした記憶があるのですが、当然再編と絡んで改築するかしないか、Ａという学校とＢという学校がもし改編されるとすると、どちらかは改築しないといけないということが出てくると思うのですが。","respondent":"柏木学務課長","answer":"学校の再編成につきましては、委員ご指摘のとおり、今回の審議事項には含まれてございませんので、今回の学事制度審議会においてそういう答申が出されることはないと考えています。","voiceIndex":39,"id":"exchange-017"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"そこに区としては参加してほしい、教育委員会としても参加する人が増えたほうがありがたいはずだと考えていますので、ぜひあらかじめの周知と、それから期間をできるだけ長めに取っていただきたいと思います。それは区としても本意ではないと思いますので、ぜひあらかじめの周知と、それから期間をなるべく長く取っていただきたいのですけれども、その辺について何かご答弁いただければと思います。","respondent":"柏木学務課長","answer":"パブリックコメントの事前周知、あと期間につきましては、学事制度審議会の設置の報告をしたときにもご意見をいただいていますので、パブリックコメントの審議のときには、文教委員会からそういう意見もあるということはきちんと伝えてまいりたいと思います。","voiceIndex":42,"id":"exchange-018"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"当然教育委員会としても多くの方たちのコメントはいただきたいと思っていらっしゃるに違いないと信じておりますので、その辺はぜひよろしくお願いします。時期ですが、大体いつ頃というのが分かれば教えていただきたいと思うのですが、いかがでしょうか。","respondent":"柏木学務課長","answer":"第２回のほうですけれども、こちらの議事録はまだ委員全員の確認が取れてございませんので、それが取れ次第、ホームページで公開したいと思います。","voiceIndex":44,"id":"exchange-019"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"なるべく早くお願いしたいと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"特に案件が案件だけにと考えていますが、いかがでしょうかということが一つです。新庁舎関連の後半の審議会ではそのように改善されて実際にやっていたので、そのように運用していただきたいのですけれども、いかがでしょうかというのが２点目です。","respondent":"柏木学務課長","answer":"説明会の件ですが、現在のところ予定はしてございません。","voiceIndex":48,"id":"exchange-021"}]},{"id":"topic-02","title":"品川区いじめ問題調査委員会による調査結果","agenda":"品川区いじめ問題調査委員会による調査結果","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"資料に基づいて幾つかお伺いするのですが、裏面の上の(1)の1)です。(1)の2)のところですが、児童・生徒に対して無記名式のアンケートを実施とあるのですけれども、現在やっているこのアンケートの内容というのはどういうアンケートを取っているのか、今後変える予定というのはあるのか、あるならどのように変える予定なのか伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"対象は全教職員約１,０００名、内容は「いじめに関する事実と具体的対応」というテーマで、講師は、公益社団法人子どもの発達科学研究所の主席研究員であります和久田学氏をお招きしております。","voiceIndex":60,"id":"exchange-022"},{"speaker":"安藤委員","kind":"質問","question":"いじめの認知のアンケートを取るということだと思うのですけれども、このいじめの調査の内容ですとか認知の方法が、他の自治体とそもそも大分違うのではないかと考えざるを得ないのです。区教育委員会はこの数字のあまりに大きな乖離について、アンケートや認知方法との関連についてどのように考えているのか伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"そういったことも管理職向け、生活指導主任向けの研修では認知率の違いについても説明をし、軽微ないじめであっても、それはいじめとして認知して報告するよう求めているところです。今後改善が図れるように我々も尽力してまいりたいと考えております。","voiceIndex":62,"id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"非常に率直で誠実な答弁なのではないかと思いましたけれども、そうだと思うのです。いい答弁だなと思いました。しっかりと取り組んでいただきたいと。次に伺いたいのですけれども、少し戻ってしまうのですが、表面の３の下の部分に「真摯に受け止め、事務局内の認識を改める」とあります。これはどのような認識を改めるのかなということを伺いたいと思います。よろしくお願いします。","respondent":"丸谷教育総合支援センター長","answer":"こうしたご指摘を教育委員会内部、事務局内部でも確認しながら、一点一点について真摯に受け止めて改善を図っていこうというところで、今、取り組みを進めているところです。","voiceIndex":64,"id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"今回は概要の資料がついていますけれども、本文を読むとかなり厳しい指摘なのです。本文の１８ページなのですが、２点目の本件いじめの重大性への理解の欠如というところの指摘です。」ということなのです。かなり根本的なところだと思うのです。この指摘、今、読み上げたようなところなのですが、なぜ区教育委員会はこのいじめの重大性というのを理解できなかったのでしょうか、お伺いいたします。","respondent":"丸谷教育総合支援センター長","answer":"ただし、法に基づいた重大事態の認定というところでは教育委員会の認識が欠けていたということは間違いございませんので、こちらについては重く受け止めて、改善を図ってまいる所存です。","voiceIndex":66,"id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後、２点だけ伺って終わりにします。区長部局のいじめ相談窓口が区教育委員会と連携とありますけれども、今後の区教育委員会、とりわけいじめ問題全般を分掌するのは教育総合支援センターですから、その教育総合支援センターと、区長部局に設置されるこの窓口との関係というのはどうなるのか、どう連携するのかを伺いたいというのが１つ。これについての進捗状況について伺いたい。","respondent":"丸谷教育総合支援センター長","answer":"今後区長部局に設置される組織との連携、関係性についてですけれども、区長部局もこれから立ち上げていくということで、その立ち上げの段階から教育総合支援センター、教育委員会事務局と、どういう役割分担でどういう機能を持たせるのかというところは。","voiceIndex":68,"id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういう立場から、教育委員会とは別のところの機関というのも大事だなと思うのです。これから連携が必要だと思うのですが、一方で適切な緊張関係というのも私は必要だと思っていますので、あまり具体的には言えないのですけれども、子どもたちにとっていじめ解決に資するような体制を、ぜひ区長部局ともしっかり連携しながらつくっていっていただきたいというふうに強く要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-027"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"いろいろご説明ありがとうございました。先ほどセンター長からいじめを早期発見するには軽微のいじめの認知ということでご説明がありましたけれども、５月のいじめのことをも踏まえて、現時点で軽微な、あってはならないのですけれども軽微ないじめがあったかどうか、今まで報告があったかどうかというのを確認させていただきたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"５月に各管理職、それから６月には生活指導主任会で説明をいたしました。すみません、今、手元に報告書がないので細かな具体事例は述べることができないのですけれども、確実に昨年度よりも認知の件数は上がっているというような認識で思っております。","voiceIndex":72,"id":"exchange-028"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ありがとうございました。被害を被った被害者に対して、あってはいけないけれども、今後もっとすごく寄り添っていただきたいということを私は感じておりまして、この記載のとおりで、私の本当に思っていることなのですけれども、これは私の要望というか意見なのですが、もし何かあったら教えていただきたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"そうした意味で、管理職への意識を高めるために研修会も行ったところです。あわせて、教職員につきましても先日の全教職員向けの研修会を行いましたが、多くの教員がいじめについての理解が深まったというような回答をしております。","voiceIndex":74,"id":"exchange-029"},{"speaker":"石田（し）委員","kind":"質問","question":"先ほどの安藤委員への答弁の中で、区のほうの相談窓口について、いまいちどのような窓口になるのかというのがよく分からないのですが、これまだ決まっていないということでいいのでしょうか、それが１点です。例えば発生して、どうやって対応して、どうやって報告していくというのが。このマニュアルがあるのかどうかというのを教えてください。以上、２点です。","respondent":"丸谷教育総合支援センター長","answer":"いじめ事案発生時の対応についてのマニュアルですけれども、学校ではいじめが発生した際につくる様式を定めておりまして、それを基に、毎月区教育委員会に報告する仕組みになってあります。そういった意味でのマニュアルという形です。","voiceIndex":78,"id":"exchange-030"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"窓口に関しては、正直、複数の窓口を持つべきなのか、１つの窓口にするべきなのか、アプローチ方法はいっぱいあっていいと思うのです。なぜかというと、教員だって教育委員会に報告するのはいろいろな意味で怖いこともあったりして、それは自分の仕事への査定も入るわけだから。私は、ずっと１時間研修を受けて、こうだ、こうだといっても、だって、みんな分かっているでしょう。","respondent":"丸谷教育総合支援センター長","answer":"我々教育総合支援センターにいる指導主事が学校訪問した際に、管理職だけではなく、当該の担任であったり、学年主任であったり、そうした教員とも一緒にいじめ対応をどうしていくかというところを検討しながら進めているところです。","voiceIndex":80,"id":"exchange-031"},{"speaker":"石田（し）委員","kind":"意見","question":"それぞれありがとうあります。持っているのだから、それをどうやって伸ばしてあげられるか、守ってあげられるかというのが区教育委員会の役割だと私は思うので、ここでは個々の先生の話をしてもしようがないので、ぜひ教育委員会としてそこは再度認識を改めてもらって、一緒に児童を守ることをしていただければなと思いますので、よろしくお願いいたします。ありがとうございました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":82,"id":"exchange-032"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"よろしくお願いします。それを踏まえて、最初に別の委員の方が、品川区が行ってきた教育改革の結果、それの影響で学校の先生方が本来業務に影響が出て、いじめを含めたそういったことに関して取り組むこと、正確でなかったら訂正してください、いじめ等に取り組む時間、体制が整わなくなってしまっている事実があるということをおっしゃったのですが、それは事実ですか。","respondent":"丸谷教育総合支援センター長","answer":"今、ご指摘がありました品川区が進める教育改革がゆえにいじめ対応が意識として低くなったのではないかというような捉えは、我々は持っておりません。品川区の教育目標の第１に人権教育ということがうたわれていますし、そのことは常に教員研修でも伝えているところです。","voiceIndex":84,"id":"exchange-033"},{"speaker":"高橋（し）委員","kind":"質問","question":"教育改革と今回のこういったことというのは、教育改革にはいろいろなプラスのところもあったり、いろいろな課題もありながら進めていると思うのですが、そこに関して、今お話があったように関連性はないというご答弁なので、そういうことでよろしいですか。","respondent":"丸谷教育総合支援センター長","answer":"明確な関連性があるというふうには捉えておりません。","voiceIndex":86,"id":"exchange-034"},{"speaker":"高橋（し）委員","kind":"意見","question":"それで、調査委員会の報告の中に２点あって、１つは学校が対応するとして、その能力を超えたという表現があったのですが、そこのところで、学校として、あるいは教育委員会として学校の対応能力を超えるというのはどういうときなのかというのが、この調査報告のところなのですが、その辺は、どういうときが対応能力を超えたと教育委員会としては判断しますか。","respondent":"丸谷教育総合支援センター長","answer":"当該のいじめ事案については、様々教育委員会も一緒に考えながら、とにかくいじめの行為をなくそうということで取り組んできたわけですけれども、最終的にはいじめ行為が止まることなく、転校を余儀なくされたということでございました。","voiceIndex":88,"id":"exchange-035"},{"speaker":"高橋（し）委員","kind":"質問","question":"いや、調査委員会では判断したのですけれども、現実の現場として、今お話があったような状況になったときは、これはもう学校の対応能力を超えていると、では、どうしようかという話になるとすると、その先のことも聞きたいのですが、まずはそういった認定というか、「これはもう厳しい、学校では無理だよ」みたいな感じになるという判断は、今みたいなときにするという形でよろしいのですか。","respondent":"丸谷教育総合支援センター長","answer":"それだけではなくて、外部の警察等との連携も行ってきたわけです。そういった意味では、ただ単に学校だけで取り組んで能力を超えたというよりは、関係諸機関とも連携を図りながらいじめ問題に取り組んでいく姿勢というのは今後も必要だと考えております。","voiceIndex":90,"id":"exchange-036"},{"speaker":"高橋（し）委員","kind":"質問","question":"すると、まだ具体的にどうかというお話はなかったのですが、ただ、実際に動くとなると、その４人の方も動きますので、教育委員会というか学校にはＨＥＡＲＴＳもあったり、そういった学校の組織もあるのですけれども、教育委員会としては、区長部局のこの４人の専門家の方が相談を受けて動くときにどのようなことが協力できて、どのようなことが、連携という言葉は非常に曖昧なのですが。","respondent":"丸谷教育総合支援センター長","answer":"今回、区長部局に設置される組織の専門家の先生方とも、大切なのは多角的な視野で多角的な見方をすることで、いじめ問題について、教育委員会だけでは、学校だけでは見えなかった部分が見えてくるものだろうというふうに考えておりまして、専門家の意見を聞きながら。","voiceIndex":92,"id":"exchange-037"},{"speaker":"高橋（し）委員","kind":"質問","question":"区長部局の窓口がどういうふうにするというのが分からない中で質問するのは申し訳ないところがあるのですけれども、イメージとしては、４人の方がこうこう、こういう視点で取り組んでといったときに、学校や教育委員会が実動隊として動いていくのか、それともというところがあるので、それはまた具体的に分かったときにお尋ねします。すみません、分からないことを話してはあれですので。","respondent":"丸谷教育総合支援センター長","answer":"その中で教育委員会としてフォローできる部分、例えばＨＥＡＲＴＳですとか、スクールソーシャルワーカーや心理職もおりますので、そういった人材も活用しながら子どもたちへの支援、学校の支援を進めていこうと考えております。","voiceIndex":94,"id":"exchange-038"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"長くなりましたけれども、今のお話の中で、教育委員会としてこういう姿勢でやっていくというのは大変重要で、教育委員会は本当に独立した機関であるわけでありまして、区長部局のほうがつくることは別にいいのです。それがよりよくいじめをなくす方向につながっていくのだと思うので、すみません、その辺はいかがでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"当然我々としては教育的な視点を持ちながら対応に当たっていくわけですけれども、そうした教育的な側面、視点と、区長部局側の専門の先生方が持っている専門性、こちらのベストミックスといいますか、双方を合わせた形で解決に向かう。","voiceIndex":96,"id":"exchange-039"},{"speaker":"高橋（し）委員","kind":"意見","question":"それはお願いしたいところです。最後に一つだけ、防犯カメラについて、学校内に防犯カメラを入れることについて、これは予算とは関係なしに、学校、教育委員会としては現状ではどういう検討なり考え方を持っているか、最後に一つお願いします。","respondent":"丸谷教育総合支援センター長","answer":"防犯カメラの設置についてですが、今回の調査結果、また３月２９日に出された品川区いじめ対策委員会の答申にもありましたが、事案によっては必要な対処だというふうに考えております。","voiceIndex":98,"id":"exchange-040"},{"speaker":"吉田副委員長","kind":"確認","question":"ごめんなさい、いろいろな方からのご意見を聞いて頭の中が若干混乱しているのですけれども、前回、７月のご報告のときもちょっと伺ったのですが、今回、いじめの認知というか報告が遅れたということについて、一応マニュアルというか、これからはフローも明記して進めていくということなのですが、今回のことで言うと、いじめの報告書を学校から教育委員会に上げるタイミングとしては。","respondent":"丸谷教育総合支援センター長","answer":"いじめがこれ以上起こらないようにということで学校は様々な対応をするのですけれども、なかなかそれがうまくいかなかったというような事案でございました。それは学校内部の学校いじめ対策委員会の中で様々な方策を考えている、そこには教育委員会も関与しています。","voiceIndex":102,"id":"exchange-041"},{"speaker":"吉田副委員長","kind":"確認","question":"すみません、私の認識が間違っていました。この事例の場合は、そこで重大事態というふうに認知することが遅れてしまったということで、重大事態というのは、例えば学校からはこれは軽微ないじめがありましたという報告が上がったとしても、いろいろ調べるとこれは重大事態として対応すべきことなのではないかということを、これからは教育委員会としてやっていくということでよろしいですか。","respondent":"丸谷教育総合支援センター長","answer":"事象として重大事態になった時点で認定が遅れてしまったということが今回問題になりましたので、今は軽微ないじめであっても報告を上げるように学校には周知徹底を図っておりまして、その中で重大事態に該当するような事案については、教育委員会から学校に確認をしながら。","voiceIndex":104,"id":"exchange-042"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"これについては、議事についても非公開、議事録も非公開ということなのですが、もちろんかなりセンシティブな内容をやらなければいけないので、ほかでやっているような発言録とかは無理だと思うのですけれども、こういうことが話し合われたということの議事の公開はあってもいいのではないかと思いますので、その辺についてはいかがでしょうか、それをお願いします。","respondent":"丸谷教育総合支援センター長","answer":"品川区いじめ問題調査委員会の議事録、議事の報告ということですけれども、教育委員会の所管ではございませんので、私からお伝えすることができません。","voiceIndex":106,"id":"exchange-043"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"そちらの議事は分かりました。もちろん重大事態については、本当に内容そのものがセンシティブになりますし、個人情報というのは、公開を求める人も、そこにはあまり興味がないというか、そこが知りたい問題ではないのですというところがありますので、そういうことはしっかり教育委員会としても取り組んでいるということを示すためにも、なるべくこういう情報は公開していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-044"},{"speaker":"吉田副委員長","kind":"確認","question":"すみません。それは相談とか、それから教育委員会のことも含めて、重大事態の原因がいじめではなくても、きちんといじめ問題と同じように扱われるというふうに理解してよろしいでしょうか、その辺を確認させてください。","respondent":"丸谷教育総合支援センター長","answer":"ただし、児童・生徒の中には家庭環境であったりとか、学習のことであったり、様々なことで悩みを持っている児童・生徒がおりますので、そういった子どもたちにはそれなりの支援ということで、こちらのほうでしています。","voiceIndex":110,"id":"exchange-045"},{"speaker":"吉田副委員長","kind":"確認","question":"子どもに、さっきの相談窓口のことにつながってしまいますけれども、別にいじめに限らず、自分にとって困難なことがあったというふうに思えば、ＨＥＡＲＴＳも含めて先生に相談して、しかるべき事案については教育委員会に報告がされて対応されるというふうに理解していいでしょうか。すみません、しつこいようですがそれを確認したいと思います。お願いします。","respondent":"丸谷教育総合支援センター長","answer":"当然その後どうなったかというところまでしっかり追って、子どもの安全・安心を守っていくという姿勢で取り組んでおります。","voiceIndex":112,"id":"exchange-046"},{"speaker":"吉田副委員長","kind":"確認","question":"それを伺って安心いたしました。今の委員長のお話から、ああ、そうだ、そのことを確認しなくてはと思ってお話しさせていただきました。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":114,"id":"exchange-047"}]},{"id":"topic-03","title":"休憩前に引き続き、会議を開きます。 次に、(3)令和４年度指定管理者による管理に対するモニタリング・評価の結果","agenda":"休憩前に引き続き、会議を開きます。 次に、(3)令和４年度指定管理者による管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"図書館のほうです。ＡグループとＣグループのところで有資格者の配置等が課題になっていますけれども、６０％以上の配置ということを求めているその数字の根拠、考え方、それと、なかなか配置が実現できない原因をどう考えて、区としてはどのようにこれを達成していくようなお考えなのか伺いたいと思います。それが一つです。","respondent":"吉田品川図書館長","answer":"その際に、人件費などここに書いてある各項目を含めまして、今年度はこういう金額でいこうと決めた金額です。それが、事業者の従業員の個々の給料等は当然把握はしてないところですが、最終的に当初の予定の金額より給料の高い職員が配置されたというふうに考えているところです。","voiceIndex":123,"id":"exchange-048"},{"speaker":"安藤委員","kind":"質問","question":"家庭あんしんセンターについても、先ほどと同様に収支が赤字になってしまっているので、社会福祉法人福栄会ということなのですが、こちらも赤字額がかなり大きいということの原因と、それが人件費削減という形でサービスの低下につながってこないのか、そこら辺の心配はないのか、伺いたいと思います。","respondent":"飛田子育て応援課長、立木保育課長","answer":"こちらのほうは、人件費の削減とかそういうところにいかないように、福栄会と定期的な打合せをして指定管理の適正化、施設修繕の分担の明確化とか、そういうところで改善策と今後の方向を今、検討している最中です。ぷりすくーる西五反田の年間の収支のところで、差引収支が８６０万円ほどにマイナスになっているところがありますが、大きなものといたしましては。","voiceIndex":125,"id":"exchange-049"},{"speaker":"安藤委員","kind":"意見","question":"すみません、拠点区分間繰入金というのがちょっと分からないので、もう一度説明してもらいたいのです。拠点というのは、どこの何の拠点なのかというのと、繰入というのは誰がどこに何を繰入したのかというのが分からないので、もう少し説明してもらわないと何なのだろうと思ってしまうので、お願いいたします。","respondent":"立木保育課長","answer":"拠点区分間繰入金ですけれども、こちらのぷりすくーる施設のほうから運営本部のほうに事務経費としてお金を移しているものでございまして、これは福栄会の中でぷりすくーるから本部へという形の資金の移動という形になります。","voiceIndex":128,"id":"exchange-050"},{"speaker":"安藤委員","kind":"質問","question":"私立保育園の補助金として出して、そのところで使ってほしいのに、様々、流用しているという問題があるのですけれども、何かそれに近いのかなということをニュアンスとして感じてしまうので。ですから、こういうことは規定があって許されているのでしょうけれども、こういうふうな計上の仕方というのがどういうふうな仕組みであって、どういうふうに許されているのかというのを最後に教えてください。","respondent":"立木保育課長","answer":"こちらのほうは手続をきちんと取っておりまして、福栄会は社会福祉法人ですので理事会で審議をした上で、理事会の決定事項として決まっているものです。理事会のメンバーには区の職員も入っているため、区でも審議をしているというような認識を今持っているようなところです。","voiceIndex":130,"id":"exchange-051"},{"speaker":"安藤委員","kind":"質問","question":"これはぷりすくーる西五反田の運営のために出している指定管理料なので、しかも正式な規定はないということですので、私はちょっと違うのではないかなと思っています。これに関しては、私たち共産党としても私立のところで様々質問もしてまいりましたし、もう少し研究を進めて、必要な場面でまた質問したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":132,"id":"exchange-052"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"財務の視点ということでモニタリングされているというのはもう当然のことで、ぜひ今後もきちんとやっていただきたいのですが、私、いつも財務とともに労務について、だから働いている人たちの環境についても事業としてのモニタリングが必要なのではないか、それについては、ぜひ社会保険労務士の調査という視点を入れるべきなのではないかということをずっと求めていたのですが。","respondent":"吉田品川図書館長、飛田子育て応援課長、立木保育課長","answer":"それに回答いただいた中で、項目の中に「当館の利用について満足されていますか」とか、そのほかに幾つかの項目がある中で。令和４年度には東京都福祉サービスの第三者評価を実施させていただきまして、その辺も都のホームページに結果を公表しているところです。今後はそれも拡大していく予定ですので、そういった中で見ていけるかなというふうには考えております。","voiceIndex":134,"id":"exchange-053"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"ありがとうございました。まだ毎年ということではないということなのですけれども、働く人にとってのどういう仕事かということは利用者の視点と同時にとても重要だと思いますので継続していただきたいのと、報告のときに、そういう働く人にとっての状況がどうかという報告も受けて、議会としても議論できたらいいかなと思いますので、その辺の資料の出し方もご検討いただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":138,"id":"exchange-054"},{"speaker":"高橋（し）委員","kind":"質問","question":"順番があれなのですけれども、ぷりすくーる西五反田は指定管理者が変わって２年になるのですけれども、前の指定管理者のときには、ここでもあるのですがサービス、ほかの保育園にない様々な特徴を持った保育・教育活動を行っていたのですが、それはほとんどそのまま移行されているのかという点と、それから、保護者の方々は指定管理者が変わって。","respondent":"立木保育課長、吉田品川図書館長","answer":"なおかつ、福栄会自身も福祉の施設を多く持っているという部分では、先ほど申し上げました特別な配慮が必要なお子さんへの対応ですとか、そういった部分をさらに加えた形でしっかりと運営させていただいているというような状況です。今後ですけれども、他自治体においては新しい図書館、いろいろな意味での目新しい図書館が幾つか出てきているところです。その辺も含めまして、現在、情報収集をしています。","voiceIndex":140,"id":"exchange-055"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"なかなか図書館の在り方というのはあまり目立たないのですが、特に若者世代というか中高生を呼び込むというか、彼らにとってもある意味別の居場所というか、勉強することも含めて、そういうところの側面も図書館で、なかなか大人が行くことが多い、あと子連れの保護者の方が多いのですが、中高生が使えるように、あるいは集えるようにというか、利用できやすいようにするという、そういう観点はいかがですか。","respondent":"吉田品川図書館長","answer":"図書館における中高生への対応ですけれども、現在、中高生と言われるちょうど１０代に関わる、ティーンズ世代に対するサービスということで、ティーンズ世代に受ける本の充実を図るだとか、あとは、全ての図書館ではないのですけれども。","voiceIndex":143,"id":"exchange-056"}]},{"id":"topic-04","title":"品川区児童相談所の政令指定要請","agenda":"品川区児童相談所の政令指定要請","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"１の(1)の説明で、東京都から確認を受けることが必要だということで３回行ったということなのですが、ここに運営体制と都区間の連携方法とありますが、開設まであと１年ということで、人の確保というのはもう終わったのかということと、それと、都区間の連携についてはどういう確認をしたのでしょうか、伺いたいと思います。","respondent":"長谷川児童相談所開設準備課長","answer":"その後、子ども家庭支援センターや福祉部と人員関係の調整を行いますので、採用数が全て児童相談所配置というわけではないので、今後、人事課と協議をしていくといった状況です。","voiceIndex":149,"id":"exchange-057"},{"speaker":"安藤委員","kind":"質問","question":"様々ご説明いただいたのですが、改めて開設まで１年前のこの時点での準備の課題としては、今どこら辺にあるのかというのをざっと教えてもらえればと思います。お願いします。","respondent":"長谷川児童相談所開設準備課長","answer":"しかしながら、先行区には実は様々なやり方があって、それぞれが持って帰ってきた種が品川区の土壌に合うのかという視点や、ほかの自治体がやっているからうちもやれるのかということとか、そういったところのすり合わせをしていくといったところで。","voiceIndex":151,"id":"exchange-058"},{"speaker":"石田（し）委員","kind":"質問","question":"１点だけ。この間、様々東京都とはやり取りをされて、財源と権限と人事、この人事権というものはどちらかというと人材確保ということになるのかと思いますが、これというのはこれまでどのように協議が進められて、今後、区が必要だと思っているものと、東京都が思っているものとの違いというのが今あるのかどうかというのを教えてください。","respondent":"長谷川児童相談所開設準備課長","answer":"人員に関しましては先ほど申し上げたとおりで、東京都から人をもらうという話はありませんので、あくまでも区で人を育てる、あるいは採用して児童相談行政に精通する職員を育てていくといった視点で今やっております。","voiceIndex":154,"id":"exchange-059"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"そこは、私はどういうやり取りするのか分からないですけれども、必要であるのであれば、東京都との話合いの中でいわゆる人事交流ではないですけれども、そういったものをうまくしていただきながら、区として、設置者としてしっかりと人材確保できるように、もちろん区がしっかりと自前で確保して育てていくというのはもう大前提で、それはぜひ頑張っていただきたいなと思うのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":156,"id":"exchange-060"},{"speaker":"せお委員","kind":"質問","question":"政令で定める市と今後なってから、ちょっと違うところでお話を伺ったのが、児童相談所以外のところで、文教委員会ではなくて厚生委員会にも関わるところで、前までは都に監督責任があったのを区のほうに移管するというのを伺っているのですけれども、そういったところで答えられるところ、この文教委員会の範囲でいいのですけれども、例えば私立保育園といったところというのは、ごめんなさい。","respondent":"長谷川児童相談所開設準備課長","answer":"ここの部署に関しましては何度か課をまたぐ検討会をつくりまして、こういう事務が来ると、ついてはこれぐらいの事務量が発生すると、都との引継ぎはこういうふうにやってくれとか、予算要求はこうしてくれという話はさせていただいているところです。","voiceIndex":158,"id":"exchange-061"},{"speaker":"せお委員","kind":"質問","question":"そういうお話を漠然と伺っていたので、かなり大変だなというのは正直思っています。人も必要になってくると思いますので、ぜひ引き続き、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":160,"id":"exchange-062"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"開設に向けて大変お忙しい部分と、あと非常に困難な準備の時期だと思って、先日視察に伺わせていただきましたが、本当に皆様が期待しているところでありますので、頑張っていただきたいと思います。","respondent":"長谷川児童相談所開設準備課長","answer":"品川区に関しましては、先ほどご説明したとおり設置条例というものを今後提案する予定がございまして、その条例提案後に共同経理課の規約に載せる必要が出てくるというところで、改めて区議会等に報告をさせていただきたいと考えています。","voiceIndex":162,"id":"exchange-063"},{"speaker":"高橋（し）委員","kind":"意見","question":"それぞれありがとうあります。組織については、ごめんなさい、文教委員会というよりも総務委員会になるのかもしれませんけれども、部レベルだということです。たしかどこかの区は課レベルだったので、部レベルでやるということはそれだけ重要性があるということなので、よろしいことだと思います。認定については承知しました。それはここの文教委員会の話ではないので、感想です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":164,"id":"exchange-064"}]},{"id":"topic-05","title":"医療従事者の優先利用措置の廃止","agenda":"医療従事者の優先利用措置の廃止","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"ちょっと拙速かなと思っています。そこで伺いたいのですけれども、今の感染状況なのですが、その前に、この制度を使って加点されていた方というのは、直近だと４月ですか、何人ぐらいいらっしゃったのかというのが１点です。","respondent":"立木保育課長、柏木学務課長","answer":"優先利用の実績になりますが、今年度４月の一次選考のときの数字になりますが、医師、看護師ということで加点を受けている方が１８０人ほどいらっしゃいました。特に今週からインフルエンザの学級閉鎖が増えてあります。すみませんが人数については、現在は持っておりませんのでお答えできません。","voiceIndex":169,"id":"exchange-065"},{"speaker":"安藤委員","kind":"提案","question":"ですから、ちょっと拙速だなと思って、私も、「こういうことを今提案されているのだけれども、どう思いますか」と医療従事者の人に聞いたら、「もう見捨てられた気がする」とおっしゃっていましたが、そうだと思うのです。私は、拙速なので、優先利用措置を廃止する状況では今は全くないということで、支援が必要な医療現場の負担軽減につながるわけですから、優先利用措置の継続を求めたいと思うのです。","respondent":"立木保育課長","answer":"もともと保育園の入園調整にあたりましては、職業についての加点はしないというような取決めといいますか、国の方針もありますので、そうした中で医療体制のひっ迫に合わせて区も対応したという形があります。","voiceIndex":172,"id":"exchange-066"}]},{"id":"topic-06","title":"議会閉会中継続審査調査事項","agenda":"議会閉会中継続審査調査事項","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"場合によっては通常飛んでいる飛行機のことなのかなと思ってしまいますし、３時から飛び始めている飛行機のことだということがなかなか分からないという方もいるのではないかと思うのですが、この質問項目の内容というのは教育委員会のほうで案をつくったのか、それとも、意見を聞かれて案を教育委員会がつくったのですかということを教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":182,"id":"exchange-067"}]},{"id":"topic-07","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"つる委員長","kind":"確認","question":"進め方については、まず、事前に配付いたしました資料をもとに、私から視察先についての概要をお話しし、その後に、視察先への質問や確認したい事項などのご発言をお願いしたいと思います。兵庫県明石市です。１ページ、兵庫県明石市をご覧ください。令和５年１０月３０日、１日目です。３ページ、４ページをご確認ください。視察先への質問や確認したい事項などがございましたらご発言をお願いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":187,"id":"exchange-068"},{"speaker":"安藤委員","kind":"意見","question":"尼崎市のほうでユースワークという言葉が出てきますけれども、尼崎市のユース交流センターというところがありますが、ユースワーカーというところの役割とか、実際に何を行っているのかというところと、配置や育成というのをどういうふうにされているのかなという、非常に要だと思うので、そこは深めたいなと思いました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":188,"id":"exchange-069"},{"speaker":"安藤委員","kind":"質問・要望","question":"具体的な配置とか育成とかを聞かせていただきたいなというところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":190,"id":"exchange-070"},{"speaker":"吉田副委員長","kind":"質問","question":"私は０歳児の見守り訪問「おむつ定期便」ということで、品川区もおむつ宅配というのですか、決して別におむつを配ることが主たる目的ではなくて、見守りということを主眼にして行う事業だということを伺っております。契約になるので、どの辺まで言っていただけるか分からないのですけれども、そこはすごく大事なところだなと思いましたので伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":192,"id":"exchange-071"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5110#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":66158,"voices":193}},{"id":"r05-20230926-5","meetingId":"r05-cm09","date":"2023年9月26日","dateIso":"2023-09-26","committee":"総務委員会","time":"午前１０時００分～午後 ０時１７分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を34件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"説明に入る前に、各所管委員会における審査結果","agenda":"説明に入る前に、各所管委員会における審査結果","exchanges":[{"speaker":"松本委員","kind":"質問","question":"そこでお伺いしたいのですが、このChatGPTについて、ある意味、もちろん責任は部課長というところになるかと思うのですけれども、実際の運用に当たって担当していくというのは、今回この専門職として採用された方たちが担っていくのかどうか。この点お願いいたします。","respondent":"河西情報戦略担当課長","answer":"ただし、運用に関しては、今いる既存のメンバーでしっかりチェック等々を含めて実施していく予定です。","voiceIndex":7,"id":"exchange-001"},{"speaker":"松本委員","kind":"質問・要望","question":"せっかく専門的な方も登用されたということで、ぜひとも知見をいただきながら進めていただきたいと考えています。一方で想定外の事態というのが起こり得ることは、想定外を想定しないといけないというところがあると思うのですけれども、何がしかの損害が発生した場合の保険とかそういったものというのは考えていらっしゃるのか、その点お願いいたします。","respondent":"河西情報戦略担当課長","answer":"研修等々を通して、しっかり説明をしてまいりますというのが１点と、今回ChatGPTのサービスを利用するに当たって、システム上ChatGPTが職員とのやり取りを学習して、ほかの一般の方に伝えてしまうということがないようなサービスを選定しておりますので。","voiceIndex":9,"id":"exchange-002"},{"speaker":"須貝委員","kind":"質問","question":"調べてこなかったのですけれども、歳入のほうで、粗大ごみリサイクル事業の資源売払収入ということでありますが、これの中身だけ教えてください。","respondent":"遠藤財政課長","answer":"今回、粗大ごみのリサイクルということで、プラスチック製の衣装ケースのようなものと、それから自転車、これはリユースですけれども、あと羽毛布団のリサイクルと、この３つが対象になっておりまして、それぞれ引取りの業者があるのですが。","voiceIndex":12,"id":"exchange-003"},{"speaker":"須貝委員","kind":"質問・要望","question":"ChatGPT導入は、品川区、ほかの自治体もそうですが、今どんどん進んでいますけれども、品川区も取り組んでいくということで、各所管の事務の効率化がかなり図られていいのかなと思いますので、ぜひ皆さんに早く職員の方が使いこなせるようにしていただきたいと思います。それは要望です。なぜこういう概要、こういう書面というか文面になったのか、その辺について教えてください。","respondent":"勝亦総務課長","answer":"そういった中でも第三者的なところ、教育委員会や学校に少し言いにくいなというようなところもあろうかなというところがございまして、あえて学校や教育委員会と違うところに、また新たに間口を広げて相談窓口を受けていくという形でございまして。","voiceIndex":14,"id":"exchange-004"},{"speaker":"須貝委員","kind":"質問","question":"ただ、どうしてもこういうふうに書かれてしまうと、何もしていないのですかというような、今まで取組が甘かったのですかというふうに捉えられてしまうと思うのです。非常に残念なので、意見を言わせていただきました。結局第三者、弁護士が入って、弁護士がどこまで分かるのですかと。","respondent":"勝亦総務課長","answer":"それからこのポータルサイトのほうでも直接相談を受け付けられるような形を考えてあります。このチラシのほうにも、今委員からいただきましたような形で、できれば料金後納みたいな形で、ご意見を紙でも出せるような形で対応していきたいと考えています。","voiceIndex":16,"id":"exchange-005"},{"speaker":"澤田委員","kind":"質問","question":"いじめ問題、今いろいろご回答いただいたのですけれども、その中で私が１つ気になったのは、いじめ相談員、会計年度任用職員というものがあるのですが、こちらはソーシャルワーカーの方とかなのでしょうか。ほかに心理士の方とかはいらっしゃらないのかなということと、あと、その会計年度任用職員の方を採用するに当たっての基準みたいなものとかはあるのでしょうか。","respondent":"勝亦総務課長","answer":"ソーシャルワーカーということで、社会福祉士ですとか、臨床心理士ですとかそういった能力をお持ちの方を任用していきたいと考えています。任用に当たりましての条件等々については、これから整理してまいります。","voiceIndex":19,"id":"exchange-006"},{"speaker":"澤田委員","kind":"質問","question":"子どもの相談を受ける方ですので、寄り添ってしっかり話を聞いてくれる方で、心理的なことにも詳しい方が当たってくださるとすごくいいのかなと思います。（４）に「いじめの情報収集促進チラシの配布による児童・生徒およびその保護者からの積極的ないじめ情報の提供の促進」とあるのですが、この児童・生徒は本人を対象としているのでしょうか。","respondent":"勝亦総務課長","answer":"そういう点では、「いじめを見た」とか「これはいじめではないか」というそういった声も、児童・生徒、あとは近隣の地域の方等からもできるだけ収集できるような形でやっていきたいと考えています。","voiceIndex":21,"id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"だけれども、ではそういう施設を増やしていこうとか、その判断というものは、企画が最終的に要望してやるとかそういうことになるのか、区長部局と教育委員会が一緒になってやっていくのですか。もちろん区長も区長部局も知らなかったのは分かるのだけれども、こういうことをやっていくと、どこまで一緒になってやるのですかと。私は教育委員会の独自性もあるから、一生懸命やっているではないですか。","respondent":"勝亦総務課長","answer":"区長部局といたしましてというか、本件の相談体制の整備、それから解決への支援につきましては、あくまでも教育委員会、学校と連携しながらやっていくという考え方でございまして、学校としても教育委員会としても手に余るといいますか。","voiceIndex":25,"id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"答弁はいいです。それから、１つはおくやみコーナーの話が出たので、私は個人的にも１つになるのはありがたいなと。大変苦労したなと思っておりまして、自分自身の体験でもつい２年弱前ぐらいに体験しましたけれども、行政書士の方とやるのですが、私が違うのかもしれませんが普通の方はご相談して対応するのは行政書士なのですかね。普通は行政書士なのかなというところを教えてもらって。","respondent":"遠藤財政課長","answer":"実際の遺産相続だとかは難しい部分があろうかと思いますが、これはそれぞれの専門職の方が関係しなければいけないところがあろうかと思うので、ただそこは一方で行政のほうでどこまで立ち入っていいかというところもありますので、それは戸籍住民課のほうで。","voiceIndex":27,"id":"exchange-009"},{"speaker":"塚本副委員長","kind":"確認","question":"運用ルールの3)で、先ほど、これまでの質疑にもありましたけれども、個人情報等の区として漏えいしてはいけない情報が外に漏れないようにシステム的に制限をかけているということですが、これは入力のときにはじいたりするのですか。１,０００万文字プランというのは、基本的には無制限、全職員が使いたいだけ使える内容になっているのか、そこのところをお伺いしたい。","respondent":"河西情報戦略担当課長","answer":"もう１点、効率化の面で言いますと、業務の時間短縮につながりました。これは、ChatGPTを利用することで、１０秒程度で複数の文章案を作成でき、そこから検討できるようになりましたので、１から作る必要がなくなったというところがあります。２点目の質問です。","voiceIndex":31,"id":"exchange-010"},{"speaker":"塚本副委員長","kind":"質問","question":"分かりました。その一方で、頭を使わなくなるということを気をつけなければいけないというお話も出ていますが、効率というところでは本当に使えるものだと思います。より一層今までにない新しい発想というかそのようなことかもしれませんけれども、あればお伺いしたい。","respondent":"河西情報戦略担当課長","answer":"今、質の向上の話がございましたが、ChatGPTは、文章の作成依頼をしますと、自分の中にないアイデアで回答してくれます。","voiceIndex":33,"id":"exchange-011"},{"speaker":"澤田委員","kind":"質問","question":"聞き漏らしてしまったのですが、すみません。（１）にその他関係機関との連絡調整というのがあるのですが、どのような施設を考えていらっしゃるのでしょうか。","respondent":"勝亦総務課長","answer":"いじめ問題に関しまして、教育委員会等々その他の関係機関ということで、例えば警察。それから、家庭の問題があるような場合ですと、児童相談所ですとか子ども家庭支援センター、そういったところとも情報共有、連絡調整はしていきたいと考えています。","voiceIndex":36,"id":"exchange-012"},{"speaker":"澤田委員","kind":"質問・要望","question":"今おっしゃっていた児童相談所とかというのは、いじめと関わってくるかなと思うので、ぜひお願いしたいのと、ら・るーととかぐるっぽとか、今いじめとかは、知的障害、発達障害とかのグレーゾーンとか言われる子どもたちが遭う確率というのがかなり高いみたいで、ぜひそういう子どもたちや保護者の方との連携というか、そこでの相談受付というのも強化していただけたらなと考えています。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-013"},{"speaker":"松本委員","kind":"質問","question":"賛成します。少し意見だけ。それに対して、区長部局としてどう対応するのかというところは、非常に大きな問題になると思いますので、今回の補正予算については私どもも賛成いたしますけれども、体制をどう整備していくかというところは、これからの大きな課題だと思いますので、決算特別委員会等でまたやり取りさせていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-014"}]},{"id":"topic-02","title":"令和５年度都区財政調整","agenda":"令和５年度都区財政調整","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"一般質問でも財調の話が出てきましたけれども、そのときに、私としてはびっくりするような発言だったのですけれども、児童相談所の運営を都区の連携・協力で一層円滑に進めるということは当たり前のことですが、それはもう東京都でこれだけやってきているのですから当たり前のことですが、その中で、一般質問で話が出ましたが、子どものためだからお金の話をしている場合ではないと。","respondent":"遠藤財政課長","answer":"東京都のほうでも幾つかのものについては、どうしてもこれはというようなところがそれぞれ考え方が違ったりというところがありますけれども、少しでも多くの、こちらの算定を認めてもらうというところで努力していますので、こちらにつきましても。","voiceIndex":54,"id":"exchange-015"}]},{"id":"topic-03","title":"品川区いじめ問題調査委員会による調査結果","agenda":"品川区いじめ問題調査委員会による調査結果","exchanges":[{"speaker":"須貝委員","kind":"確認","question":"調査結果を見て、学校、教育委員会、特に最初の段階ですか、「令和２年に区立中学校生徒に対し、机に『しね』などと書かれた紙片の投入等が繰り返しあり、学校は直ちにこれをいじめと認定した」とありますけれども、私は、現場の先生はこういう対処をできるように教育を受けていると思うのです。学校の言い分もあると思うのです。ここまで言われたら、教育長の責任になってしまうわけではないですか。","respondent":"勝亦総務課長","answer":"そういった中で、重大事態としての認識が学校・教育委員会として、認識が間違っていたということで、こうした対応の遅れにつながった部分があるということは考えてあります。","voiceIndex":61,"id":"exchange-016"},{"speaker":"須貝委員","kind":"質問・要望","question":"今、品川区、小中一貫校が幾つかありますけれども、本当に広くて廊下もかなり長くて、先生の目が行き届かないところもたくさんあるではないですか。「お前立ってろ」と言うこともできない。まして、お尻をたたくこともできない。もう先生は何もできない状態で、今必死になって教えていると。そういうことも考えると、何か対処してほしいなというふうに思います。もし何か一言ありましたら、お願いいたします。","respondent":"勝亦総務課長","answer":"そういった意味で、今カメラというお話を受けまして、できる対応にどういったものがあるか。さらに教育委員会と連携して、検討していきたいと思います。","voiceIndex":63,"id":"exchange-017"},{"speaker":"松本委員","kind":"質問・要望","question":"先ほど少し補正予算のところでも触れた問題で、実際には教育委員会にも話しをしないといけない問題なので、あくまで区長部局との関係でお伺いしたいのですけれども、今回の総務委員会に出されている資料ですが、こちらの事案の概要のところの、「令和２年に区立中学校生徒に対し、机に『しね』などと書かれた紙片の投入等が繰り返しあり」というところですが、調査報告書の調査の概要ですと。","respondent":"勝亦総務課長","answer":"確かに法律的な考え方の中では、「ころす」というアクションが脅迫、恐喝等につながるものがあるのかなというふうには認識しております。","voiceIndex":66,"id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"先ほど私は言ったのであれなのですが、１点だけ。」という方だっていらっしゃるわけではないですか。民間企業だって当たり前です。親御さんに対しても、こういうことがあった場合はフォローできるとかはっきり言うべきだと思うのです。その先に区もどういうフォローの仕方があるかということをやっていかないと、この問題はもう解決できない。お願いだけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-019"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"僕が小学校、中学校にいたときというのは、学校というのは本当に聖域で、基本的にいろいろなことが起こったとしても、絶対に外部の人間など入れない、自分たちで解決する。警察など絶対入れないとそういう矜持が教師にもすごくあって、それは一面よかったところもあったのでしょうけれども、１０年ぐらい前ですか。大津のいじめ問題。そういう位置づけなのか、その辺のところを教えていただきたい。","respondent":"勝亦総務課長","answer":"その案件に対しまして、対応をそれぞれが取っていくような部分がありますので、定期的、日常的に情報共有して、対応について協議をしていく場を設けていきたいと考えています。","voiceIndex":72,"id":"exchange-020"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"今回、調査委員会から、品川区の教育にとっては厳しい報告内容を頂いているのですけれども、それによって新しい展開となったものが、ともするとこういうことはお互いに牽制し合ってしまうことになりがちなので、ネガティブな事案から始まると。そうならないように、よりよい品川区になっていくように努力していただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-021"}]},{"id":"topic-04","title":"教育委員会委員候補者（保護者枠）の公募結果","agenda":"教育委員会委員候補者（保護者枠）の公募結果","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"ここだけでなくても公募委員というものはあるわけですが、それは別で、教育委員とかほかの方々もあるわけですが、区が推薦する方もいらっしゃるわけですが、それもそういう意味で言うと、それの公募ということもこれから出てくるという理解なのか、どういう感じで。これは保護者枠だからこれだけやったという理解でいいのかどうか、そこら辺だけ教えていただけますか。","respondent":"勝亦総務課長","answer":"保護者枠以外の教育委員につきましては、その他今、法律の方ですとか、地域に詳しい方ですとか、そういった専門的な方に入っていただいておりますけれども、今後公募をしていくかどうかについては、現段階では未定です。","voiceIndex":79,"id":"exchange-022"}]},{"id":"topic-05","title":"（仮称）ジェンダー平等を推進するための条例に盛り込むべき考え方に関するパブリックコメントの実施","agenda":"（仮称）ジェンダー平等を推進するための条例に盛り込むべき考え方に関するパブリックコメントの実施","exchanges":[{"speaker":"澤田委員","kind":"質問","question":"私から質問したいことが何点かあるのですが、まずこのパブリックコメントですけれども、対象年齢というか何歳ぐらいから何歳ぐらいまでやるというのはあるのでしょうか。この間、区民、小学生にもアンケートを取りましたけれども、子どもたちがどう思っているかというのも、ぜひ聞いていただけたらなと。一部分においては難しい部分もあるのですが、その辺についてはどうお考えでしょうか。","respondent":"加島人権啓発課長","answer":"ご質問の趣旨からはずれるかもしれませんが、検討委員会のほうから「子どもについてもジェンダー平等の条例というのは大変大切なものになってくると思うので、しっかり周知を図っていってほしい」というようなご意見をいただいたところです。","voiceIndex":85,"id":"exchange-023"},{"speaker":"澤田委員","kind":"質問","question":"こちらも年齢に関連するのですが、経緯・目的の中で、性的マイノリティをカミングアウトされた場合に変わらずに接することについて、「できない」「わからない」という回答がとても多いみたいですが、その回答をした年齢というのも、例えば、割と高齢の方だったら拒否反応が強かったり、若い方だったらもう少し受入体制があったりとかということもあると思うのですけれども、しっかり検討して、調査をして。","respondent":"加島人権啓発課長","answer":"こちらの検討の経緯・目的のところに記載いたしました区民意識調査の結果ですけれども、こちらは令和元年に実施したものですが、区内在住の１８歳から８０歳未満の男女２,０００人の方で、有効回答率５０％という結果でした。","voiceIndex":87,"id":"exchange-024"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"すみません。中身の話ではなくて、これを見て、私だけかもしれないですけれども、検討の経緯・目的から読んだときに、基本理念も字を大きくしてくださって小さい部分と分けていただいているのですが、ぱっと読んだときに見づらい。もう少し色をつけていただくとか何か。黒べたでこれだけあって、字の大きさが変わると読んでいて疲れるので、何か少し検討していただきたいなと。それで結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-025"},{"speaker":"須貝委員","kind":"質問・要望","question":"ただ、基本理念の中で、７番目、女性のエンパワーメントということで、女性が強調されていますけれども、これは女性を強調するなら男性というのもどこかで文字としてクローズアップしておかないと、女性だけなのかなというような、男女平等云々をうたっているのは分かるのですけれども、そういう配慮も必要かと思うのですが、それは基本理念とは違うというふうに考えていたほうがいいのでしょうか。","respondent":"加島人権啓発課長","answer":"品川区といたしまして、この女性のエンパワーメントというのが、今の時代だからこそ、この考え方に組み込むべきものとして、ここに入れたいというふうにお示しした次第です。","voiceIndex":91,"id":"exchange-026"}]},{"id":"topic-06","title":"－I・メッセージ－ ３６０°フィードバックの試行実施","agenda":"－I・メッセージ－ ３６０°フィードバックの試行実施","exchanges":[{"speaker":"澤田委員","kind":"意見","question":"褒めていくというのはすごくいいことだと思うのですけれども、なかなか難しい部分というか慣れない部分とかもあると思うので、そういういいコメントもたくさん出て、皆さんに広まっていくといいなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":100,"id":"exchange-027"},{"speaker":"須貝委員","kind":"質問","question":"これはこれでいろいろ試行して、人材育成していくということでいいと思うのですが、現在職場の中で、管理職、それから中間管理職、それから一般の事業部の職員の方と、１か月に何度か話す、お互いに意見交換する場というのはつくられているのですか。それをお聞かせください。","respondent":"田口人材育成担当課長","answer":"今のご質問ですが、定期的に毎月１回というようなものではないのですが、基本的には係員と係長が日々の仕事を通してやり取りをするというところと、あとは年度当初のほうに目標の申告などがありますので、そのときの面談などで、１対１で話をしているような状況です。","voiceIndex":102,"id":"exchange-028"},{"speaker":"須貝委員","kind":"質問・要望","question":"それだけ人事課でも大変な時期が来たと思うのですが、そういうこれとは別に、人間関係としてそちらのほうもつくっていただきたいと思います。ぜひ、これはこれでいいのですけれども、そちらのほうも自由に意見交換ができる、言いたいことが言えるようなそういう職場環境づくりも、ぜひ築いていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-029"}]},{"id":"topic-07","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"せりざわ委員長","kind":"確認","question":"進め方として、まず、事前に配付いたしました資料を基に、私から視察先についての概要をお話しし、その後に視察先への質問、確認したい事項など、ご発言をお願いしたいと思います。こちら１６ページから３０ページに添付してありますが、ホームページのほうもご確認いただければと思います。後ほどご確認ください。視察先への質問や、確認したい事項がございましたら、この場でご発言をお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":113,"id":"exchange-030"},{"speaker":"石田（秀）委員","kind":"質問","question":"電通を辞めてなぜ四日市市に入社したのかなと思ったけれども、そういうところというのは品川区にない部分ではないですか。四日市市とか加西市なのであれですが、品川区でそういう方を発掘して、専門的な人を入れたらどうか、プラスマイナスみたいなものを行政側から質問するというのはありな気がしてなりません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":114,"id":"exchange-031"},{"speaker":"石田（秀）委員","kind":"質問","question":"これがその方という意味なのですか。我々が行く頃には影響が出だした頃ではないか。シティプロモーションは、もう一つ言うとこの方が電通にいらっしゃったというのもあるけれども、職員としてやっているというのもありますが、企業の派遣というのがあるではないですか。しながわ」というのは、品川区でしたら委託をするわけだけれども、そうではなくて任期付で採用というのも可能性があるわけではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":116,"id":"exchange-032"},{"speaker":"松本委員","kind":"質問","question":"四日市市ですけれども、シティプロモーション、すごく広い概念だと思うのですが、今回はマーケティングの観点とかということで、対外的なものと対内的なプロモーション、どちらもあると思っているのですけれども、そこのバランスをどう考えていらっしゃるのかというところを１つ伺いたいなと思います。２点目として、効果検証をどうされているのか。そことの関連で差別化ですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":118,"id":"exchange-033"},{"speaker":"石田（秀）委員","kind":"質問","question":"なぜかと言ったら人口減少を止めるために。すごく面白いやり方をしているなと思ったのだけれども、それは地方の人口減少の話だからあれですが、そういうアプローチは品川など絶対ないなと思ったから、そういうことをやったらどういうことが起こるかというのが、品川だったらどちらにしても品川にいるみたいなものだけれども、特に大学生などにそういうアプローチをしないではないですか。","respondent":"せりざわ委員長","answer":"この対応については、事前に先方にもお伝えさせていただいて進めてまいります。最後、３点目。夕食の考え方。","voiceIndex":123,"id":"exchange-034"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2278#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":44236,"voices":128}}]);
